package io.github.cheshmakzanoon.portfolio.stacks;
import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.*;
import java.util.concurrent.Semaphore;
import org.springframework.stereotype.Component;
import org.springframework.core.annotation.Order;
import org.springframework.web.filter.OncePerRequestFilter;
@Component @Order(-200)
public class AdmissionFilter extends OncePerRequestFilter {
 private final Semaphore permits=new Semaphore(32);
 @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{if(!permits.tryAcquire()){response.sendError(429);return;}try{if(request.getContentLengthLong()>65536){response.sendError(413);return;}if(SetLike.hasBody(request.getMethod())){byte[] bytes=request.getInputStream().readNBytes(65537);if(bytes.length>65536){response.sendError(413);return;}chain.doFilter(new HttpServletRequestWrapper(request){@Override public ServletInputStream getInputStream(){ByteArrayInputStream in=new ByteArrayInputStream(bytes);return new ServletInputStream(){public int read(){return in.read();}public boolean isFinished(){return in.available()==0;}public boolean isReady(){return true;}public void setReadListener(ReadListener l){throw new UnsupportedOperationException();}};}@Override public BufferedReader getReader(){return new BufferedReader(new InputStreamReader(getInputStream(),java.nio.charset.StandardCharsets.UTF_8));}@Override public int getContentLength(){return bytes.length;}@Override public long getContentLengthLong(){return bytes.length;}},response);}else chain.doFilter(request,response);}finally{permits.release();}}
 private static final class SetLike{static boolean hasBody(String method){return method.equals("POST")||method.equals("PUT")||method.equals("PATCH");}}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.apache.lucene.index.Term;
import org.apache.lucene.search.*;
public final class AuthorizationFilter {
 public record Access(String principal,String tenant,Set<String> repositories,long version,boolean administrator){public Access{if(principal==null||principal.isBlank()||tenant==null||!tenant.matches("[a-zA-Z0-9_-]{1,64}")||repositories.size()>64)throw new IllegalArgumentException("access context");repositories=Set.copyOf(repositories);}}
 private final Map<String,Access> principals=new ConcurrentHashMap<>();private final AtomicLong sequence=new AtomicLong();
 public Access update(String principal,String tenant,Set<String> repositories,boolean admin){Access a=new Access(principal,tenant,repositories,sequence.incrementAndGet(),admin);principals.put(principal,a);return a;}
 public Access current(String principal){Access a=principals.get(principal);if(a==null)throw new SecurityException("access denied");return a;}
 public boolean current(Access a){return a.equals(principals.get(a.principal()));}
 public Query apply(Query query,Access a){BooleanQuery.Builder repos=new BooleanQuery.Builder();for(String r:new TreeSet<>(a.repositories()))repos.add(new TermQuery(new Term("repository",r)),BooleanClause.Occur.SHOULD);Query permitted=a.repositories().isEmpty()?new MatchNoDocsQuery():repos.build();return new BooleanQuery.Builder().add(query,BooleanClause.Occur.MUST).add(new TermQuery(new Term("tenant",a.tenant())),BooleanClause.Occur.FILTER).add(permitted,BooleanClause.Occur.FILTER).build();}
 public void require(Access a,String tenant,String repository){if(!a.tenant().equals(tenant)||!a.repositories().contains(repository)||!current(a))throw new SecurityException("access denied");}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.util.*;
import org.apache.lucene.search.*;
public final class CandidateRetriever {
 public record Candidate(int document,String key,float score){}
 public List<Candidate> retrieve(GenerationLease lease,Query authorized)throws IOException{TopDocs hits=lease.searcher().search(authorized,500,new Sort(SortField.FIELD_SCORE,new SortField("key_sort",SortField.Type.STRING)),true);List<Candidate> out=new ArrayList<>();for(ScoreDoc h:hits.scoreDocs)out.add(new Candidate(h.doc,lease.reader().storedFields().document(h.doc).get("key"),h.score));return out;}
}

package io.github.cheshmakzanoon.portfolio.stacks;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.OptionalInt;

public final class CheckpointStore {
  private final Path root;

  public CheckpointStore(Path root) throws IOException {
    this.root = root;
    Files.createDirectories(root);
  }

  public void save(String manifest, int completed) throws IOException {
    if (completed < 0) throw new IllegalArgumentException("checkpoint");
    String payload = manifest + "\n" + completed;
    DurableFiles.atomicWrite(
        root.resolve(manifest),
        (payload + "\n" + Digests.sha256(payload)).getBytes(StandardCharsets.UTF_8));
  }

  public OptionalInt read(String manifest) throws IOException {
    Path p = root.resolve(manifest);
    if (!Files.exists(p)) return OptionalInt.empty();
    if (Files.size(p) > 1024) throw new IOException("checkpoint quota");
    String[] parts = Files.readString(p).split("\n");
    if (parts.length != 3
        || !parts[0].equals(manifest)
        || !Digests.sha256(parts[0] + "\n" + parts[1]).equals(parts[2]))
      throw new IOException("corrupt checkpoint");
    try {
      return OptionalInt.of(Integer.parseInt(parts[1]));
    } catch (NumberFormatException e) {
      throw new IOException("corrupt checkpoint", e);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.util.*;
import java.util.regex.*;
import org.apache.lucene.analysis.*;
import org.apache.lucene.analysis.tokenattributes.*;
public final class CodeIdentifierAnalyzer extends Analyzer {
 public record Part(String term,int start,int end,int position){}
 public static List<Part> parts(String input){List<Part> out=new ArrayList<>();Matcher words=Pattern.compile("[\\p{L}\\p{N}_$]+").matcher(input);int position=0;while(words.find()){String original=words.group();out.add(new Part(original.toLowerCase(Locale.ROOT),words.start(),words.end(),++position));Matcher pieces=Pattern.compile("[\\p{Lu}]+(?=[\\p{Lu}][\\p{Ll}]|[^\\p{L}]|$)|[\\p{Lu}]?[\\p{Ll}]+|[\\p{N}]+|[\\p{L}]+").matcher(original);while(pieces.find()){String p=pieces.group().toLowerCase(Locale.ROOT);if(!p.equals(original.toLowerCase(Locale.ROOT)))out.add(new Part(p,words.start()+pieces.start(),words.start()+pieces.end(),position));}}return out;}
 @Override protected TokenStreamComponents createComponents(String field){Tokenizer t=new Tokenizer(){final CharTermAttribute term=addAttribute(CharTermAttribute.class);final OffsetAttribute offset=addAttribute(OffsetAttribute.class);final PositionIncrementAttribute increment=addAttribute(PositionIncrementAttribute.class);List<Part> tokens=List.of();int at,previous,length;
 @Override public void reset()throws IOException{super.reset();StringBuilder s=new StringBuilder();char[] b=new char[4096];int n;while((n=input.read(b))!=-1)s.append(b,0,n);length=s.length();tokens=parts(s.toString());at=previous=0;}
 @Override public boolean incrementToken(){if(at>=tokens.size())return false;clearAttributes();Part p=tokens.get(at++);term.append(p.term());offset.setOffset(correctOffset(p.start()),correctOffset(p.end()));increment.setPositionIncrement(p.position()-previous);previous=p.position();return true;}
 @Override public void end()throws IOException{super.end();offset.setOffset(correctOffset(length),correctOffset(length));}};return new TokenStreamComponents(t);}
}

package io.github.cheshmakzanoon.portfolio.stacks;

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;

public final class ContentAddressedStore {
  private final Path root;

  public ContentAddressedStore(Path root) throws IOException {
    this.root = root;
    Files.createDirectories(root);
  }

  public String put(byte[] content) throws IOException {
    String h = Digests.sha256(content);
    Path p = root.resolve(h);
    if (Files.exists(p)) {
      read(h);
      return h;
    }
    DurableFiles.atomicWrite(p, content);
    return h;
  }

  public byte[] read(String digest) throws IOException {
    if (!digest.matches("[a-f0-9]{64}")) throw new IOException("invalid digest");
    Path p = root.resolve(digest);
    if (Files.size(p) > 1_048_576) throw new IOException("content too large");
    byte[] b = Files.readAllBytes(p);
    if (!Digests.sha256(b).equals(digest)) throw new IOException("content digest mismatch");
    return b;
  }

  public String text(String digest) throws IOException {
    try {
      return StandardCharsets.UTF_8
          .newDecoder()
          .onMalformedInput(CodingErrorAction.REPORT)
          .decode(java.nio.ByteBuffer.wrap(read(digest)))
          .toString();
    } catch (CharacterCodingException e) {
      throw new IOException("invalid UTF-8", e);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.stacks;

import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.HexFormat;

public final class Digests {
  private Digests() {}

  public static String sha256(byte[] data) {
    try {
      return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException(e);
    }
  }

  public static String sha256(String text) {
    return sha256(text.getBytes(StandardCharsets.UTF_8));
  }
}

package io.github.cheshmakzanoon.portfolio.stacks;
import org.apache.lucene.document.*;
import org.apache.lucene.index.IndexableField;
import java.util.*;
public final class DocumentMapper {
 private DocumentMapper(){}
 public static Document map(SourceDocument s){Document d=new Document();exact(d,"key",s.key());exact(d,"tenant",s.tenant());exact(d,"repository",s.repository());exact(d,"path",s.entry().path());exact(d,"sha256",s.entry().sha256());exact(d,"revision",s.revision());exact(d,"language",s.entry().language());exact(d,"kind",s.entry().kind());exact(d,"coordinates",s.entry().coordinates());exact(d,"version",s.entry().version());d.add(new TextField("content",s.content(),Field.Store.YES));d.add(new TextField("identifiers",String.join(" ",s.entry().symbols()),Field.Store.NO));d.add(new TextField("path_tokens",s.entry().path(),Field.Store.NO));for(String symbol:s.entry().symbols())exact(d,"symbol",symbol.toLowerCase(Locale.ROOT));d.add(new SortedDocValuesField("key_sort",new org.apache.lucene.util.BytesRef(s.key())));d.add(new StoredField("schema",SnapshotManifest.SCHEMA));return d;}
 private static void exact(Document d,String field,String value){d.add(new StringField(field,value,Field.Store.YES));}
 public static SourceDocument source(Document d){List<String> symbols=Arrays.asList(d.getValues("symbol"));return new SourceDocument(d.get("tenant"),d.get("repository"),d.get("revision"),new SnapshotManifest.Entry(d.get("path"),d.get("sha256"),d.get("language"),d.get("kind"),symbols,d.get("coordinates"),d.get("version")),d.get("content"));}
}

package io.github.cheshmakzanoon.portfolio.stacks;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.util.UUID;

public final class DurableFiles {
  private DurableFiles() {}

  public static void atomicWrite(Path path, byte[] bytes) throws IOException {
    Files.createDirectories(path.getParent());
    Path tmp = path.resolveSibling(path.getFileName() + ".tmp-" + UUID.randomUUID());
    try {
      try (FileChannel c =
          FileChannel.open(tmp, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
        ByteBuffer b = ByteBuffer.wrap(bytes);
        while (b.hasRemaining()) c.write(b);
        c.force(true);
      }
      Files.move(tmp, path, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
      syncDirectory(path.getParent());
    } finally {
      Files.deleteIfExists(tmp);
    }
  }

  public static void syncDirectory(Path p) throws IOException {
    try (FileChannel c = FileChannel.open(p, StandardOpenOption.READ)) {
      c.force(true);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.util.*;
import java.util.concurrent.RejectedExecutionException;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
@RestControllerAdvice
public class ErrorResponses {
 @ExceptionHandler(SecurityException.class) ResponseEntity<Map<String,String>> denied(){return error(403,"ACCESS_DENIED");}
 @ExceptionHandler(IngestionJob.Conflict.class) ResponseEntity<Map<String,String>> conflict(){return error(409,"IDEMPOTENCY_CONFLICT");}
 @ExceptionHandler(GenerationPublisher.RetiredGeneration.class) ResponseEntity<Map<String,String>> retired(){return error(410,"GENERATION_RETIRED");}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> invalid(){return error(400,"INVALID_REQUEST");}
 @ExceptionHandler(RejectedExecutionException.class) ResponseEntity<Map<String,String>> overload(){return error(429,"QUEUE_FULL");}
 @ExceptionHandler(IOException.class) ResponseEntity<Map<String,String>> io(){return error(422,"SOURCE_OR_STORAGE_FAILURE");}
 private ResponseEntity<Map<String,String>> error(int status,String code){return ResponseEntity.status(status).body(Map.of("error",code));}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.BooleanSupplier;
import org.apache.lucene.analysis.Analyzer;
import org.apache.lucene.index.*;
import org.apache.lucene.store.*;
public final class GenerationBuilder {
 public enum Boundary {BUILD_START, DOCUMENT, BEFORE_COMMIT, AFTER_COMMIT, AFTER_WARM, AFTER_RENAME, BEFORE_POINTER, AFTER_POINTER, RETIRE}
 @FunctionalInterface public interface Fault {void at(Boundary boundary)throws IOException;static Fault none(){return boundary->{};}}
 public record Built(String id,Path path,String manifestHash,int count){}
 private final Path root;private final ContentAddressedStore cas;private final CheckpointStore checkpoints;
 public GenerationBuilder(Path root,ContentAddressedStore cas)throws IOException{this.root=root;this.cas=cas;this.checkpoints=new CheckpointStore(root.resolve("checkpoints"));Files.createDirectories(root.resolve("staging"));}
 public Built build(SnapshotManifest manifest,List<SourceDocument> previous,Fault fault,BooleanSupplier cancelled)throws IOException {String id=UUID.randomUUID().toString();Path dir=root.resolve("staging").resolve(id);Files.createDirectory(dir);fault.at(Boundary.BUILD_START);Map<String,SourceDocument> docs=new TreeMap<>();for(SourceDocument old:previous)docs.put(old.key(),old);String prefix=manifest.tenantId()+"/"+manifest.repositoryId()+"/";Set<String> uploaded=new HashSet<>();for(var e:manifest.entries())uploaded.add(prefix+e.path());if(manifest.complete())for(String key:docs.keySet())if(key.startsWith(prefix)&&!uploaded.contains(key)&&!manifest.deletions().contains(key.substring(prefix.length())))throw new IOException("complete snapshot requires explicit deletions");for(String deleted:manifest.deletions())docs.remove(prefix+deleted);for(var e:manifest.entries())docs.put(prefix+e.path(),new SourceDocument(manifest.tenantId(),manifest.repositoryId(),manifest.revision(),e,cas.text(e.sha256())));if(docs.size()>100_000)throw new IOException("tenant document quota");String hash=manifest.digest();try(Directory fs=FSDirectory.open(dir);Analyzer analyzer=new CodeIdentifierAnalyzer();IndexWriter writer=new IndexWriter(fs,new IndexWriterConfig(analyzer).setOpenMode(IndexWriterConfig.OpenMode.CREATE))){int n=0;for(SourceDocument s:docs.values()){if(cancelled.getAsBoolean()||Thread.currentThread().isInterrupted())throw new IOException("cancelled");writer.addDocument(DocumentMapper.map(s));fault.at(Boundary.DOCUMENT);if(++n%1000==0)checkpoints.save(hash,n);}writer.setLiveCommitData(Map.of("manifest",hash,"schema",Integer.toString(SnapshotManifest.SCHEMA),"count",Integer.toString(docs.size()),"generation",id).entrySet());fault.at(Boundary.BEFORE_COMMIT);writer.commit();fault.at(Boundary.AFTER_COMMIT);}DurableFiles.atomicWrite(dir.resolve("manifest.bin"),manifest.bytes());try(Directory fs=FSDirectory.open(dir);DirectoryReader r=DirectoryReader.open(fs)){if(r.numDocs()!=docs.size())throw new IOException("count mismatch");new org.apache.lucene.search.IndexSearcher(r).count(new org.apache.lucene.search.MatchAllDocsQuery());}fault.at(Boundary.AFTER_WARM);DurableFiles.atomicWrite(dir.resolve("generation.sha256"),checksum(dir).getBytes(StandardCharsets.UTF_8));return new Built(id,dir,hash,docs.size());}
 public static String checksum(Path dir)throws IOException {StringBuilder b=new StringBuilder();try(var files=Files.list(dir)){for(Path p:files.filter(Files::isRegularFile).filter(p->!p.getFileName().toString().equals("generation.sha256")&&!p.getFileName().toString().equals("write.lock")).sorted().toList())b.append(p.getFileName()).append(':').append(Digests.sha256(Files.readAllBytes(p))).append('\n');}return Digests.sha256(b.toString());}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.search.IndexSearcher;
public final class GenerationLease implements AutoCloseable {
 private final String id;private final DirectoryReader reader;private final Runnable release;private final AtomicBoolean closed=new AtomicBoolean();
 GenerationLease(String id,DirectoryReader reader,Runnable release){this.id=id;this.reader=reader;this.release=release;}
 public String id(){return id;}
 public IndexSearcher searcher(){if(closed.get())throw new IllegalStateException("closed lease");return new IndexSearcher(reader);}
 public DirectoryReader reader(){if(closed.get())throw new IllegalStateException("closed lease");return reader;}
 @Override public void close(){if(closed.compareAndSet(false,true))release.run();}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.apache.lucene.search.*;
class GenerationLifecycleTest {
 @TempDir Path root;
 SnapshotManifest manifest(ContentAddressedStore cas,String revision,int count)throws IOException {List<SnapshotManifest.Entry> entries=new ArrayList<>();for(int i=0;i<count;i++){String text="public void method"+i+"() {} revision "+revision;entries.add(new SnapshotManifest.Entry("src/A"+i+".java",cas.put(text.getBytes(StandardCharsets.UTF_8)),"java","source",List.of("method"+i),"g:a","1"));}return new SnapshotManifest("t","r",revision,false,entries,Set.of());}
 @Test void committedGenerationsHaveAtomicSnapshotAndLeaseLifetime()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var builder=new GenerationBuilder(index,cas);try(var publisher=new GenerationPublisher(index)){var one=builder.build(manifest(cas,"one",4),List.of(),GenerationBuilder.Fault.none(),()->false);publisher.publish(one,GenerationBuilder.Fault.none());GenerationLease old=publisher.acquire();assertEquals(4,old.searcher().count(new MatchAllDocsQuery()));var two=builder.build(manifest(cas,"two",6),publisher.sources(),GenerationBuilder.Fault.none(),()->false);publisher.publish(two,GenerationBuilder.Fault.none());assertEquals(one.id(),old.id());assertEquals(4,old.reader().numDocs());try(var lease=publisher.acquire()){assertEquals(two.id(),lease.id());assertEquals(6,lease.reader().numDocs());}assertThrows(GenerationPublisher.RetiredGeneration.class,()->publisher.acquire(one.id()));old.close();old.close();assertThrows(IllegalStateException.class,old::searcher);}try(var recovered=new GenerationPublisher(index);var lease=recovered.acquire()){assertEquals(6,lease.reader().numDocs());assertEquals("two",recovered.sources().getFirst().revision());}}
 @Test void explicitDeletionsAndPartialUploadsRespectSnapshotContract()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var builder=new GenerationBuilder(index,cas);try(var publisher=new GenerationPublisher(index)){var m=manifest(cas,"one",3);publisher.publish(builder.build(m,List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());var partial=new SnapshotManifest("t","r","partial",false,List.of(m.entries().getFirst()),Set.of());publisher.publish(builder.build(partial,publisher.sources(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());assertEquals(3,publisher.sources().size());var invalid=new SnapshotManifest("t","r","full",true,List.of(m.entries().getFirst()),Set.of());assertThrows(IOException.class,()->builder.build(invalid,publisher.sources(),GenerationBuilder.Fault.none(),()->false));var full=new SnapshotManifest("t","r","full",true,List.of(m.entries().getFirst()),Set.of("src/A1.java","src/A2.java"));publisher.publish(builder.build(full,publisher.sources(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());assertEquals(1,publisher.sources().size());}}
 @Test void hundredSeededFailureSchedulesNeverExposeMixedGenerations()throws Exception{Random random=new Random(7007);var boundaries=GenerationBuilder.Boundary.values();for(int schedule=0;schedule<100;schedule++){Path run=root.resolve("schedule-"+schedule);var cas=new ContentAddressedStore(run.resolve("cas"));Path index=run.resolve("index");var builder=new GenerationBuilder(index,cas);var chosen=boundaries[random.nextInt(boundaries.length)];try(var publisher=new GenerationPublisher(index)){publisher.publish(builder.build(manifest(cas,"old",3),List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());GenerationBuilder.Fault failure=at->{if(at==chosen)throw new IOException("seeded failure "+at);};try{publisher.publish(builder.build(manifest(cas,"new",5),publisher.sources(),failure,()->false),failure);}catch(IOException expected){assertTrue(expected.getMessage().contains("seeded failure"));}}try(var recovered=new GenerationPublisher(index);var lease=recovered.acquire()){int n=lease.reader().numDocs();assertTrue(n==3||n==5,"schedule "+schedule);Set<String> revisions=new HashSet<>();recovered.sources().forEach(d->revisions.add(d.revision()));assertEquals(Set.of(n==3?"old":"new"),revisions,"schedule "+schedule);}}}
 @Test void corruptCurrentPointerFallsBackAndStagingIsQuarantined()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var b=new GenerationBuilder(index,cas);String previous;try(var p=new GenerationPublisher(index)){p.publish(b.build(manifest(cas,"old",2),List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());previous=p.currentId();p.publish(b.build(manifest(cas,"new",3),p.sources(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());}Files.writeString(index.resolve("CURRENT"),"corrupt");Files.createDirectory(index.resolve("staging/incomplete"));Files.writeString(index.resolve("staging/incomplete/corrupt"),"metadata");try(var p=new GenerationPublisher(index)){assertEquals(previous,p.currentId());assertEquals(2,p.sources().size());}try(var files=Files.list(index.resolve("quarantine"))){assertEquals(2,files.count());}}
 @Test void cancellationAndSimulatedEnospcPreserveLastCommittedReader()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var b=new GenerationBuilder(index,cas);try(var p=new GenerationPublisher(index)){p.publish(b.build(manifest(cas,"old",2),List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());String old=p.currentId();assertThrows(IOException.class,()->b.build(manifest(cas,"cancel",3),p.sources(),GenerationBuilder.Fault.none(),()->true));assertThrows(IOException.class,()->p.publish(b.build(manifest(cas,"disk",3),p.sources(),GenerationBuilder.Fault.none(),()->false),at->{if(at==GenerationBuilder.Boundary.BEFORE_POINTER)throw new FileSystemException(index.toString(),null,"No space left on device (injected ENOSPC)");}));assertEquals(old,p.currentId());assertEquals(2,p.sources().size());}}
 @Test void identifierTokenizerPreservesOriginalAndOffsetsWithUnicode()throws Exception{var parts=CodeIdentifierAnalyzer.parts("HTTPServer snake_case caféValue");assertTrue(parts.stream().anyMatch(p->p.term().equals("httpserver")&&p.start()==0&&p.end()==10));assertTrue(parts.stream().anyMatch(p->p.term().equals("http")));assertTrue(parts.stream().anyMatch(p->p.term().equals("server")));assertTrue(parts.stream().anyMatch(p->p.term().equals("snake")));assertTrue(parts.stream().anyMatch(p->p.term().equals("case")));assertTrue(parts.stream().anyMatch(p->p.term().equals("café")));try(var analyzer=new CodeIdentifierAnalyzer();var tokens=analyzer.tokenStream("content","fooBar")){var term=tokens.addAttribute(org.apache.lucene.analysis.tokenattributes.CharTermAttribute.class);var position=tokens.addAttribute(org.apache.lucene.analysis.tokenattributes.PositionIncrementAttribute.class);tokens.reset();List<String> values=new ArrayList<>();while(tokens.incrementToken()){values.add(term.toString());assertTrue(position.getPositionIncrement()>=0);}tokens.end();assertEquals(List.of("foobar","foo","bar"),values);}}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.apache.lucene.index.*;
import org.apache.lucene.store.*;
public final class GenerationPublisher implements AutoCloseable {
 private static final class Handle {final String id;final Directory directory;final DirectoryReader reader;int leases;boolean retired;Handle(String id,Directory d,DirectoryReader r){this.id=id;directory=d;reader=r;}}
 private final Path root;private final Map<String,Handle> handles=new HashMap<>();private String current;private boolean closed;
 public GenerationPublisher(Path root)throws IOException{this.root=root;Files.createDirectories(root.resolve("generations"));Files.createDirectories(root.resolve("quarantine"));Files.createDirectories(root.resolve("staging"));recover();}
 private void recover()throws IOException {for(String pointer:List.of("CURRENT","PREVIOUS")){Path p=root.resolve(pointer);if(!Files.exists(p))continue;try{String id=readPointer(p);Handle h=open(id);handles.put(id,h);current=id;if(pointer.equals("PREVIOUS"))DurableFiles.atomicWrite(root.resolve("CURRENT"),pointer(id));break;}catch(IOException|IllegalArgumentException ignored){Files.move(p,root.resolve("quarantine").resolve(pointer+"-"+UUID.randomUUID()),StandardCopyOption.ATOMIC_MOVE);}}
 try(var staged=Files.list(root.resolve("staging"))){for(Path p:staged.toList())Files.move(p,root.resolve("quarantine").resolve(p.getFileName()+"-incomplete"),StandardCopyOption.ATOMIC_MOVE);}}
