package io.github.cheshmakzanoon.portfolio.stacks;

import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.BooleanSupplier;
import java.util.zip.*;

public final class SafeSourceReader {
  public record Limits(long fileBytes, long totalBytes, int entries, int expansionRatio) {
    public Limits {
      if (fileBytes < 1
          || fileBytes > 1_048_576
          || totalBytes < 1
          || entries < 1
          || expansionRatio < 1) throw new IllegalArgumentException("limits");
    }

    public static Limits defaults() {
      return new Limits(1_048_576, 256L * 1024 * 1024, 100_000, 100);
    }
  }

  private final Path root;
  private final Limits limits;
  private final ContentAddressedStore store;

  public SafeSourceReader(Path configuredRoot, Limits limits, ContentAddressedStore store)
      throws IOException {
    root = configuredRoot.toRealPath();
    if (!Files.isDirectory(root)) throw new IOException("root is not directory");
    this.limits = limits;
    this.store = store;
  }

  public SnapshotManifest directory(
      String tenant,
      String repo,
      String revision,
      Path selected,
      boolean complete,
      Set<String> deleted,
      BooleanSupplier cancelled)
      throws IOException {
    Path base = resolve(selected);
    List<SnapshotManifest.Entry> entries = new ArrayList<>();
    long total = 0;
    try (var paths = Files.walk(base)) {
      for (Path p : paths.sorted().toList()) {
        checkCancelled(cancelled);
        if (Files.isSymbolicLink(p)) throw new IOException("symlinks prohibited");
        if (Files.isDirectory(p)) continue;
        if (!Files.isRegularFile(p, LinkOption.NOFOLLOW_LINKS))
          throw new IOException("not a regular file");
        resolve(p);
        byte[] b = bounded(Files.newInputStream(p), limits.fileBytes());
        total = Math.addExact(total, b.length);
        if (total > limits.totalBytes() || entries.size() >= limits.entries())
          throw new IOException("snapshot quota");
        entries.add(entry(base.relativize(p).toString().replace('\\', '/'), b));
      }
    }
    return new SnapshotManifest(tenant, repo, revision, complete, entries, deleted);
  }

  public SnapshotManifest archive(
      String tenant, String repo, String revision, Path selected, BooleanSupplier cancelled)
      throws IOException {
    Path archive = resolve(selected);
    if (Files.isSymbolicLink(selected)) throw new IOException("symlinks prohibited");
    long compressed = Files.size(archive);
    if (compressed > limits.totalBytes()) throw new IOException("archive quota");
    List<SnapshotManifest.Entry> entries = new ArrayList<>();
    Set<String> names = new HashSet<>();
    long total = 0;
    try (ZipInputStream zip =
        new ZipInputStream(Files.newInputStream(archive), StandardCharsets.UTF_8)) {
      ZipEntry z;
      while ((z = zip.getNextEntry()) != null) {
        checkCancelled(cancelled);
        String name;
        try {
          name = SnapshotManifest.normalize(z.getName().replaceAll("/$", ""));
        } catch (IllegalArgumentException e) {
          throw new IOException("unsafe archive path", e);
        }
        if (!names.add(name) || names.size() > limits.entries())
          throw new IOException("archive entry quota or duplicate");
        if (z.isDirectory()) continue;
        byte[] b = bounded(zip, limits.fileBytes());
        total += b.length;
        if (total > limits.totalBytes()
            || total > Math.max(1, compressed) * limits.expansionRatio())
          throw new IOException("archive expansion quota");
        entries.add(entry(name, b));
      }
    }
    return new SnapshotManifest(tenant, repo, revision, false, entries, Set.of());
  }

  private Path resolve(Path path) throws IOException {
    Path p = path.isAbsolute() ? path : root.resolve(path);
    if (!p.normalize().startsWith(root)) throw new IOException("path escape");
    Path current = root;
    for (Path part : root.relativize(p.normalize())) {
      current = current.resolve(part);
      if (Files.isSymbolicLink(current)) throw new IOException("symlinks prohibited");
    }
    Path real = p.toRealPath();
    if (!real.startsWith(root)) throw new IOException("path escape");
    return real;
  }

  private SnapshotManifest.Entry entry(String path, byte[] bytes) throws IOException {
    String text;
    try {
      text =
          StandardCharsets.UTF_8
              .newDecoder()
              .onMalformedInput(CodingErrorAction.REPORT)
              .onUnmappableCharacter(CodingErrorAction.REPORT)
              .decode(ByteBuffer.wrap(bytes))
              .toString();
    } catch (CharacterCodingException e) {
      throw new IOException("invalid UTF-8", e);
    }
    List<String> symbols = new ArrayList<>();
    var matcher = java.util.regex.Pattern.compile("[\\p{L}_$][\\p{L}\\p{N}_$]*").matcher(text);
    while (matcher.find() && symbols.size() < 256) {
      String s = matcher.group();
      if (s.length() <= 256 && !symbols.contains(s)) symbols.add(s);
    }
    return new SnapshotManifest.Entry(
        path,
        store.put(bytes),
        path.endsWith(".java") ? "java" : "text",
        path.endsWith(".java") ? "source" : "documentation",
        symbols,
        "",
        "");
  }

  private static byte[] bounded(InputStream in, long max) throws IOException {
    try {
      ByteArrayOutputStream b = new ByteArrayOutputStream();
      byte[] buffer = new byte[8192];
      int n;
      long size = 0;
      while ((n = in.read(buffer)) != -1) {
        size += n;
        if (size > max) throw new IOException("file quota");
        b.write(buffer, 0, n);
      }
      return b.toByteArray();
    } finally {
      if (!(in instanceof ZipInputStream)) in.close();
    }
  }

  private static void checkCancelled(BooleanSupplier c) throws IOException {
    if (c.getAsBoolean() || Thread.currentThread().isInterrupted())
      throw new IOException("cancelled");
  }
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.springframework.core.env.Environment;
import org.springframework.http.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
@RestController
public class SearchController implements AutoCloseable {
 public record IngestRequest(String repository,String revision,String idempotencyKey,String path,boolean archive,boolean complete,Set<String> deletions){}
 public record SuggestRequest(String prefix){}
 private final SearchEngine engine;private final AuthorizationFilter auth;private final Path sources;private final ThreadPoolExecutor workers=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(8),Thread.ofPlatform().name("stacks-ingest-",0).factory(),new ThreadPoolExecutor.AbortPolicy());private final ConcurrentMap<String,Future<?>> futures=new ConcurrentHashMap<>();private final ConcurrentMap<String,String> states=new ConcurrentHashMap<>();private final AtomicLong searches=new AtomicLong(),failures=new AtomicLong();
 public SearchController(SearchEngine engine,AuthorizationFilter auth,Environment env)throws IOException{this.engine=engine;this.auth=auth;sources=Path.of(env.getProperty("stacks.sources",".runtime/sources"));Files.createDirectories(sources);}
 private AuthorizationFilter.Access context(Jwt jwt,boolean write){if(jwt==null)throw new SecurityException("access denied");var a=auth.current(jwt.getSubject());if(!a.tenant().equals(jwt.getClaimAsString("tenant"))||(write&&!Arrays.asList(jwt.getClaimAsString("scope").split(" ")).contains("ingest")))throw new SecurityException("access denied");return a;}
 @GetMapping("/health") Map<String,String> health(){return Map.of("status","UP");}
 @PostMapping("/v1/search") SearchEngine.Response search(@AuthenticationPrincipal Jwt jwt,@RequestBody SearchEngine.Request request)throws IOException{var a=context(jwt,false);searches.incrementAndGet();return engine.search(a.principal(),request);}
 @PostMapping("/v1/suggest") List<String> suggest(@AuthenticationPrincipal Jwt jwt,@RequestBody SuggestRequest request)throws IOException{return engine.suggest(context(jwt,false).principal(),request.prefix());}
 @PostMapping("/v1/ingestions") ResponseEntity<Map<String,String>> ingest(@AuthenticationPrincipal Jwt jwt,@RequestBody IngestRequest request)throws IOException{var a=context(jwt,true);auth.require(a,a.tenant(),request.repository());if(request.path()==null||request.revision()==null||request.idempotencyKey()==null)throw new IllegalArgumentException("missing ingestion field");SafeSourceReader reader=new SafeSourceReader(sources,SafeSourceReader.Limits.defaults(),engine.contentStore());SnapshotManifest manifest=request.archive()?reader.archive(a.tenant(),request.repository(),request.revision(),Path.of(request.path()),()->false):reader.directory(a.tenant(),request.repository(),request.revision(),Path.of(request.path()),request.complete(),request.deletions()==null?Set.of():request.deletions(),()->false);var job=engine.register(a,request.idempotencyKey(),manifest);synchronized(futures){if(!futures.containsKey(job.id())&&!engine.completed(job.id())){FutureTask<Void> task=new FutureTask<>(()->{states.put(job.id(),"RUNNING");try{engine.ingest(a,request.idempotencyKey(),manifest,GenerationBuilder.Fault.none(),Thread.currentThread()::isInterrupted);states.put(job.id(),"COMPLETE");}catch(Exception e){states.put(job.id(),Thread.currentThread().isInterrupted()?"CANCELLED":"FAILED");failures.incrementAndGet();}return null;});states.put(job.id(),"QUEUED");workers.execute(task);futures.put(job.id(),task);}}return ResponseEntity.accepted().body(Map.of("id",job.id(),"state",engine.completed(job.id())?"COMPLETE":states.getOrDefault(job.id(),"REGISTERED")));}
 @GetMapping("/v1/ingestions/{id}") Map<String,String> job(@AuthenticationPrincipal Jwt jwt,@PathVariable String id)throws IOException{engine.job(context(jwt,false),id);return Map.of("id",id,"state",engine.completed(id)?"COMPLETE":states.getOrDefault(id,"REGISTERED"));}
 @DeleteMapping("/v1/ingestions/{id}") Map<String,String> cancel(@AuthenticationPrincipal Jwt jwt,@PathVariable String id)throws IOException{engine.job(context(jwt,true),id);Future<?> f=futures.get(id);if(f!=null&&f.cancel(true))states.put(id,"CANCELLED");return Map.of("id",id,"state",states.getOrDefault(id,"REGISTERED"));}
 @PostMapping("/v1/reindexes") Map<String,String> reindex(@AuthenticationPrincipal Jwt jwt)throws IOException{engine.reindex(context(jwt,true));return Map.of("state","COMPLETE");}
 @GetMapping("/v1/metrics") Map<String,Long> metrics(@AuthenticationPrincipal Jwt jwt){if(!context(jwt,false).administrator())throw new SecurityException("access denied");return Map.of("searches",searches.get(),"jobFailures",failures.get(),"queuedJobs",(long)workers.getQueue().size());}
 @Override public void close(){workers.shutdownNow();}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
public final class SearchCursor {
 public record Position(String generation,int offset){}
 private final byte[] key;private final Clock clock;
 public SearchCursor(byte[] key,Clock clock){if(key.length<32)throw new IllegalArgumentException("cursor key");this.key=key.clone();this.clock=clock;}
 public String encode(AuthorizationFilter.Access a,String digest,String generation,int offset){String payload=a.tenant()+"\n"+a.principal()+"\n"+a.version()+"\n"+digest+"\n"+generation+"\n"+offset+"\n"+(clock.instant().getEpochSecond()+300);byte[] b=payload.getBytes(StandardCharsets.UTF_8);return Base64.getUrlEncoder().withoutPadding().encodeToString(b)+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(sign(b));}
 public Position decode(String token,AuthorizationFilter.Access a,String digest){if(token==null||token.length()>2048)throw new IllegalArgumentException("cursor");try{String[] pieces=token.split("\.");if(pieces.length!=2)throw new IllegalArgumentException("cursor");byte[] b=Base64.getUrlDecoder().decode(pieces[0]);if(!MessageDigest.isEqual(sign(b),Base64.getUrlDecoder().decode(pieces[1])))throw new IllegalArgumentException("cursor signature");String[] p=new String(b,StandardCharsets.UTF_8).split("\n");if(p.length!=7||!p[0].equals(a.tenant())||!p[1].equals(a.principal())||Long.parseLong(p[2])!=a.version()||!p[3].equals(digest)||Long.parseLong(p[6])<=clock.instant().getEpochSecond()||!p[4].matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("cursor context");int offset=Integer.parseInt(p[5]);if(offset<0||offset>500)throw new IllegalArgumentException("cursor offset");return new Position(p[4],offset);}catch(RuntimeException e){throw new IllegalArgumentException("invalid cursor");}}
 private byte[] sign(byte[] data){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return mac.doFinal(data);}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
}

package io.github.cheshmakzanoon.portfolio.stacks;
import java.io.*;
import java.nio.file.*;
import java.time.*;
