public final class SearchEngine implements AutoCloseable {
 public record Request(String text,int pageSize,String cursor,Map<String,String> filters){public Request{if(pageSize<1||pageSize>100)throw new IllegalArgumentException("page size");filters=filters==null?Map.of():Map.copyOf(filters);if(filters.size()>8||filters.entrySet().stream().anyMatch(e->!Set.of("repository","language","kind","coordinates","version").contains(e.getKey())||e.getValue().length()>256))throw new IllegalArgumentException("filter");}}
 public record Hit(String key,String path,String repository,String sha256,float score,String snippet,String explanation){}
 public record Response(String generationId,String scoringVersion,long totalHits,String relation,List<Hit> results,Map<String,Integer> facets,String cursor){}
 private final Path root;private final ContentAddressedStore cas;private final IngestionJob jobs;private final Map<String,GenerationPublisher> publishers=new ConcurrentHashMap<>();private final AuthorizationFilter authorization;private final SearchCursor cursors;
 public SearchEngine(Path root,AuthorizationFilter authorization)throws IOException {this.root=root;Files.createDirectories(root);this.authorization=authorization;cas=new ContentAddressedStore(root.resolve("cas"));jobs=new IngestionJob(root.resolve("jobs"));Files.createDirectories(root.resolve("index"));try(var tenants=Files.list(root.resolve("index"))){for(Path tenant:tenants.filter(Files::isDirectory).toList()){String name=tenant.getFileName().toString();if(!name.matches("[a-zA-Z0-9_-]{1,64}"))throw new IOException("invalid tenant directory");publishers.put(name,new GenerationPublisher(tenant));}}Path secret=root.resolve("cursor.key");if(!Files.exists(secret)){byte[] key=new byte[32];new SecureRandom().nextBytes(key);DurableFiles.atomicWrite(secret,key);try{Files.setPosixFilePermissions(secret,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));}catch(UnsupportedOperationException ignored){}}cursors=new SearchCursor(Files.readAllBytes(secret),Clock.systemUTC());}
 public ContentAddressedStore contentStore(){return cas;}
 public synchronized GenerationPublisher generations(String tenant)throws IOException{if(!tenant.matches("[a-zA-Z0-9_-]{1,64}"))throw new IllegalArgumentException("tenant");GenerationPublisher p=publishers.get(tenant);if(p==null){p=new GenerationPublisher(root.resolve("index").resolve(tenant));publishers.put(tenant,p);}return p;}
 public IngestionJob.Registered register(AuthorizationFilter.Access a,String key,SnapshotManifest m)throws IOException{authorization.require(a,m.tenantId(),m.repositoryId());return jobs.register(key,m);}
 public boolean completed(String id){return id.matches("[a-f0-9]{64}")&&Files.exists(root.resolve("jobs").resolve(id+".done"));}
 public synchronized IngestionJob.Registered ingest(AuthorizationFilter.Access a,String key,SnapshotManifest m,GenerationBuilder.Fault fault,BooleanSupplier cancelled)throws IOException {authorization.require(a,m.tenantId(),m.repositoryId());IngestionJob.Registered job=jobs.register(key,m);Path done=root.resolve("jobs").resolve(job.id()+".done");if(Files.exists(done))return job;GenerationPublisher publisher=generations(a.tenant());GenerationBuilder builder=new GenerationBuilder(root.resolve("index").resolve(a.tenant()),cas);var built=builder.build(m,publisher.sources(),fault,cancelled);authorization.require(a,m.tenantId(),m.repositoryId());publisher.publish(built,fault);DurableFiles.atomicWrite(done,built.id().getBytes(java.nio.charset.StandardCharsets.UTF_8));return job;}
