 public Response search(String principal,Request request)throws IOException{return search(principal,request,QueryPlanner.Mode.SOURCE_AWARE);}
 public Response search(String principal,Request request,QueryPlanner.Mode mode)throws IOException {QueryAst ast=QueryAst.parse(request.text());String digest=Digests.sha256(request.text()+"\n"+new TreeMap<>(request.filters())+"\n"+request.pageSize()+"\n"+mode);for(int retry=0;retry<3;retry++){AuthorizationFilter.Access a=authorization.current(principal);SearchCursor.Position position=request.cursor()==null?null:cursors.decode(request.cursor(),a,digest);try(GenerationLease lease=generations(a.tenant()).acquire(position==null?null:position.generation())){BooleanQuery.Builder qb=new BooleanQuery.Builder().add(new QueryPlanner().plan(ast,mode),BooleanClause.Occur.MUST);for(var f:request.filters().entrySet())qb.add(new TermQuery(new Term(f.getKey(),f.getValue())),BooleanClause.Occur.FILTER);Query authorized=authorization.apply(qb.build(),a);var ranked=new Ranker().rank(new CandidateRetriever().retrieve(lease,authorized));int start=position==null?0:position.offset(),end=Math.min(ranked.size(),start+request.pageSize());if(start>ranked.size())throw new IllegalArgumentException("cursor offset");List<Hit> hits=new ArrayList<>();for(var c:ranked.subList(start,end)){var d=lease.reader().storedFields().document(c.document());hits.add(new Hit(c.key(),d.get("path"),d.get("repository"),d.get("sha256"),c.score(),SnippetBuilder.snippet(d.get("content"),request.text()),lease.searcher().explain(authorized,c.document()).toString()));}long count=lease.searcher().count(authorized);Map<String,Integer> facets=new TreeMap<>();for(String repo:new TreeSet<>(a.repositories())){Query q=new BooleanQuery.Builder().add(authorized,BooleanClause.Occur.MUST).add(new TermQuery(new Term("repository",repo)),BooleanClause.Occur.FILTER).build();int n=lease.searcher().count(q);if(n>0)facets.put(repo,n);}String next=end<ranked.size()?cursors.encode(a,digest,lease.id(),end):null;Response response=new Response(lease.id(),mode==QueryPlanner.Mode.BASELINE?"bm25-content-v1":QueryPlanner.VERSION,count,"EQUAL_TO",List.copyOf(hits),Map.copyOf(facets),next);if(authorization.current(a))return response;}}throw new SecurityException("authorization changed; retry");}
 public List<String> suggest(String principal,String prefix)throws IOException {if(prefix==null||!prefix.matches("[\\p{L}\\p{N}_$]{1,64}"))throw new IllegalArgumentException("prefix");for(int retry=0;retry<3;retry++){var a=authorization.current(principal);try(var lease=generations(a.tenant()).acquire()){Query q=authorization.apply(new PrefixQuery(new Term("symbol",prefix.toLowerCase(Locale.ROOT))),a);List<String> out=new ArrayList<>();for(var c:new CandidateRetriever().retrieve(lease,q)){var d=lease.reader().storedFields().document(c.document());for(String symbol:d.getValues("symbol"))if(symbol.startsWith(prefix.toLowerCase(Locale.ROOT))&&!out.contains(symbol)&&out.size()<20)out.add(symbol);}Collections.sort(out);if(authorization.current(a))return List.copyOf(out);}}throw new SecurityException("authorization changed; retry");}
