chEngine.Request("shared",2,cursor,Map.of())));assertEquals(0,e.search("alice",request).totalHits());assertThrows(SecurityException.class,()->e.ingest(alice,"denied",manifest(e,"tenant1","denied",1,"x"),GenerationBuilder.Fault.none(),()->false));assertTrue(Files.isDirectory(root.resolve("index/tenant1")));assertTrue(Files.isDirectory(root.resolve("index/tenant2")));}}
