package io.github.cheshmakzanoon.portfolio.daybook;

import java.util.*;
import javax.crypto.spec.SecretKeySpec;
import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.*;
import org.springframework.context.annotation.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.oauth2.core.*;
import org.springframework.security.oauth2.jose.jws.MacAlgorithm;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.security.web.SecurityFilterChain;

@SpringBootApplication
public class DaybookApplication {
  public static void main(String[] args) {
    SpringApplication.run(DaybookApplication.class, args);
  }

  @Bean
  LedgerStore ledgerStore(org.springframework.core.env.Environment env) {
    String url =
        env.getProperty(
            "ledger.url",
            System.getenv()
                .getOrDefault("LEDGER_URL", "jdbc:postgresql://127.0.0.1:18101/daybook"));
    if ("true".equals(System.getenv("LEDGER_MIGRATE")))
      LedgerStore.migrate(
          url,
          "postgres",
          System.getenv().getOrDefault("LEDGER_ADMIN_PASSWORD", "local-only-admin"));
    return new LedgerStore(
        url,
        "daybook_runtime",
        System.getenv().getOrDefault("LEDGER_PASSWORD", "local-only-daybook"));
  }

  @Bean
  JwtDecoder decoder(org.springframework.core.env.Environment env) {
    String issuer = env.getProperty("ledger.issuer", "http://127.0.0.1:18109/dev-issuer");
    boolean dev = env.acceptsProfiles(org.springframework.core.env.Profiles.of("dev"));
    if (dev) {
      String address = env.getProperty("server.address", "127.0.0.1");
      if (!Set.of("127.0.0.1", "::1", "localhost").contains(address))
        throw new IllegalStateException("DEV_REQUIRES_LOOPBACK");
      var decoder =
          NimbusJwtDecoder.withSecretKey(
                  new SecretKeySpec(
                      "daybook-disposable-local-demo-key-32-bytes"
                          .getBytes(java.nio.charset.StandardCharsets.UTF_8),
                      "HmacSHA256"))
              .macAlgorithm(MacAlgorithm.HS256)
              .build();
      decoder.setJwtValidator(validators(issuer));
      return decoder;
    }
    return protectedDecoder(issuer);
  }

  public static JwtDecoder protectedDecoder(String issuer) {
    var d = (NimbusJwtDecoder) JwtDecoders.fromIssuerLocation(issuer);
    d.setJwtValidator(validators(issuer));
    return d;
  }

  static OAuth2TokenValidator<Jwt> validators(String issuer) {
    return new DelegatingOAuth2TokenValidator<>(
        JwtValidators.createDefaultWithIssuer(issuer),
        jwt -> {
          try {
            UUID.fromString(jwt.getClaimAsString("tenant"));
            if (!jwt.getAudience().contains("daybook")
                || jwt.getExpiresAt() == null
                || jwt.getSubject() == null) throw new IllegalArgumentException();
            return OAuth2TokenValidatorResult.success();
          } catch (RuntimeException e) {
            return OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"));
          }
        });
  }

  @Bean
  SecurityFilterChain security(HttpSecurity h) throws Exception {
    return h.csrf(c -> c.disable())
        .authorizeHttpRequests(
            a ->
                a.requestMatchers("/health")
                    .permitAll()
                    .requestMatchers("/v1/reports/**")
                    .hasAuthority("SCOPE_ledger.admin")
                    .requestMatchers("/v1/reconciliation/**", "/v1/statements/**")
                    .hasAuthority("SCOPE_ledger.reconcile")
                    .requestMatchers(org.springframework.http.HttpMethod.GET, "/v1/**")
                    .hasAuthority("SCOPE_ledger.read")
                    .requestMatchers("/v1/**")
                    .hasAuthority("SCOPE_ledger.write")
                    .anyRequest()
                    .denyAll())
        .oauth2ResourceServer(o -> o.jwt(j -> {}))
        .build();
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import java.time.*;
import java.util.*;
import org.springframework.http.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;

@RestController
public class LedgerController {
  private final LedgerStore store;
  private final Reconciliation reconciliation;
  private final Projector projector;

  public LedgerController(LedgerStore s) {
    store = s;
    reconciliation = new Reconciliation(s);
    projector = new Projector(s);
  }

  UUID tenant(Jwt principal) {
    return UUID.fromString(principal.getClaimAsString("tenant"));
  }

  public record AccountInput(String currency, Journal.Side normalSide, String name) {}

  public record LineInput(UUID account, Journal.Side side, String amount) {}

  public record JournalInput(
      UUID period, LocalDate date, String currency, String reference, List<LineInput> lines) {
    Journal journal() {
      if (lines == null || lines.size() > 100) throw new IllegalArgumentException("BATCH_BOUND");
      return new Journal(
          period,
          date,
          currency,
          reference,
          lines.stream()
              .map(
                  l ->
                      new Journal.Line(
                          l.account(), l.side(), Money.parse(currency, l.amount()).minor()))
              .toList());
    }
  }

  public record ReversalInput(LocalDate date) {}

  public record Decision(UUID journal, int line, String reason, String evidence) {}

  @GetMapping("/health")
  Map<String, String> health() {
    return Map.of("status", "UP");
  }

  @PostMapping("/v1/accounts")
  Map<String, UUID> account(@AuthenticationPrincipal Jwt p, @RequestBody AccountInput in) {
    return Map.of("id", store.account(tenant(p), in.currency(), in.normalSide(), in.name()));
  }

  @PostMapping("/v1/journals")
  Map<String, UUID> post(
      @AuthenticationPrincipal Jwt p,
      @RequestHeader("Idempotency-Key") String key,
      @RequestBody JournalInput in) {
    return Map.of("journalId", store.post(tenant(p), key, in.journal()));
  }

  @PostMapping("/v1/journals/{id}/reversals")
  Map<String, UUID> reverse(
      @AuthenticationPrincipal Jwt p,
      @PathVariable UUID id,
      @RequestHeader("Idempotency-Key") String key,
      @RequestBody ReversalInput in) {
    return Map.of("journalId", store.reverse(tenant(p), id, key, in.date()));
  }

  @GetMapping("/v1/requests/{key}")
  List<Map<String, String>> request(@AuthenticationPrincipal Jwt p, @PathVariable String key) {
    return store.receipt(tenant(p), key);
  }

  @PostMapping("/v1/periods/{id}/close")
  Map<String, String> close(@AuthenticationPrincipal Jwt p, @PathVariable UUID id) {
    store.close(tenant(p), id);
    return Map.of("status", "CLOSED");
  }

  @GetMapping("/v1/accounts/{id}/statement")
  Map<String, Object> statement(
      @AuthenticationPrincipal Jwt p,
      @PathVariable UUID id,
      @RequestParam(defaultValue = "1900-01-01") LocalDate afterDate,
      @RequestParam(defaultValue = "00000000-0000-0000-0000-000000000000") UUID afterId,
      @RequestParam(defaultValue = "0") int afterLine,
      @RequestParam(required = false) Instant boundary,
      @RequestParam(required = false) String snapshot,
      @RequestParam(defaultValue = "100") int limit) {
    var cutoff = boundary == null ? Instant.now() : boundary;
    var visibility = snapshot == null ? store.visibilitySnapshot() : snapshot;
    var rows =
        store.statement(tenant(p), id, afterDate, afterId, afterLine, cutoff, visibility, limit);
    return Map.of(
        "consistency",
        "immutable source filtered by PostgreSQL transaction visibility snapshot; stable across pages",
        "snapshot",
        visibility,
        "boundary",
        cutoff,
        "account",
        id,
        "summary",
        store.statementSummary(tenant(p), id, cutoff, visibility),
        "rows",
        rows,
        "next",
        rows.isEmpty()
            ? Map.of()
            : Map.of(
                "afterDate",
                rows.getLast().get("effective_date"),
                "afterId",
                rows.getLast().get("id"),
                "afterLine",
                rows.getLast().get("line_no")),
        "filters",
        Map.of("limit", limit));
  }

  @PostMapping(value = "/v1/statements", consumes = "text/csv")
  Map<String, UUID> ingest(@AuthenticationPrincipal Jwt p, @RequestBody byte[] csv) {
    return Map.of("importId", reconciliation.ingest(tenant(p), csv));
  }

  @GetMapping("/v1/reconciliation/{id}")
  List<Map<String, String>> rows(@AuthenticationPrincipal Jwt p, @PathVariable UUID id) {
    return reconciliation.rows(tenant(p), id);
  }

  @PostMapping("/v1/reconciliation/{id}/{row}/resolve")
  Map<String, String> resolve(
      @AuthenticationPrincipal Jwt p,
      @PathVariable UUID id,
      @PathVariable int row,
      @RequestBody Decision d) {
    reconciliation.resolve(
        tenant(p), id, row, d.journal(), d.line(), p.getSubject(), d.reason(), d.evidence());
    return Map.of("status", "MATCHED");
  }

  @GetMapping(value = "/v1/reconciliation/{id}/export", produces = "text/csv")
  String export(@AuthenticationPrincipal Jwt p, @PathVariable UUID id) {
    return reconciliation.export(tenant(p), id);
  }

  @GetMapping("/v1/reports/accounts/{id}")
  Map<String, Object> report(@AuthenticationPrincipal Jwt p, @PathVariable UUID id) {
    return projector.report(tenant(p), id);
  }

  @PostMapping("/v1/reports/replay")
  Map<String, UUID> replay() {
    return Map.of("generation", projector.replay());
  }

  @GetMapping("/v1/reports/freshness")
  Map<String, Object> freshness() {
    return projector.freshness();
  }

  @ExceptionHandler({IllegalArgumentException.class, NullPointerException.class})
  ResponseEntity<Map<String, String>> invalid(RuntimeException e) {
    return ResponseEntity.unprocessableContent()
        .body(
            Map.of(
                "code",
                e instanceof NullPointerException
                    ? "MISSING_FIELD"
                    : e.getMessage() == null ? "INVALID_INPUT" : e.getMessage()));
  }

  @ExceptionHandler(LedgerStore.LedgerException.class)
  ResponseEntity<Map<String, String>> db(LedgerStore.LedgerException e) {
    return ResponseEntity.status(
            e.temporary
                ? 503
                : e.code.contains("CONFLICT") || e.code.contains("REVERSED") ? 409 : 422)
        .body(
            Map.of(
                "code", e.code, "retry", e.temporary ? "same key after backoff" : "correct input"));
  }

  @ExceptionHandler({
    org.springframework.http.converter.HttpMessageNotReadableException.class,
    org.springframework.web.method.annotation.MethodArgumentTypeMismatchException.class,
    org.springframework.web.bind.MissingRequestHeaderException.class
  })
  ResponseEntity<Map<String, String>> malformed(Exception e) {
    return ResponseEntity.badRequest().body(Map.of("code", "MALFORMED_REQUEST"));
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/** Bounds actual bytes, including chunked requests, before JSON/CSV deserialization. */
@Component
public final class RequestBoundsFilter extends OncePerRequestFilter {
  protected void doFilterInternal(
      HttpServletRequest request, HttpServletResponse response, FilterChain chain)
      throws ServletException, IOException {
    if (!request.getRequestURI().startsWith("/v1/") || !request.getMethod().equals("POST")) {
      chain.doFilter(request, response);
      return;
    }
    byte[] bytes = request.getInputStream().readNBytes(1048577);
    if (bytes.length > 1048576) {
      response.setStatus(413);
      response.setContentType("application/json");
      response.getWriter().write("{\"code\":\"REQUEST_BYTE_BOUND\"}");
      return;
    }
    if (request.getContentType() != null
        && request.getContentType().startsWith("application/json")) {
      int depth = 0;
      boolean quoted = false, escaped = false;
      for (byte raw : bytes) {
        char ch = (char) (raw & 255);
        if (quoted) {
          if (escaped) escaped = false;
          else if (ch == '\\') escaped = true;
          else if (ch == '"') quoted = false;
        } else if (ch == '"') quoted = true;
        else if (ch == '{' || ch == '[') {
          if (++depth > 64) {
            response.setStatus(422);
            response.setContentType("application/json");
            response.getWriter().write("{\"code\":\"NESTING_BOUND\"}");
            return;
          }
        } else if (ch == '}' || ch == ']') depth--;
      }
    }
    chain.doFilter(
        new HttpServletRequestWrapper(request) {
          public ServletInputStream getInputStream() {
            var input = new ByteArrayInputStream(bytes);
            return new ServletInputStream() {
              public int read() {
                return input.read();
              }

              public boolean isFinished() {
                return input.available() == 0;
              }

              public boolean isReady() {
                return true;
              }

              public void setReadListener(ReadListener listener) {
                throw new UnsupportedOperationException("synchronous adapter");
              }
            };
          }

          public BufferedReader getReader() {
            return new BufferedReader(
                new InputStreamReader(getInputStream(), StandardCharsets.UTF_8));
          }
        },
        response);
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import java.math.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;

public record Journal(
    UUID period, LocalDate date, String currency, String reference, List<Line> lines) {
  public enum Side {
    DEBIT,
    CREDIT;

    public Side opposite() {
      return this == DEBIT ? CREDIT : DEBIT;
    }
  }

  public record Line(UUID account, Side side, BigInteger minor) {
    public Line {
      Objects.requireNonNull(account);
      Objects.requireNonNull(side);
      if (minor == null || minor.signum() <= 0 || minor.compareTo(Money.MAX) > 0)
        throw new IllegalArgumentException("POSITIVE_BOUNDED_AMOUNT");
    }
  }

  public Journal {
    Objects.requireNonNull(period);
    Objects.requireNonNull(date);
    if (!Money.SCALES.containsKey(currency)) throw new IllegalArgumentException("CURRENCY");
    if (reference == null || reference.length() > 120)
      throw new IllegalArgumentException("REFERENCE");
    lines = List.copyOf(lines);
    if (lines.size() < 2 || lines.size() > 100) throw new IllegalArgumentException("BATCH_BOUND");
    var debit = BigInteger.ZERO;
    var credit = BigInteger.ZERO;
    for (var l : lines)
      if (l.side() == Side.DEBIT) debit = debit.add(l.minor());
      else credit = credit.add(l.minor());
    if (!debit.equals(credit) || debit.compareTo(Money.MAX) > 0)
      throw new IllegalArgumentException("UNBALANCED_OR_OVERFLOW");
  }

  public Journal reversed(LocalDate when) {
    return new Journal(
        period,
        when,
        currency,
        "reversal:" + digest(),
        lines.stream().map(l -> new Line(l.account(), l.side().opposite(), l.minor())).toList());
  }

  public String digest() {
    try {
      var s =
          period
              + "|"
              + date
              + "|"
              + currency
              + "|"
              + reference
              + "|"
              + lines.stream()
                  .map(l -> l.account() + ":" + l.side() + ":" + l.minor())
                  .sorted()
                  .toList();
      return HexFormat.of()
          .formatHex(
              MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException(e);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import java.math.*;
import java.util.Map;

public record Money(String currency, BigInteger minor) {
  public static final Map<String, Integer> SCALES = Map.of("CAD", 2, "USD", 2, "JPY", 0);
  public static final BigInteger MAX = new BigInteger("999999999999999999999999999999");

  public Money {
    if (currency == null || !SCALES.containsKey(currency))
      throw new IllegalArgumentException("CURRENCY");
    if (minor == null || minor.abs().compareTo(MAX) > 0)
      throw new IllegalArgumentException("AMOUNT_BOUND");
  }

  public static Money parse(String currency, String decimal) {
    if (currency == null
        || decimal == null
        || decimal.length() > 64
        || !decimal.matches("-?(0|[1-9][0-9]*)(\\.[0-9]+)?")
        || !SCALES.containsKey(currency)) throw new IllegalArgumentException("DECIMAL");
    var d = new BigDecimal(decimal);
    if (d.scale() > SCALES.get(currency)) throw new IllegalArgumentException("SCALE");
    return new Money(currency, d.movePointRight(SCALES.get(currency)).toBigIntegerExact());
  }

  public String decimal() {
    return new BigDecimal(minor, SCALES.get(currency)).toPlainString();
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Independent debit/credit summation oracle; credit-normal presentation reverses the signed sum.
 */
public final class ReferenceLedger {
  private final Map<UUID, BigInteger> debitTotals = new HashMap<>();
  private final Map<UUID, BigInteger> creditTotals = new HashMap<>();

  public void apply(Journal journal) {
    var debitDelta = new HashMap<UUID, BigInteger>();
    var creditDelta = new HashMap<UUID, BigInteger>();
    for (var line : journal.lines()) {
      (line.side() == Journal.Side.DEBIT ? debitDelta : creditDelta)
          .merge(line.account(), line.minor(), BigInteger::add);
    }
    debitDelta.replaceAll((id, delta) -> debitTotals.getOrDefault(id, BigInteger.ZERO).add(delta));
    creditDelta.replaceAll(
        (id, delta) -> creditTotals.getOrDefault(id, BigInteger.ZERO).add(delta));
    if (java.util.stream.Stream.concat(debitDelta.values().stream(), creditDelta.values().stream())
        .anyMatch(n -> n.compareTo(Money.MAX) > 0))
      throw new IllegalArgumentException("BALANCE_BOUND");
    debitTotals.putAll(debitDelta);
    creditTotals.putAll(creditDelta);
  }

  public Map<UUID, BigInteger> balances() {
    var result = new HashMap<>(debitTotals);
    creditTotals.forEach((id, value) -> result.merge(id, value.negate(), BigInteger::add));
    return Map.copyOf(result);
  }

  public BigInteger displayed(UUID id, Journal.Side normal) {
    return balances()
        .getOrDefault(id, BigInteger.ZERO)
        .multiply(normal == Journal.Side.DEBIT ? BigInteger.ONE : BigInteger.ONE.negate());
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import java.math.*;
import java.security.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.*;
import org.flywaydb.core.Flyway;

public final class LedgerStore implements AutoCloseable {
  private final com.zaxxer.hikari.HikariDataSource pool;
  private final java.util.concurrent.atomic.AtomicLong retries =
      new java.util.concurrent.atomic.AtomicLong();

  public long retryCount() {
    return retries.get();
  }

  public record Failure(String code, boolean temporary) {}

  public static final class LedgerException extends RuntimeException {
    public final String code;
    public final boolean temporary;

    LedgerException(String c, boolean t, Throwable e) {
      super(c, e);
      code = c;
      temporary = t;
    }
  }

  private final String url, user, password;

  public LedgerStore(String url, String user, String password) {
    this(url, user, password, 32);
  }

  public LedgerStore(String url, String user, String password, int poolSize) {
    this.url = url;
    this.user = user;
    this.password = password;
    var config = new com.zaxxer.hikari.HikariConfig();
    config.setJdbcUrl(url);
    config.setUsername(user);
    config.setPassword(password);
    config.setMaximumPoolSize(poolSize);
    config.setMinimumIdle(0);
    config.setConnectionTimeout(15000);
    config.setInitializationFailTimeout(-1);
    config.setPoolName("daybook-" + UUID.randomUUID());
    pool = new com.zaxxer.hikari.HikariDataSource(config);
  }

  public void close() {
    pool.close();
  }

  public static void migrate(String url, String user, String password) {
    Flyway.configure()
        .dataSource(url, user, password)
        .locations("classpath:db/migration")
        .load()
        .migrate();
  }

  @FunctionalInterface
  public interface SqlWork<T> {
    T run(Connection c) throws SQLException;
  }

  public <T> T tx(SqlWork<T> work) {
    for (int attempt = 0; attempt < 12; attempt++) {
      try (var c = pool.getConnection()) {
        c.setAutoCommit(false);
        c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);
        try (var st = c.createStatement()) {
          st.execute("SET LOCAL statement_timeout='15s'");
          st.execute("SET LOCAL lock_timeout='10s'");
        }
        try {
          T result = work.run(c);
          c.commit();
          return result;
        } catch (SQLException | RuntimeException e) {
          c.rollback();
          throw e;
        }
      } catch (SQLException e) {
        if (("40001".equals(e.getSQLState())
                || "40P01".equals(e.getSQLState())
                || "55P03".equals(e.getSQLState())
                || "23505".equals(e.getSQLState()))
            && attempt < 11) {
          try {
            retries.incrementAndGet();
            Thread.sleep(Math.min(100, 2L * (attempt + 1)));
          } catch (InterruptedException x) {
            Thread.currentThread().interrupt();
            throw new LedgerException("INTERRUPTED", true, x);
          }
          continue;
        }
        throw new LedgerException(
            e.getSQLState() != null && e.getSQLState().startsWith("P0")
                ? (e instanceof org.postgresql.util.PSQLException pg
                        && pg.getServerErrorMessage() != null
                    ? pg.getServerErrorMessage().getMessage()
                    : "POSTING_REJECTED")
                : "DATABASE_REJECTED",
            e instanceof SQLTransientException
                || "40001".equals(e.getSQLState())
                || "40P01".equals(e.getSQLState())
                || "55P03".equals(e.getSQLState())
                || "57014".equals(e.getSQLState())
                || e.getSQLState() != null && e.getSQLState().startsWith("08"),
            e);
      }
    }
    throw new IllegalStateException();
  }

  public static int execute(Connection c, String sql, Object... args) throws SQLException {
    try (var p = c.prepareStatement(sql)) {
      bind(p, args);
      return p.executeUpdate();
    }
  }

  public static List<Map<String, String>> query(Connection c, String sql, Object... args)
      throws SQLException {
    try (var p = c.prepareStatement(sql)) {
      bind(p, args);
      try (var r = p.executeQuery()) {
        var list = new ArrayList<Map<String, String>>();
        while (r.next()) {
          var m = new LinkedHashMap<String, String>();
          for (int i = 1; i <= r.getMetaData().getColumnCount(); i++)
            m.put(r.getMetaData().getColumnLabel(i), r.getString(i));
          list.add(m);
        }
        return list;
      }
    }
  }

  private static void bind(PreparedStatement p, Object[] args) throws SQLException {
    for (int i = 0; i < args.length; i++) p.setObject(i + 1, args[i]);
  }

  public UUID account(UUID tenant, String currency, Journal.Side normal, String name) {
    if (!Money.SCALES.containsKey(currency)
        || name == null
        || name.isBlank()
        || name.length() > 120) throw new IllegalArgumentException("ACCOUNT_INPUT");
    var id = UUID.randomUUID();
    return tx(
        c -> {
          execute(
              c,
              "INSERT INTO ledger.account VALUES(?,?,?,?,?)",
              tenant,
              id,
              currency,
              normal.name(),
              name);
          return id;
        });
  }

  public UUID post(UUID tenant, String key, Journal j) {
    return post(tenant, key, j, null);
  }

  public UUID post(UUID tenant, String key, Journal j, UUID reversal) {
    if (key == null || key.isBlank() || key.length() > 120)
      throw new IllegalArgumentException("KEY_BOUND");
    var id = UUID.randomUUID();
    return tx(c -> postOn(c, tenant, key, j, reversal, id));
  }

  public static UUID postOn(
      Connection c, UUID tenant, String key, Journal j, UUID reversal, UUID id)
      throws SQLException {
    var json = new StringBuilder("[");
    for (var l : j.lines()) {
      if (json.length() > 1) json.append(',');
      json.append("{\"account\":\"")
          .append(l.account())
          .append("\",\"side\":\"")
          .append(l.side())
          .append("\",\"amount\":\"")
          .append(l.minor())
          .append("\"}");
    }
    json.append(']');
    try (var p = c.prepareStatement("SELECT ledger.post_journal(?,?,?,?,?,?,?,?,?::jsonb,?,?)")) {
      bind(
          p,
          new Object[] {
            tenant,
            key,
            j.digest(),
            id,
            j.period(),
            j.date(),
            j.currency(),
            j.reference(),
            json.toString(),
            reversal,
            reversal == null ? "POST" : "REVERSE"
          });
      try (var r = p.executeQuery()) {
        r.next();
        return r.getObject(1, UUID.class);
      }
    }
  }

  public UUID reverse(UUID tenant, UUID original, String key, LocalDate date) {
    return tx(
        c -> {
          var rows =
              query(
                  c,
                  "SELECT j.period_id,j.currency,j.reference,p.account_id,p.side,p.amount FROM ledger.journal j JOIN ledger.posting p ON p.tenant_id=j.tenant_id AND p.journal_id=j.id WHERE j.tenant_id=? AND j.id=? ORDER BY p.line_no",
                  tenant,
                  original);
          if (rows.isEmpty()) throw new IllegalArgumentException("JOURNAL_NOT_FOUND");
          var first = rows.getFirst();
          var lines =
              rows.stream()
                  .map(
                      r ->
                          new Journal.Line(
                              UUID.fromString(r.get("account_id")),
                              Journal.Side.valueOf(r.get("side")).opposite(),
                              new BigInteger(r.get("amount"))))
                  .toList();
          var journal =
              new Journal(
                  UUID.fromString(first.get("period_id")),
                  date,
                  first.get("currency"),
                  "reversal:" + original,
                  lines);
          return postOn(c, tenant, key, journal, original, UUID.randomUUID());
        });
  }

  public void close(UUID tenant, UUID period) {
    tx(
        c -> {
          query(c, "SELECT ledger.close_period(?,?)", tenant, period);
          return null;
        });
  }

  public List<Map<String, String>> receipt(UUID tenant, String key) {
    return tx(
        c ->
            query(
                c,
                "SELECT operation,response FROM ledger.idempotency_receipt WHERE tenant_id=? AND key=? ORDER BY operation",
                tenant,
                key));
  }

  /**
   * Cursor is the last journal date/id/line and fixed recorded-at boundary; later requests preserve
   * it.
   */
  public String visibilitySnapshot() {
    return tx(c -> query(c, "SELECT pg_current_snapshot() AS snapshot").getFirst().get("snapshot"));
  }

  public List<Map<String, String>> statement(
      UUID tenant,
      UUID account,
      LocalDate afterDate,
      UUID afterId,
      int afterLine,
      Instant boundary,
      String snapshot,
      int limit) {
    if (snapshot == null || snapshot.length() > 16384 || !snapshot.matches("[0-9]+:[0-9]+:[0-9,]*"))
      throw new IllegalArgumentException("SNAPSHOT_BOUND");
    if (limit < 1 || limit > 200) throw new IllegalArgumentException("PAGE_BOUND");
    return tx(
        c ->
            query(
                c,
                "SELECT j.id,j.effective_date,j.recorded_at,j.currency,j.reference,p.line_no,p.side,p.amount::text FROM ledger.journal j JOIN ledger.posting p ON j.tenant_id=p.tenant_id AND j.id=p.journal_id WHERE p.tenant_id=? AND p.account_id=? AND pg_visible_in_snapshot(j.recorded_xid,?::pg_snapshot) AND j.recorded_at<=? AND (j.effective_date,j.id,p.line_no)>(?,?,?) ORDER BY j.effective_date,j.id,p.line_no LIMIT ?",
                tenant,
                account,
                snapshot,
                java.sql.Timestamp.from(boundary),
                afterDate,
                afterId,
                afterLine,
                limit));
  }

  public Map<String, String> statementSummary(
      UUID tenant, UUID account, Instant boundary, String snapshot) {
    return tx(
        c -> {
          var accounts =
              query(
                  c,
                  "SELECT currency,normal_side FROM ledger.account WHERE tenant_id=? AND id=?",
                  tenant,
                  account);
          if (accounts.isEmpty()) return Map.of();
          var sums =
              query(
                  c,
                  "SELECT coalesce(sum(CASE p.side WHEN 'DEBIT' THEN p.amount ELSE 0 END),0)::text AS debits,coalesce(sum(CASE p.side WHEN 'CREDIT' THEN p.amount ELSE 0 END),0)::text AS credits FROM ledger.posting p JOIN ledger.journal j ON j.tenant_id=p.tenant_id AND j.id=p.journal_id WHERE p.tenant_id=? AND p.account_id=? AND pg_visible_in_snapshot(j.recorded_xid,?::pg_snapshot) AND j.recorded_at<=?",
                  tenant,
                  account,
                  snapshot,
                  java.sql.Timestamp.from(boundary));
          var accountInfo = accounts.getFirst();
          var totals = sums.getFirst();
          var signed =
              new BigInteger(totals.get("debits")).subtract(new BigInteger(totals.get("credits")));
          var presented = accountInfo.get("normal_side").equals("DEBIT") ? signed : signed.negate();
          return Map.of(
              "currency",
              accountInfo.get("currency"),
              "normalSide",
              accountInfo.get("normal_side"),
              "debitsMinor",
              totals.get("debits"),
              "creditsMinor",
              totals.get("credits"),
              "normalBalanceMinor",
              presented.toString(),
              "normalBalanceDecimal",
              new Money(accountInfo.get("currency"), presented).decimal());
        });
  }

  public List<Map<String, String>> balances(UUID tenant) {
    return tx(
        c ->
            query(
                c,
                "SELECT a.id,a.currency,a.normal_side,coalesce(b.debits,0)::text AS debits,coalesce(b.credits,0)::text AS credits FROM ledger.account a LEFT JOIN ledger.account_balance b ON b.tenant_id=a.tenant_id AND b.account_id=a.id WHERE a.tenant_id=? ORDER BY a.id",
                tenant));
  }
}

package io.github.cheshmakzanoon.portfolio.daybook;

import java.sql.*;
import java.util.*;

/** Per-event membership, never sequence MAX: an earlier allocated ID can commit later. */
public final class Projector {
  private final LedgerStore store;

  public Projector(LedgerStore s) {
    store = s;
  }

  public UUID active() {
    return store.tx(
        c ->
            UUID.fromString(
                LedgerStore.query(c, "SELECT generation FROM ledger.projection_head")
                    .getFirst()
                    .get("generation")));
  }

  public int drain(UUID generation) {
    int n = 0;
    while (true) {
      int batch =
          store.tx(
              c -> {
                var events =
                    LedgerStore.query(
                        c,
                        "SELECT e.id,e.tenant_id,e.journal_id FROM ledger.outbox_event e WHERE NOT EXISTS(SELECT FROM ledger.projection_checkpoint p WHERE p.generation=? AND p.event_id=e.id) ORDER BY e.id LIMIT 100",
                        generation);
                int count = 0;
                for (var e : events) {
                  int inserted =
                      LedgerStore.execute(
                          c,
                          "INSERT INTO ledger.projection_checkpoint(generation,event_id) VALUES(?,?) ON CONFLICT DO NOTHING",
                          generation,
                          Long.valueOf(e.get("id")));
                  if (inserted == 0) continue;
                  LedgerStore.execute(
                      c,
                      "INSERT INTO ledger.reporting_balance SELECT ?,tenant_id,account_id,sum(CASE side WHEN 'DEBIT' THEN amount ELSE 0 END),sum(CASE side WHEN 'CREDIT' THEN amount ELSE 0 END) FROM ledger.posting WHERE tenant_id=? AND journal_id=? GROUP BY tenant_id,account_id ON CONFLICT(generation,tenant_id,account_id) DO UPDATE SET debits=ledger.reporting_balance.debits+excluded.debits,credits=ledger.reporting_balance.credits+excluded.credits",
                      generation,
                      UUID.fromString(e.get("tenant_id")),
                      UUID.fromString(e.get("journal_id")));
                  count++;
                }
                return count;
              });
      n += batch;
      if (batch == 0) return n;
    }
  }

  public long pending() {
    return store.tx(
        c ->
            Long.valueOf(
                LedgerStore.query(
                        c,
                        "SELECT count(*) AS n FROM ledger.outbox_event e WHERE NOT EXISTS(SELECT FROM ledger.projection_checkpoint p JOIN ledger.projection_head h ON h.generation=p.generation WHERE p.event_id=e.id)")
                    .getFirst()
                    .get("n")));
  }

  private static UUID generationOn(Connection c) throws SQLException {
    return UUID.fromString(
        LedgerStore.query(c, "SELECT generation FROM ledger.projection_head")
            .getFirst()
            .get("generation"));
  }

  private static long pendingOn(Connection c, UUID generation) throws SQLException {
    return Long.parseLong(
        LedgerStore.query(
                c,
                "SELECT count(*) AS n FROM ledger.outbox_event e WHERE NOT EXISTS(SELECT FROM ledger.projection_checkpoint p WHERE p.generation=? AND p.event_id=e.id)",
                generation)
            .getFirst()
            .get("n"));
  }

  public Map<String, Object> freshness() {
    return store.tx(
        c -> {
          var generation = generationOn(c);
          return Map.of(
              "generation",
              generation,
              "pendingEvents",
              pendingOn(c, generation),
              "authoritative",
              false,
              "snapshot",
              LedgerStore.query(c, "SELECT pg_current_snapshot() AS snapshot")
                  .getFirst()
                  .get("snapshot"));
        });
  }

  public Map<String, Object> report(UUID tenant, UUID account) {
    return store.tx(
        c -> {
          var generation = generationOn(c);
          var rows =
              LedgerStore.query(
                  c,
                  "SELECT a.id,a.currency,a.normal_side,coalesce(r.debits,0)::text AS debits_minor,coalesce(r.credits,0)::text AS credits_minor FROM ledger.account a LEFT JOIN ledger.reporting_balance r ON r.tenant_id=a.tenant_id AND r.account_id=a.id AND r.generation=? WHERE a.tenant_id=? AND a.id=?",
                  generation,
                  tenant,
                  account);
          return Map.of(
              "generation",
              generation,
              "authoritative",
              false,
              "pendingEvents",
              pendingOn(c, generation),
              "balances",
              rows,
              "snapshot",
              LedgerStore.query(c, "SELECT pg_current_snapshot() AS snapshot")
                  .getFirst()
                  .get("snapshot"));
        });
  }

  public UUID replay() {
    var shadow = UUID.randomUUID();
    drain(shadow);
    store.tx(
        c -> {
          LedgerStore.query(c, "SELECT ledger.promote_shadow(?)", shadow);
          return null;
        });
    return shadow;
  }

  public static void main(String[] args) throws Exception {
    var s =
        new LedgerStore(
            System.getenv()
                .getOrDefault("LEDGER_URL", "jdbc:postgresql://localhost:18101/daybook"),
            "daybook_runtime",
            System.getenv().getOrDefault("LEDGER_PASSWORD", "local-only-daybook"));
    var p = new Projector(s);
    if (args.length > 0 && args[0].equals("replay")) {
      System.out.println(p.replay());
      return;
    }
    do {
      p.drain(p.active());
      Thread.sleep(500);
    } while (true);
  }
}

package io.github.cheshmakzanoon.portfolio.handoff;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.*;
import java.util.*;
import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.*;
import org.springframework.context.annotation.*;
import org.springframework.core.env.Environment;
import org.springframework.http.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.oauth2.core.*;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.www.BasicAuthenticationFilter;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.filter.OncePerRequestFilter;

@SpringBootApplication
@RestController
public class Application {
  static {
    tools.jackson.core.StreamReadConstraints.overrideDefaultStreamReadConstraints(
        tools.jackson.core.StreamReadConstraints.builder()
            .maxNestingDepth(32)
            .maxStringLength(4096)
            .maxNumberLength(32)
            .build());
  }

  private final WorkflowStore store;

  public Application(WorkflowStore store) {
    this.store = store;
  }

  public static void main(String[] args) {
    SpringApplication.run(Application.class, args);
  }

  @Bean
  static WorkflowStore store(Environment e) {
    WorkflowStore s =
        new WorkflowStore(
            e.getRequiredProperty("DB_URL"),
            e.getProperty("DB_USER", "handoff"),
            e.getRequiredProperty("DB_PASSWORD"));
    s.migrate();
    return s;
  }

  @Bean
  SecurityFilterChain security(HttpSecurity http, Environment e) throws Exception {
    boolean dev = Arrays.asList(e.getActiveProfiles()).contains("dev");
    http.csrf(c -> c.disable())
        .authorizeHttpRequests(
            a -> a.requestMatchers("/health").permitAll().anyRequest().authenticated());
    if (dev) {
      String address = e.getProperty("server.address", "127.0.0.1");
      if (!Set.of("127.0.0.1", "::1", "localhost").contains(address))
        throw new IllegalStateException("dev must bind loopback");
      http.httpBasic(b -> {});
    } else {
      String issuer = e.getRequiredProperty("OIDC_ISSUER"),
          audience = e.getRequiredProperty("OIDC_AUDIENCE");
      NimbusJwtDecoder decoder = JwtDecoders.fromIssuerLocation(issuer);
      decoder.setJwtValidator(
          new DelegatingOAuth2TokenValidator<>(
              JwtValidators.createDefaultWithIssuer(issuer),
              jwt ->
                  jwt.getAudience().contains(audience) && jwt.getExpiresAt()!=null && jwt.getSubject()!=null && !jwt.getSubject().isBlank() && jwt.getClaimAsString("tenant")!=null && jwt.getClaimAsString("tenant").matches("[a-zA-Z0-9-]{1,64}")
                      ? OAuth2TokenValidatorResult.success()
                      : OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"))));
      http.oauth2ResourceServer(o -> o.jwt(j -> j.decoder(decoder)));
    }
    http.addFilterBefore(
        new OncePerRequestFilter() {
          protected void doFilterInternal(
              HttpServletRequest request, HttpServletResponse response, FilterChain chain)
              throws IOException, ServletException {
            byte[] bytes = request.getInputStream().readNBytes(8193);
            if (bytes.length > 8192) {
              response.sendError(413);
              return;
            }
            HttpServletRequestWrapper wrapped =
                new HttpServletRequestWrapper(request) {
                  public ServletInputStream getInputStream() {
                    ByteArrayInputStream in = new ByteArrayInputStream(bytes);
                    return new ServletInputStream() {
                      public int read() {
                        return in.read();
                      }

                      public boolean isFinished() {
                        return in.available() == 0;
                      }

                      public boolean isReady() {
                        return true;
                      }

                      public void setReadListener(ReadListener listener) {}
                    };
                  }

                  public BufferedReader getReader() {
                    return new BufferedReader(
                        new InputStreamReader(
                            getInputStream(), java.nio.charset.StandardCharsets.UTF_8));
                  }
                };
            chain.doFilter(wrapped, response);
          }
        },
        BasicAuthenticationFilter.class);
    return http.build();
  }

  @Bean
  @Profile("dev")
  UserDetailsService users(Environment env) {
    List<UserDetails> users = new ArrayList<>();
    for (String role : List.of("deployer", "operator", "viewer", "worker"))
      users.add(
          User.withUsername(role)
              .password("{noop}" + env.getProperty("DEMO_PASSWORD", "disposable-local-only"))
              .roles(role)
              .build());
    return new org.springframework.security.provisioning.InMemoryUserDetailsManager(users);
  }

  private String tenant(String role) {
    Authentication a = SecurityContextHolder.getContext().getAuthentication();
    boolean allowed =
        a.getAuthorities().stream()
            .anyMatch(
                g ->
                    g.getAuthority().equals("ROLE_" + role)
                        || g.getAuthority().equals("SCOPE_" + role));
    if (!allowed)
      throw new org.springframework.security.access.AccessDeniedException("role required");
    if (a.getPrincipal() instanceof Jwt jwt) {
      String tenant = jwt.getClaimAsString("tenant");
      if (tenant == null || !tenant.matches("[a-zA-Z0-9-]{1,64}"))
        throw new org.springframework.security.access.AccessDeniedException("tenant missing");
      return tenant;
    }
    return "demo";
  }

  @GetMapping("/health")
  public Map<String, String> health() {
    if(!store.healthy())throw new IllegalStateException("database unavailable");
    return Map.of("status", "UP");
  }

  @PostMapping("/v1/definitions")
  public Map<String, String> deploy(@RequestBody Definition d) {
    return Map.of("hash", store.deploy(tenant("deployer"), d));
  }

  public record Start(String definitionHash, Map<String, String> input) {}

  @PostMapping("/v1/executions")
  public Map<String, UUID> start(
      @RequestHeader("Idempotency-Key") String key, @RequestBody Start request) {
    return Map.of(
        "id", store.start(tenant("operator"), request.definitionHash(), key, request.input()));
  }

  @GetMapping("/v1/executions/{id}")
  public WorkflowStore.View get(@PathVariable UUID id) {
    return store.get(tenant("viewer"), id);
  }

  @GetMapping("/v1/executions/{id}/history")
  public List<Interpreter.Event> history(@PathVariable UUID id) {
    return store.history(tenant("viewer"), id);
  }

  public record Signal(String name, String value) {}

  @PostMapping("/v1/executions/{id}/signals")
  public Map<String, Boolean> signal(
      @PathVariable UUID id,
      @RequestHeader("Idempotency-Key") String key,
      @RequestBody Signal signal) {
    return Map.of(
        "accepted", store.signal(tenant("operator"), id, key, signal.name(), signal.value()));
  }

  @PostMapping("/v1/executions/{id}/cancel")
  public void cancel(@PathVariable UUID id) {
    store.cancel(tenant("operator"), id);
  }

  public record Resolution(String task, String decision, String reason) {}

  @PostMapping("/v1/executions/{id}/resolve")
  public void resolve(@PathVariable UUID id, @RequestBody Resolution r) {
    store.resolve(
        tenant("operator"),
        id,
        r.task(),
        r.decision(),
        SecurityContextHolder.getContext().getAuthentication().getName(),
        r.reason());
  }

  @PostMapping("/v1/executions/{id}/retry-compensation")
  public void retryCompensation(@PathVariable UUID id, @RequestBody Resolution r) {
    store.retryCompensation(
        tenant("operator"),
        id,
        r.task(),
        SecurityContextHolder.getContext().getAuthentication().getName(),
        r.reason());
  }

  public record ClaimRequest(String worker, int batch, int leaseSeconds) {}

  @PostMapping("/v1/worker/claim")
  public List<WorkflowStore.Claim> claim(@RequestBody ClaimRequest r) {
    return store.claim(tenant("worker"), r.worker(), r.batch(), r.leaseSeconds());
  }

  private void check(WorkflowStore.Claim q) {
    if (!tenant("worker").equals(q.tenant()))
      throw new org.springframework.security.access.AccessDeniedException("tenant mismatch");
  }

  @PostMapping("/v1/worker/dispatch")
  public void dispatch(@RequestBody WorkflowStore.Claim q) {
    check(q);
    store.dispatch(q);
  }

  public record Completion(WorkflowStore.Claim claim, String result) {}

  @PostMapping("/v1/worker/complete")
  public void complete(@RequestBody Completion c) {
    check(c.claim());
    store.complete(c.claim(), c.result());
  }

  @PostMapping("/v1/worker/heartbeat")
  public void heartbeat(@RequestBody WorkflowStore.Claim q) {
    check(q);
    store.heartbeat(q, 10);
  }

  public record Failure(WorkflowStore.Claim claim, boolean definitive, String reason) {}

  @PostMapping("/v1/worker/fail")
  public void fail(@RequestBody Failure f) {
    check(f.claim());
    store.fail(f.claim(), f.definitive(), f.reason());
  }

  @ExceptionHandler({
    IllegalArgumentException.class,
    NoSuchElementException.class,
    IllegalStateException.class
  })
  public ResponseEntity<ProblemDetail> problem(RuntimeException error) {
    int status =
        error instanceof NoSuchElementException
            ? 404
            : error instanceof IllegalStateException ? 409 : 400;
    ProblemDetail p = ProblemDetail.forStatus(status);
    p.setTitle(status == 409 ? "State conflict" : "Invalid workflow request");
    p.setDetail(
        error.getMessage() != null && error.getMessage().equals("STALE_GENERATION")
            ? "STALE_GENERATION"
            : "Request rejected; check the contract and current execution state");
    return ResponseEntity.status(status).body(p);
  }
}

package io.github.cheshmakzanoon.portfolio.handoff;

import io.github.cheshmakzanoon.portfolio.handoff.Definition.*;
import java.time.Instant;
import java.util.*;

/** No clocks, random values, generated identifiers, or I/O enter replay. */
public final class Interpreter {
  public static final String SEMANTICS = "1";

  public enum State {
    RUNNING,
    WAITING,
    COMPLETED,
    FAILED,
    CANCELLED,
    CANCEL_REQUESTED,
    COMPENSATING,
    COMPENSATION_FAILED,
    MANUAL_REVIEW
  }

  public enum EventType {
    STARTED,
    COMPLETED,
    TIMER_FIRED,
    SIGNAL,
    FAILED,
    CANCELLED,
    DISPATCHED,
    UNKNOWN_OUTCOME,
    OPERATOR_RESOLVED,
    OPERATOR_RETRY,
    LATE_EVENT
  }

  public record Event(long sequence, EventType type, String task, String value, Instant at) {}

  public record Decision(
      String id,
      Kind kind,
      String activity,
      Safety safety,
      String compensation,
      Instant due,
      String signal) {}

  public record Result(State state, List<Decision> decisions, Map<String, String> values) {
    public Result {
      decisions = List.copyOf(decisions);
      values = Map.copyOf(values);
    }
  }

  public Result replay(Definition definition, List<Event> history, Map<String, String> input) {
    definition.validate();
    if (history.isEmpty() || history.getFirst().type() != EventType.STARTED)
      throw new IllegalArgumentException("STARTED required");
    Map<String, Node> index = new HashMap<>();
    for (Node node : definition.nodes()) index.put(node.id(), node);
    Map<String, String> values = new LinkedHashMap<>();
    Map<String, Event> successes = new LinkedHashMap<>();
    Set<String> unknown = new HashSet<>(), failed = new HashSet<>();
    boolean cancelled = false;
    Instant started = Instant.EPOCH;
    long sequence = 0;
    for (Event e : history) {
      if (e.sequence() != ++sequence) throw new IllegalArgumentException("history ordering");
      if (e.type() == EventType.STARTED && e.sequence() != 1)
        throw new IllegalArgumentException("duplicate start");
      if (e.type() != EventType.STARTED
          && e.type() != EventType.CANCELLED
          && e.type() != EventType.LATE_EVENT) {
        boolean undo = e.task().startsWith("comp-");
        Node node = index.get(undo ? e.task().substring(5) : e.task());
        if (node == null
            || (undo
                && (node.compensation() == null
                    || !successes.containsKey(node.id())
                    || (!cancelled && failed.isEmpty()))))
          throw new IllegalArgumentException("unknown task");
        Kind kind = undo ? Kind.ACTIVITY : node.kind();
        if(successes.containsKey(e.task()))throw new IllegalArgumentException("task already settled");
        if(!undo && node.when()!=null){String[] guard=node.when().split("==");String[] expression=index.get(guard[0]).expression().split("==");String actual=Boolean.toString(expression[1].equals(input.get(expression[0].substring(6))));if(!actual.equals(guard[1]))throw new IllegalArgumentException("inactive branch task");}
        if(Set.of(EventType.DISPATCHED,EventType.FAILED,EventType.UNKNOWN_OUTCOME,EventType.OPERATOR_RETRY).contains(e.type()) && kind!=Kind.ACTIVITY)throw new IllegalArgumentException("activity event required");

        if ((e.type() == EventType.COMPLETED && kind != Kind.ACTIVITY)
            || (e.type() == EventType.SIGNAL && kind != Kind.SIGNAL)
            || (e.type() == EventType.TIMER_FIRED && kind != Kind.SIGNAL && kind != Kind.TIMER))
          throw new IllegalArgumentException("event/task kind mismatch");
        if (e.type() == EventType.OPERATOR_RESOLVED
            && (!unknown.contains(e.task())
                || !Set.of("APPLIED", "NOT_APPLIED").contains(e.value())))
          throw new IllegalArgumentException("invalid operator resolution");
        if (!undo
            && e.type() != EventType.OPERATOR_RESOLVED
            && node.requires().stream()
                .anyMatch(parent -> !settled(parent, index, successes, input)))
          throw new IllegalArgumentException("out-of-order task event");
      }
      switch (e.type()) {
        case STARTED -> started = e.at();
        case COMPLETED, TIMER_FIRED, SIGNAL -> {
          if (successes.putIfAbsent(e.task(), e) == null) values.put(e.task(), e.value());
        }
        case UNKNOWN_OUTCOME -> unknown.add(e.task());
        case OPERATOR_RESOLVED -> {
          unknown.remove(e.task());
          if ("APPLIED".equals(e.value())) {
            successes.put(e.task(), e);
            values.put(e.task(), "resolved");
          } else failed.add(e.task());
        }
        case OPERATOR_RETRY -> {
          if (!e.task().startsWith("comp-") || !failed.remove(e.task()))
            throw new IllegalArgumentException("invalid compensation retry");
        }
        case FAILED -> failed.add(e.task());
        case CANCELLED -> cancelled = true;
        default -> {}
      }
    }
    if (!unknown.isEmpty()) return new Result(State.MANUAL_REVIEW, List.of(), values);
    if (cancelled || !failed.isEmpty()) {
      List<Decision> undo = new ArrayList<>();
      List<Node> completed = new ArrayList<>();
      for (String id : successes.keySet())
        definition.nodes().stream()
            .filter(n -> n.id().equals(id) && n.compensation() != null)
            .findFirst()
            .ifPresent(completed::add);
      Collections.reverse(completed);
      for (Node n : completed) {
        String id = "comp-" + n.id();
        if (failed.contains(id)) return new Result(State.COMPENSATION_FAILED, List.of(), values);
        if (!successes.containsKey(id)) {
          undo.add(
              new Decision(id, Kind.ACTIVITY, n.compensation(), n.safety(), null, started, null));
          break;
        }
      }
      return new Result(
          undo.isEmpty() ? (cancelled ? State.CANCELLED : State.FAILED) : State.COMPENSATING,
          undo,
          values);
    }
    List<Decision> decisions = new ArrayList<>();
    Map<String,Instant> settledAt=new HashMap<>();for(var entry:successes.entrySet())settledAt.put(entry.getKey(),entry.getValue().at());
    Set<String> settled = new HashSet<>(successes.keySet());
    boolean changed;
    do {
      changed = false;
      for (Node n : definition.nodes()) {
        if (settled.contains(n.id()) || !settled.containsAll(n.requires())) continue;
        Instant derivedAt=started;for(String parent:n.requires())if(settledAt.getOrDefault(parent,started).isAfter(derivedAt))derivedAt=settledAt.get(parent);
        if (n.when() != null) {
          String[] guard = n.when().split("==");
          if (!guard[1].equals(values.get(guard[0]))) {
            settled.add(n.id());
            values.put(n.id(), "skipped");
            settledAt.put(n.id(),derivedAt);
            changed = true;
            continue;
          }
        }
        if (n.kind() == Kind.BRANCH || n.kind() == Kind.PARALLEL_ALL) {
          String value = "joined";
          if (n.kind() == Kind.BRANCH) {
            String[] expr = n.expression().split("==");
            value = Boolean.toString(expr[1].equals(input.get(expr[0].substring(6))));
          }
          values.put(n.id(), value);
          settledAt.put(n.id(),derivedAt);
          settled.add(n.id());
          changed = true;
        }
      }
    } while (changed);
    for (Node n : definition.nodes()) {
      if (settled.contains(n.id()) || !settled.containsAll(n.requires())) continue;
      Instant anchor = started;
      for (String r : n.requires())
        if (settledAt.getOrDefault(r,started).isAfter(anchor)) anchor=settledAt.get(r);
      decisions.add(
          new Decision(
              n.id(),
              n.kind(),
              n.activity(),
              n.safety(),
              n.compensation(),
              anchor.plusSeconds(n.delaySeconds()),
              n.signal()));
    }
    State state =
        settled.size() == definition.nodes().size()
            ? State.COMPLETED
            : decisions.stream().anyMatch(d -> d.kind() == Kind.ACTIVITY)
                ? State.RUNNING
                : State.WAITING;
    return new Result(state, decisions, values);
  }

  private static boolean settled(
      String id, Map<String, Node> index, Map<String, Event> successes, Map<String, String> input) {
    if (successes.containsKey(id)) return true;
    Node n = index.get(id);
    if (!n.requires().stream().allMatch(p -> settled(p, index, successes, input))) return false;
    if (n.kind() == Kind.BRANCH || n.kind() == Kind.PARALLEL_ALL) return true;
    if (n.when() != null) {
      String[] guard = n.when().split("==");
      Node branch = index.get(guard[0]);
      String[] expression = branch.expression().split("==");
      String actual = Boolean.toString(expression[1].equals(input.get(expression[0].substring(6))));
      return !actual.equals(guard[1]);
    }
    return false;
  }
}

package io.github.cheshmakzanoon.portfolio.handoff;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Immutable finite typed graph. Expressions are deliberately not a general language. */
public record Definition(String name, int version, List<Node> nodes) {
  public enum Kind {
    ACTIVITY,
    TIMER,
    SIGNAL,
    BRANCH,
    PARALLEL_ALL
  }

  public enum Safety {
    PURE,
    IDEMPOTENT_WITH_KEY,
    NON_IDEMPOTENT
  }

  public enum Type {
    TEXT,
    BOOLEAN,
    INTEGER
  }

  public record Node(
      String id,
      Kind kind,
      List<String> requires,
      String activity,
      Safety safety,
      String compensation,
      Type inputType,
      Type outputType,
      long delaySeconds,
      String signal,
      String expression,
      String when) {
    public Node {
      requires = List.copyOf(requires);
    }
  }

  public static final Set<String> ACTIVITIES =
      Set.of(
          "reserve",
          "charge",
          "ship",
          "release",
          "refund",
          "transcode",
          "thumbnail",
          "publish",
          "unpublish",
          "pure");

  public Definition {
    nodes = List.copyOf(nodes);
  }

  public Definition validate() {
    if (name == null
        || !name.matches("[a-z][a-z0-9-]{0,63}")
        || version < 1
        || nodes.isEmpty()
        || nodes.size() > 128) throw new IllegalArgumentException("definition bounds");
    Map<String, Node> index = new LinkedHashMap<>();
    for (Node n : nodes) {
      if (n.id == null
          || !n.id.matches("[a-z][a-z0-9-]{0,63}")
          || n.id.startsWith("comp-")
          || index.put(n.id, n) != null
          || n.kind == null
          || n.inputType == null
          || n.outputType == null
          || n.requires.size() > 16
          || new HashSet<>(n.requires).size() != n.requires.size())
        throw new IllegalArgumentException("invalid node");
      if (n.kind == Kind.ACTIVITY
          && (n.activity == null
              || !ACTIVITIES.contains(n.activity)
              || n.safety == null
              || n.outputType != Type.TEXT))
        throw new IllegalArgumentException("untrusted activity");
      if (n.compensation != null && (n.kind!=Kind.ACTIVITY || !ACTIVITIES.contains(n.compensation)))
        throw new IllegalArgumentException("untrusted compensation");
      if (n.delaySeconds < 0 || n.delaySeconds > 604800)
        throw new IllegalArgumentException("timer bound");
      if (n.kind == Kind.BRANCH
          && (n.expression == null
              || !n.expression.matches("input\\.[a-zA-Z][a-zA-Z0-9_]{0,31}==[a-zA-Z0-9_-]{1,64}")
              || n.outputType != Type.BOOLEAN))
        throw new IllegalArgumentException("invalid expression");
      if (n.when != null && !n.when.matches("[a-z][a-z0-9-]{0,63}==(true|false)"))
        throw new IllegalArgumentException("invalid guard");
      if (n.kind == Kind.SIGNAL && (n.signal == null || !n.signal.matches("[a-z][a-z0-9-]{0,63}")))
        throw new IllegalArgumentException("signal name");
    }
    if (nodes.stream().filter(n -> n.requires.isEmpty()).count() != 1)
      throw new IllegalArgumentException("one reachable root required");
    for (Node n : nodes) {
      for (String r : n.requires) {
        Node previous = index.get(r);
        if (previous == null || previous.outputType != n.inputType)
          throw new IllegalArgumentException("missing reference/type mismatch");
      }
      if (n.when != null) {
        String branch = n.when.split("==")[0];
        if (!index.containsKey(branch)
            || index.get(branch).kind != Kind.BRANCH
            || !ancestors(n.id, index, new HashSet<>()).contains(branch))
          throw new IllegalArgumentException("guard must name an ancestor branch");
      }
      visit(n.id, index, new HashSet<>(), new HashSet<>());
    }
    for (Node parent : nodes)
      if (nodes.stream().filter(n -> n.requires().contains(parent.id())).count() > 16)
        throw new IllegalArgumentException("fan-out bound");
    return this;
  }

  private static Set<String> ancestors(String id, Map<String, Node> index, Set<String> seen) {
    if (!seen.add(id)) return seen;
    for (String parent : index.get(id).requires)
      if (index.containsKey(parent)) ancestors(parent, index, seen);
    return seen;
  }

  private static void visit(
      String id, Map<String, Node> index, Set<String> visiting, Set<String> done) {
    if (done.contains(id)) return;
    if (!visiting.add(id)) throw new IllegalArgumentException("cycle");
    for (String parent : index.get(id).requires) visit(parent, index, visiting, done);
    visiting.remove(id);
    done.add(id);
  }

  public String contentHash() {
    try {
      return HexFormat.of()
          .formatHex(
              MessageDigest.getInstance("SHA-256")
                  .digest(toString().getBytes(StandardCharsets.UTF_8)));
    } catch (java.security.NoSuchAlgorithmException e) {
      throw new IllegalStateException(e);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.handoff;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.*;
import io.github.cheshmakzanoon.portfolio.handoff.Definition.*;
import io.github.cheshmakzanoon.portfolio.handoff.Interpreter.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.flywaydb.core.Flyway;

/** PostgreSQL is the serialization boundary; no process-local state is authoritative. */
public final class WorkflowStore implements AutoCloseable {
  private final com.zaxxer.hikari.HikariDataSource pool;
  private final String url, user, password;
  private final ObjectMapper json =
      new ObjectMapper().enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
  private final Interpreter interpreter = new Interpreter();
  private final Runnable beforeCommit;

  public record Claim(
      UUID instance,
      String tenant,
      String task,
      String activity,
      Safety safety,
      String parameters,
      long generation,
      int attempt,
      String worker,
      String credential) {}

  public record View(
      UUID id,
      String tenant,
      String definitionHash,
      String semantics,
      State state,
      long version,
      Map<String, String> values) {}

  public WorkflowStore(String url, String user, String password) {
    this(url, user, password, () -> {});
  }

  public WorkflowStore(String url, String user, String password, Runnable beforeCommit) {
    this.url = url;
    this.user = user;
    this.password = password;
    this.beforeCommit = beforeCommit;
    var configuration=new com.zaxxer.hikari.HikariConfig();configuration.setJdbcUrl(url);configuration.setUsername(user);configuration.setPassword(password);configuration.setMaximumPoolSize(4);configuration.setMinimumIdle(0);configuration.setConnectionTimeout(10000);configuration.setValidationTimeout(3000);configuration.setPoolName("handoff-db");pool=new com.zaxxer.hikari.HikariDataSource(configuration);

  }

  public void migrate() {
    Flyway.configure()
        .dataSource(url, user, password)
        .locations("classpath:db/migration")
        .load()
        .migrate();
  }

  private interface Work<T> {
    T run(Connection c) throws Exception;
  }

  private <T> T tx(Work<T> work) {
    try (Connection c = pool.getConnection()) {
      c.setAutoCommit(false);
      try {
        T result = work.run(c);
        beforeCommit.run();
        c.commit();
        return result;
      } catch (Exception e) {
        c.rollback();
        throw e;
      }
    } catch (RuntimeException e) {
      throw e;
    } catch (Exception e) {
      throw new IllegalStateException("database operation failed", e);
    }
  }

  private static PreparedStatement statement(Connection c, String sql, Object... params)
      throws SQLException {
    PreparedStatement s = c.prepareStatement(sql);
    s.setQueryTimeout(15);
    for (int i = 0; i < params.length; i++) s.setObject(i + 1, params[i]);
    return s;
  }

  private static int update(Connection c, String sql, Object... params) throws SQLException {
    try (PreparedStatement s = statement(c, sql, params)) {
      return s.executeUpdate();
    }
  }

  private String encode(Object object) throws Exception {
    return json.writeValueAsString(object);
  }

  private Definition definition(Connection c, String tenant, String hash) throws Exception {
    try (PreparedStatement s =
            statement(
                c, "SELECT body FROM workflow_definition WHERE tenant=? AND hash=?", tenant, hash);
        ResultSet r = s.executeQuery()) {
      if (!r.next()) throw new IllegalArgumentException("definition missing");
      return json.readValue(r.getString(1), Definition.class);
    }
  }

  public String deploy(String tenant, Definition definition) {
    definition.validate();
    return tx(
        c -> {
          String hash = definition.contentHash();
          int n =
              update(
                  c,
                  "INSERT INTO workflow_definition(tenant,name,version,hash,body) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING",
                  tenant,
                  definition.name(),
                  definition.version(),
                  hash,
                  encode(definition));
          if (n == 0) {
            try (PreparedStatement s =
                    statement(
                        c,
                        "SELECT hash FROM workflow_definition WHERE tenant=? AND name=? AND version=?",
                        tenant,
                        definition.name(),
                        definition.version());
                ResultSet r = s.executeQuery()) {
              if (!r.next() || !r.getString(1).equals(hash))
                throw new IllegalArgumentException("immutable version conflict");
            }
          }
          return hash;
        });
  }

  public UUID start(String tenant, String hash, String key, Map<String, String> input) {
    boundedKey(key);
    if(hash==null||!hash.matches("[a-f0-9]{64}")||input==null||input.entrySet().stream().anyMatch(e->e.getKey()==null||!e.getKey().matches("[a-zA-Z][a-zA-Z0-9_-]{0,63}")||e.getValue()==null))throw new IllegalArgumentException("typed input required");
    if (input.entrySet().stream()
        .anyMatch(
            e ->
                e.getKey()
                    .toLowerCase(Locale.ROOT)
                    .matches(".*(password|secret|token|authorization).*")))
      throw new IllegalArgumentException("secret input forbidden");
    if (input.size() > 32 || input.toString().length() > 4096)
      throw new IllegalArgumentException("input cap");
    return tx(
        c -> {
          definition(c, tenant, hash);
          String body = encode(new TreeMap<>(input));
          if(body.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>4096)throw new IllegalArgumentException("input byte cap");
          String request = hash + ":" + body;
          try (PreparedStatement s =
                  statement(
                      c,
                      "SELECT id,request_hash FROM workflow_instance WHERE tenant=? AND start_key=?",
                      tenant,
                      key);
              ResultSet r = s.executeQuery()) {
            if (r.next()) {
              if (!request.equals(r.getString(2)))
                throw new IllegalArgumentException("idempotency conflict");
              return r.getObject(1, UUID.class);
            }
          }
          // Serialize tenant quota and concurrent duplicate starts without taking a global lock.
          try (PreparedStatement lock =
              statement(c, "SELECT pg_advisory_xact_lock(hashtext(?))", tenant)) {
            lock.execute();
          }
          try (PreparedStatement s =
                  statement(
                      c,
                      "SELECT id,request_hash FROM workflow_instance WHERE tenant=? AND start_key=?",
                      tenant,
                      key);
              ResultSet r = s.executeQuery()) {
            if (r.next()) {
              if (!request.equals(r.getString(2)))
                throw new IllegalArgumentException("idempotency conflict");
              return r.getObject(1, UUID.class);
            }
          }
          try (PreparedStatement s =
                  statement(
                      c,
                      "SELECT count(*) FROM workflow_instance WHERE tenant=? AND state NOT IN ('COMPLETED','FAILED','CANCELLED')",
                      tenant);
              ResultSet r = s.executeQuery()) {
            r.next();
            if (r.getLong(1) >= 20000) throw new IllegalArgumentException("tenant execution quota");
          }
          try (PreparedStatement quota =
                  statement(
                      c,
                      "SELECT count(*) FROM activity_task t JOIN workflow_instance i ON i.id=t.instance_id WHERE i.tenant=? AND t.status IN ('READY','LEASED')",
                      tenant);
              ResultSet count = quota.executeQuery()) {
            count.next();
            if (count.getLong(1) >= 100000)
              throw new IllegalArgumentException("tenant queue quota");
          }
          UUID id = UUID.randomUUID();
          update(
              c,
              "INSERT INTO workflow_instance(id,tenant,definition_hash,semantics,input,start_key,request_hash,state) VALUES(?,?,?,?,?,?,?,'RUNNING')",
              id,
              tenant,
              hash,
              Interpreter.SEMANTICS,
              body,
              key,
              request);
          append(c, id, EventType.STARTED, "", "started");
          schedule(c, id);
          return id;
        });
  }

  private static void boundedKey(String key) {
    if (key == null || !key.matches("[a-zA-Z0-9_-]{1,128}"))
      throw new IllegalArgumentException("idempotency key required");
  }

  private View lock(Connection c, String tenant, UUID id) throws Exception {
    try (PreparedStatement s =
            statement(
                c,
                "SELECT definition_hash,semantics,state,version FROM workflow_instance WHERE id=? AND tenant=? FOR UPDATE",
                id,
                tenant);
        ResultSet r = s.executeQuery()) {
      if (!r.next()) throw new NoSuchElementException("execution missing");
      return new View(
          id,
          tenant,
          r.getString(1),
          r.getString(2),
          State.valueOf(r.getString(3)),
          r.getLong(4),
          Map.of());
    }
  }

  private void append(Connection c, UUID id, EventType type, String task, String value)
      throws Exception {
    if (value == null) value = "";
    if (value.length() > 1024
        || value.toLowerCase(Locale.ROOT).matches(".*(password|secret|bearer|token).*"))
      throw new IllegalArgumentException("result contains forbidden secret field or exceeds cap");
    long expectedVersion;
    try (PreparedStatement s = statement(c, "SELECT version FROM workflow_instance WHERE id=?", id);
        ResultSet r = s.executeQuery()) {
      if (!r.next()) throw new NoSuchElementException("execution missing");
      expectedVersion = r.getLong(1);
    }
    if (expectedVersion >= 10000) throw new IllegalArgumentException("history cap");
    long seq;
    try (PreparedStatement s =
            statement(
                c,
                "UPDATE workflow_instance SET version=version+1 WHERE id=? AND version=? RETURNING version",
                id,
                expectedVersion);
        ResultSet r = s.executeQuery()) {
      if (!r.next()) throw new java.sql.SQLTransactionRollbackException("instance version changed", "40001");
      seq = r.getLong(1);
    }
    update(
        c,
        "INSERT INTO workflow_history(instance_id,sequence,type,task,value) VALUES(?,?,?,?,?)",
        id,
        seq,
        type.name(),
        task,
        value);
  }

  private List<Event> history(Connection c, UUID id) throws Exception {
    List<Event> events = new ArrayList<>();
    try (PreparedStatement s =
            statement(
                c,
                "SELECT sequence,type,task,value,at FROM workflow_history WHERE instance_id=? ORDER BY sequence",
                id);
        ResultSet r = s.executeQuery()) {
      while (r.next())
        events.add(
            new Event(
                r.getLong(1),
                EventType.valueOf(r.getString(2)),
                r.getString(3),
                r.getString(4),
                r.getTimestamp(5).toInstant()));
    }
    return events;
  }

  public List<Event> history(String tenant, UUID id) {
    return tx(
        c -> {
          lock(c, tenant, id);
          return history(c, id);
        });
  }

  private Result schedule(Connection c, UUID id) throws Exception {
    String tenant, hash, input, semantics;
    try (PreparedStatement s =
            statement(
                c,
                "SELECT tenant,definition_hash,input,semantics FROM workflow_instance WHERE id=?",
                id);
        ResultSet r = s.executeQuery()) {
      r.next();
      tenant = r.getString(1);
      hash = r.getString(2);
      input = r.getString(3);
      semantics = r.getString(4);
    }
    if (!Interpreter.SEMANTICS.equals(semantics))
      throw new IllegalStateException("unsupported pinned semantics");
    Definition d = definition(c, tenant, hash);
    Result result =
        interpreter.replay(
            d, history(c, id), json.readValue(input, new TypeReference<Map<String, String>>() {}));
    // Cancellation waits for all in-flight leases to settle before selecting reverse-order undo.
    if (result.state() == State.COMPENSATING
        || result.state() == State.CANCELLED
        || result.state() == State.CANCEL_REQUESTED
        || result.state() == State.FAILED) {
      try (PreparedStatement leased =
              statement(
                  c,
                  "SELECT count(*) FROM activity_task WHERE instance_id=? AND status='LEASED' AND logical_id NOT LIKE 'comp-%'",
                  id);
          ResultSet remaining = leased.executeQuery()) {
        remaining.next();
        if (remaining.getInt(1) > 0)
          result = new Result(State.CANCEL_REQUESTED, List.of(), result.values());
      }
    }
    update(c, "UPDATE workflow_instance SET state=? WHERE id=?", result.state().name(), id);
    if (result.state() == State.COMPENSATING
        || result.state() == State.CANCELLED
        || result.state() == State.CANCEL_REQUESTED
        || result.state() == State.FAILED
        || result.state() == State.COMPENSATION_FAILED) {
      update(
          c,
          "UPDATE activity_task SET status='CANCELLED' WHERE instance_id=? AND status='READY' AND logical_id NOT LIKE 'comp-%'",
          id);
      update(c, "UPDATE timer SET status='CANCELLED' WHERE instance_id=? AND status='WAITING'", id);
    }
    if(result.decisions().stream().anyMatch(d->d.kind()==Kind.ACTIVITY)) {
      try(PreparedStatement quotaLock=statement(c,"SELECT pg_advisory_xact_lock(hashtext(?))",tenant)){quotaLock.execute();}
      try(PreparedStatement quota=statement(c,"SELECT count(*) FROM activity_task t JOIN workflow_instance i ON i.id=t.instance_id WHERE i.tenant=? AND t.status IN ('READY','LEASED')",tenant);ResultSet count=quota.executeQuery()){count.next();if(count.getLong(1)+result.decisions().size()>100000)throw new IllegalArgumentException("tenant queue quota");}
    }
    for (Decision choice : result.decisions()) {
      if (choice.kind() == Kind.ACTIVITY)
        update(
            c,
            "INSERT INTO activity_task(instance_id,logical_id,activity,safety,parameters,status,due_at) VALUES(?,?,?,?,?,'READY',?) ON CONFLICT DO NOTHING",
            id,
            choice.id(),
            choice.activity(),
            choice.safety().name(),
            input,
            Timestamp.from(choice.due()));
      if (choice.kind() == Kind.TIMER || choice.kind() == Kind.SIGNAL)
        update(
            c,
            "INSERT INTO timer(instance_id,logical_id,due_at,status) VALUES(?,?,?,'WAITING') ON CONFLICT DO NOTHING",
            id,
            choice.id(),
            Timestamp.from(choice.due()));
    }
    return result;
  }

  public View get(String tenant, UUID id) {
    return tx(
        c -> {
          View v = lock(c, tenant, id);
          Result result = schedule(c, id);
          return new View(
              id,
              tenant,
              v.definitionHash(),
              v.semantics(),
              result.state(),
              v.version(),
              result.values());
        });
  }

  public List<Claim> claim(String tenant,String worker,int batch,int leaseSeconds) {
    if(batch<1||batch>16||leaseSeconds<1||leaseSeconds>120||worker==null||!worker.matches("[a-zA-Z0-9-]{1,64}"))throw new IllegalArgumentException("claim bounds");
    return tx(c->{List<Claim> claims=new ArrayList<>();List<UUID> instances=new ArrayList<>();
      // Match the instance-before-task lock order used by cancellation/completion.
      try(PreparedStatement eligible=statement(c,"SELECT i.id FROM workflow_instance i WHERE i.tenant=? AND i.state IN ('RUNNING','COMPENSATING') AND EXISTS(SELECT 1 FROM activity_task t WHERE t.instance_id=i.id AND t.status='READY' AND t.due_at<=clock_timestamp()) ORDER BY i.id FOR UPDATE SKIP LOCKED LIMIT ?",tenant,batch);ResultSet rows=eligible.executeQuery()){while(rows.next())instances.add(rows.getObject(1,UUID.class));}
      for(UUID id:instances){if(claims.size()>=batch)break;
        try(PreparedStatement s=statement(c,"SELECT logical_id,activity,safety,parameters,generation,attempt FROM activity_task WHERE instance_id=? AND status='READY' AND due_at<=clock_timestamp() ORDER BY due_at,logical_id FOR UPDATE SKIP LOCKED LIMIT ?",id,batch-claims.size());ResultSet r=s.executeQuery()){
          while(r.next()){String task=r.getString(1),credential=UUID.randomUUID().toString();long generation=r.getLong(5)+1;int attempt=r.getInt(6)+1;
            update(c,"UPDATE activity_task SET status='LEASED',generation=?,attempt=?,worker=?,credential=?,lease_until=clock_timestamp()+(? * interval '1 second'),dispatch_intent=false WHERE instance_id=? AND logical_id=?",generation,attempt,worker,credential,leaseSeconds,id,task);
            update(c,"INSERT INTO activity_attempt(instance_id,logical_id,generation,worker) VALUES(?,?,?,?)",id,task,generation,worker);
            claims.add(new Claim(id,tenant,task,r.getString(2),Safety.valueOf(r.getString(3)),r.getString(4),generation,attempt,worker,credential));
          }
        }
      }
      return claims;
    });
  }

  private void authorize(Connection c, Claim q) throws Exception {
    try (PreparedStatement s =
            statement(
                c,
                "SELECT 1 FROM activity_task WHERE instance_id=? AND logical_id=? AND generation=? AND attempt=? AND worker=? AND credential=? AND status='LEASED' AND lease_until>clock_timestamp() AND safety=? AND activity=? AND parameters=? FOR UPDATE",
                q.instance(),
                q.task(),
                q.generation(),
                q.attempt(),
                q.worker(),
                q.credential(),
                q.safety().name(),
                q.activity(),
                q.parameters());
        ResultSet r = s.executeQuery()) {
      if (!r.next()) throw new IllegalStateException("STALE_GENERATION");
    }
  }

  public void heartbeat(Claim q, int seconds) {
    if (seconds < 1 || seconds > 120) throw new IllegalArgumentException("lease cap");
    tx(
        c -> {
          lock(c, q.tenant(), q.instance());
          authorize(c, q);
          update(
              c,
              "UPDATE activity_task SET lease_until=clock_timestamp()+(? * interval '1 second') WHERE instance_id=? AND logical_id=?",
              seconds,
              q.instance(),
              q.task());
          return null;
        });
  }

  public void dispatch(Claim q) {
    tx(
        c -> {
          View view = lock(c, q.tenant(), q.instance());
          authorize(c, q);
          if ((q.task().startsWith("comp-") && view.state()!=State.COMPENSATING) || (!q.task().startsWith("comp-") && view.state()!=State.RUNNING))
            throw new IllegalStateException("dispatch paused");
          int authorized=update(c,"UPDATE activity_task SET dispatch_intent=true WHERE instance_id=? AND logical_id=? AND (safety<>'NON_IDEMPOTENT' OR dispatch_intent=false)",q.instance(),q.task());
          if(authorized!=1)throw new IllegalStateException("DISPATCH_ALREADY_AUTHORIZED");
          update(
              c,
              "UPDATE activity_attempt SET dispatched_at=clock_timestamp() WHERE instance_id=? AND logical_id=? AND generation=?",
              q.instance(),
              q.task(),
              q.generation());
          append(c, q.instance(), EventType.DISPATCHED, q.task(), "authorized");
          return null;
        });
  }

  public void complete(Claim q, String result) {
    tx(
        c -> {
          lock(c, q.tenant(), q.instance());
          authorize(c, q);
          update(
              c,
              "UPDATE activity_task SET status='COMPLETED' WHERE instance_id=? AND logical_id=?",
              q.instance(),
              q.task());
          update(
              c,
              "UPDATE activity_attempt SET completed_at=clock_timestamp(),outcome='COMPLETED' WHERE instance_id=? AND logical_id=? AND generation=?",
              q.instance(),
              q.task(),
              q.generation());
          append(c, q.instance(), EventType.COMPLETED, q.task(), result);
          obligation(c,q.tenant(),q.instance(),q.task());
          schedule(c, q.instance());
          return null;
        });
  }

  private void obligation(Connection c,String tenant,UUID id,String task)throws Exception {
    Definition d=definition(c,tenant,getHash(c,id));
    for(Node n:d.nodes())if(n.id().equals(task)&&n.compensation()!=null)update(c,"INSERT INTO compensation_obligation(instance_id,logical_id,activity,completion_sequence) SELECT id,?,?,version FROM workflow_instance WHERE id=? ON CONFLICT DO NOTHING",n.id(),n.compensation(),id);
    if(task.startsWith("comp-"))update(c,"UPDATE compensation_obligation SET status='COMPLETED' WHERE instance_id=? AND logical_id=?",id,task.substring(5));
  }

  private String getHash(Connection c, UUID id) throws Exception {
    try (PreparedStatement s =
            statement(c, "SELECT definition_hash FROM workflow_instance WHERE id=?", id);
        ResultSet r = s.executeQuery()) {
      r.next();
      return r.getString(1);
    }
  }

  public void fail(Claim q, boolean definitive, String reason) {
    if(reason==null || reason.isBlank() || reason.length()>256)throw new IllegalArgumentException("failure reason required");
    tx(
        c -> {
          lock(c, q.tenant(), q.instance());
          authorize(c, q);
          boolean dispatched;
          try (PreparedStatement s =
                  statement(
                      c,
                      "SELECT dispatch_intent FROM activity_task WHERE instance_id=? AND logical_id=?",
                      q.instance(),
                      q.task());
              ResultSet r = s.executeQuery()) {
            r.next();
            dispatched = r.getBoolean(1);
          }
          failure(
              c, q.instance(), q.task(), q.safety(), q.attempt(), dispatched, definitive, reason);
          schedule(c, q.instance());
          return null;
        });
  }

  private void failure(
      Connection c,
      UUID id,
      String task,
      Safety safety,
      int attempt,
      boolean dispatched,
      boolean definitive,
      String reason)
      throws Exception {
    update(
        c,
        "UPDATE activity_attempt SET completed_at=clock_timestamp(),outcome=? WHERE instance_id=? AND logical_id=? AND generation=(SELECT generation FROM activity_task WHERE instance_id=? AND logical_id=?)",
        definitive ? "REJECTED" : reason.equals("lease expired") ? "LEASE_EXPIRED" : "UNCERTAIN",
        id,
        task,
        id,
        task);
    if(task.startsWith("comp-")&&((safety==Safety.NON_IDEMPOTENT && dispatched && !definitive)||attempt>=4))update(c,"UPDATE compensation_obligation SET status=? WHERE instance_id=? AND logical_id=?",safety==Safety.NON_IDEMPOTENT&&dispatched&&!definitive?"UNKNOWN_OUTCOME":"FAILED",id,task.substring(5));
    if (safety == Safety.NON_IDEMPOTENT && dispatched && !definitive) {
      update(
          c,
          "UPDATE activity_task SET status='UNKNOWN_OUTCOME' WHERE instance_id=? AND logical_id=?",
          id,
          task);
      append(c, id, EventType.UNKNOWN_OUTCOME, task, "external result uncertain");
    } else if (attempt >= 4) {
      update(
          c,
          "UPDATE activity_task SET status='FAILED' WHERE instance_id=? AND logical_id=?",
          id,
          task);
      append(c, id, EventType.FAILED, task, reason);
    } else {
      long backoff = (1L << attempt);
      long jitter = Math.floorMod(Objects.hash(id, task, attempt, 42), 1000);
      update(
          c,
          "UPDATE activity_task SET status='READY',due_at=clock_timestamp()+(? * interval '1 millisecond') WHERE instance_id=? AND logical_id=?",
          backoff * 100 + jitter,
          id,
          task);
    }
  }

  public int tick(int limit) {
    if (limit < 1 || limit > 1000) throw new IllegalArgumentException("tick bounds");
    return tx(
        c -> {
          List<UUID> ids = new ArrayList<>();
          try (PreparedStatement s =
                  statement(
                      c,
                      "SELECT id FROM workflow_instance WHERE id IN (SELECT instance_id FROM timer WHERE status='WAITING' AND due_at<=clock_timestamp() UNION SELECT instance_id FROM activity_task WHERE status='LEASED' AND lease_until<=clock_timestamp()) ORDER BY id FOR UPDATE SKIP LOCKED LIMIT ?",
                      limit);
              ResultSet r = s.executeQuery()) {
            while (r.next()) ids.add(r.getObject(1, UUID.class));
          }
          for (UUID id : ids) {
            try (PreparedStatement s =
                    statement(
                        c,
                        "SELECT logical_id FROM timer WHERE instance_id=? AND status='WAITING' AND due_at<=clock_timestamp() FOR UPDATE",
                        id);
                ResultSet r = s.executeQuery()) {
              while (r.next()) {
                String task = r.getString(1);
                update(
                    c,
                    "UPDATE timer SET status='FIRED' WHERE instance_id=? AND logical_id=?",
                    id,
                    task);
                append(c, id, EventType.TIMER_FIRED, task, "timeout");
              }
            }
            try (PreparedStatement s =
                    statement(
                        c,
                        "SELECT logical_id,safety,attempt,dispatch_intent FROM activity_task WHERE instance_id=? AND status='LEASED' AND lease_until<=clock_timestamp() FOR UPDATE",
                        id);
                ResultSet r = s.executeQuery()) {
              while (r.next())
                failure(
                    c,
                    id,
                    r.getString(1),
                    Safety.valueOf(r.getString(2)),
                    r.getInt(3),
                    r.getBoolean(4),
                    false,
                    "lease expired");
            }
            schedule(c, id);
          }
          return ids.size();
        });
  }

  public boolean signal(String tenant, UUID id, String key, String signal, String payload) {
    boundedKey(key);
    if(signal==null||!signal.matches("[a-z][a-z0-9-]{0,63}")||payload==null||payload.length()>1024||payload.toLowerCase(Locale.ROOT).matches(".*(password|secret|bearer|token).*"))throw new IllegalArgumentException("signal bounds/secret");
    return tx(
        c -> {
          View view = lock(c, tenant, id);
          try (PreparedStatement s =
                  statement(
                      c,
                      "SELECT signal,payload,accepted FROM signal_inbox WHERE instance_id=? AND request_key=?",
                      id,
                      key);
              ResultSet r = s.executeQuery()) {
            if (r.next()) {
              if (!r.getString(1).equals(signal) || !r.getString(2).equals(payload))
                throw new IllegalArgumentException("signal idempotency conflict");
              return r.getBoolean(3);
            }
          }
          Result state = schedule(c, id);
          Decision choice =
              state.decisions().stream()
                  .filter(d -> d.kind() == Kind.SIGNAL && signal.equals(d.signal()))
                  .findFirst()
                  .orElse(null);
          boolean accepted = false;
          if (choice != null) {
            int n =
                update(
                    c,
                    "UPDATE timer SET status='SIGNALED' WHERE instance_id=? AND logical_id=? AND status='WAITING'",
                    id,
                    choice.id());
            accepted = n == 1;
            if (accepted) append(c, id, EventType.SIGNAL, choice.id(), payload);
          }
          if (!accepted) append(c, id, EventType.LATE_EVENT, "", "late signal:" + signal);
          update(
              c,
              "INSERT INTO signal_inbox(instance_id,request_key,signal,payload,accepted) VALUES(?,?,?,?,?)",
              id,
              key,
              signal,
              payload,
              accepted);
          schedule(c, id);
          return accepted;
        });
  }

  public void cancel(String tenant, UUID id) {
    tx(
        c -> {
          View view = lock(c, tenant, id);
          if (view.state() == State.COMPLETED
              || view.state() == State.CANCELLED
              || view.state() == State.FAILED)
            throw new IllegalArgumentException("terminal execution");
          append(c, id, EventType.CANCELLED, "", "cooperative cancellation");
          schedule(c, id);
          return null;
        });
  }

  public void resolve(
      String tenant, UUID id, String task, String decision, String operator, String reason) {
    if (!Set.of("APPLIED", "NOT_APPLIED").contains(decision)
        || reason == null
        || reason.isBlank()
        || reason.length() > 256) throw new IllegalArgumentException("resolution reason required");
    tx(
        c -> {
          lock(c, tenant, id);
          int n =
              update(
                  c,
                  "UPDATE activity_task SET status=? WHERE instance_id=? AND logical_id=? AND status='UNKNOWN_OUTCOME'",
                  decision.equals("APPLIED") ? "COMPLETED" : "FAILED",
                  id,
                  task);
          if (n != 1) throw new IllegalArgumentException("not unknown");
          append(c, id, EventType.OPERATOR_RESOLVED, task, decision);
          if(decision.equals("APPLIED"))obligation(c,tenant,id,task);
          else if(task.startsWith("comp-"))update(c,"UPDATE compensation_obligation SET status='FAILED' WHERE instance_id=? AND logical_id=?",id,task.substring(5));

          update(
              c,
              "INSERT INTO operator_decision(instance_id,sequence,operator_id,task,resolution,reason) SELECT id,version,?,?,?,? FROM workflow_instance WHERE id=?",
              operator,
              task,
              decision,
              reason,
              id);
          schedule(c, id);
          return null;
        });
  }

  public void retryCompensation(
      String tenant, UUID id, String task, String operator, String reason) {
    if (task == null
        || !task.startsWith("comp-")
        || reason == null
        || reason.isBlank()
        || reason.length() > 256)
      throw new IllegalArgumentException("compensation and reason required");
    tx(
        c -> {
          lock(c, tenant, id);
          int count =
              update(
                  c,
                  "UPDATE activity_task SET status='READY',attempt=0,due_at=clock_timestamp() WHERE instance_id=? AND logical_id=? AND status='FAILED'",
                  id,
                  task);
          if (count != 1) throw new IllegalArgumentException("compensation not failed");
          append(c, id, EventType.OPERATOR_RETRY, task, "authorized retry");
          update(
              c,
              "INSERT INTO operator_decision(instance_id,sequence,operator_id,task,resolution,reason) SELECT id,version,?,?,'RETRY_COMPENSATION',? FROM workflow_instance WHERE id=?",
              operator,
              task,
              reason,
              id);
          update(
              c,
              "UPDATE compensation_obligation SET status='PENDING' WHERE instance_id=? AND logical_id=?",
              id,
              task.substring(5));
          schedule(c, id);
          return null;
        });
  }

  public boolean healthy(){return tx(c->{try(PreparedStatement s=statement(c,"SELECT 1");ResultSet result=s.executeQuery()){return result.next()&&result.getInt(1)==1;}});}
  @Override public void close(){pool.close();}
}

package io.github.cheshmakzanoon.portfolio.handoff;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.cheshmakzanoon.portfolio.handoff.Definition.*;
import io.github.cheshmakzanoon.portfolio.handoff.Interpreter.*;
import java.net.URI;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

public final class ScenarioMain {
  private ScenarioMain() {}

  static final ObjectMapper JSON = new ObjectMapper();

  static void check(boolean condition, String message) {
    if (!condition) throw new AssertionError(message);
  }

  static WorkflowStore store() {
    return new WorkflowStore(
        System.getenv("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
  }

  static Process child(String main, String... args) throws Exception {
    List<String> command =
        new ArrayList<>(
            List.of(
                Path.of(System.getProperty("java.home"), "bin", "java").toString(),
                "-Xmx128m",
                "-Dloader.main=" + main,
                "-cp",
                System.getProperty("java.class.path"),
                "org.springframework.boot.loader.launch.PropertiesLauncher"));
    command.addAll(List.of(args));
    return new ProcessBuilder(command)
        .redirectErrorStream(true)
        .redirectOutput(
            ProcessBuilder.Redirect.appendTo(Path.of("target", "scenario-process.log").toFile()))
        .start();
  }

  static void kill(Process process) throws Exception {
    process.destroyForcibly();
    check(process.waitFor(10, TimeUnit.SECONDS), "process failed to stop");
  }

  static void waitFile(Path file, Process process) throws Exception {
    long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(60);
    while (!Files.exists(file) && process.isAlive() && System.nanoTime() < until) Thread.sleep(20);
    check(
        Files.exists(file),
        "worker failed before effect boundary; inspect target/scenario-process.log");
  }

  static long effects(UUID instance, String task) throws Exception {
    Path log = Path.of(System.getenv("EFFECT_LOG"));
    if (!Files.exists(log)) return 0;
    try (var lines = Files.lines(log)) {
      return lines.filter(l -> l.startsWith("EFFECT\t" + instance + ":" + task + "\t")).count();
    }
  }

  static WorkflowStore.Claim ready(WorkflowStore store, String tenant) throws Exception {
    long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
    while (System.nanoTime() < until) {
      store.tick(256);
      List<WorkflowStore.Claim> claims = store.claim(tenant, "demo-worker", 1, 60);
      if (!claims.isEmpty()) return claims.getFirst();
      Thread.sleep(100);
    }
    throw new AssertionError("expected ready activity");
  }

  public static void main(String[] args) throws Exception {
    Files.createDirectories(Path.of("target"));
    WorkflowStore store = store();
    String tenant = "scenario-" + UUID.randomUUID();
    List<Map<String, Object>> timeline = new ArrayList<>();
    long started = System.nanoTime();
    URI provider = URI.create(System.getenv("PROVIDER_URL"));
    Definition order = Fixtures.order(1, Safety.IDEMPOTENT_WITH_KEY);
    String hash = store.deploy(tenant, order);
    UUID id = store.start(tenant, hash, "order-start", Map.of("order", "synthetic-42"));
    check(
        id.equals(store.start(tenant, hash, "order-start", Map.of("order", "synthetic-42"))),
        "duplicate start changed identity");
    WorkflowStore.Claim first = store.claim(tenant, "killed-worker", 1, 30).getFirst();
    Path marker = Path.of("target", "effect-" + id);
    Process worker =
        child(
            ScenarioWorker.class.getName(),
            Base64.getEncoder().encodeToString(JSON.writeValueAsBytes(first)),
            marker.toAbsolutePath().toString());
    waitFile(marker, worker);
    kill(worker);
    long recoveryStart=System.nanoTime();
    check(effects(id, "reserve") == 1, "independent log has no effect");
    Thread.sleep(31000);
    store.tick(256);
    long version = store.get(tenant, id).version();
    boolean rejected = false;
    try {
      store.complete(first, "stale");
    } catch (IllegalStateException stale) {
      rejected = stale.getMessage().equals("STALE_GENERATION");
    }
    check(
        rejected && version == store.get(tenant, id).version(), "stale completion mutated history");
    try (Worker retry = new Worker(store, provider)) {
      WorkflowStore.Claim successor = ready(store, tenant);
      store.complete(successor, retry.execute(successor, "duplicate"));
    }
    check(effects(id, "reserve") == 1, "idempotent recovery duplicated external effect");
    check(store.get(tenant, id).state() == State.WAITING, "order should wait for approval");
    Path schedulerReady=Path.of("target","scheduler-ready-"+id).toAbsolutePath();
    Process scheduler = child(RuntimeMain.class.getName(), "scheduler",schedulerReady.toString());
    waitFile(schedulerReady,scheduler);
    kill(scheduler);
    Files.delete(schedulerReady);
    scheduler = child(RuntimeMain.class.getName(), "scheduler",schedulerReady.toString());
    waitFile(schedulerReady,scheduler);
    try {
      check(hash.equals(store.get(tenant, id).definitionHash()), "restart changed pin");
      String upgraded = store.deploy(tenant, Fixtures.order(2, Safety.IDEMPOTENT_WITH_KEY));
      check(
          !hash.equals(upgraded) && hash.equals(store.get(tenant, id).definitionHash()),
          "definition upgrade mutated running execution");
      check(store.signal(tenant, id, "approval", "approval", "yes"), "signal not accepted");
      check(
          store.signal(tenant, id, "approval", "approval", "yes"),
          "duplicate signal not accepted idempotently");
      try (Worker resume = new Worker(store, provider)) {
        WorkflowStore.Claim ship = ready(store, tenant);
        store.complete(ship, resume.execute(ship, "normal"));
      }
      check(store.get(tenant, id).state() == State.COMPLETED, "order did not finish");
    } finally {
      kill(scheduler);
    }
    timeline.add(
        Map.of(
            "event",
            "killed-worker-and-restarted-scheduler-idempotent-recovery",
            "elapsedSeconds",
            (System.nanoTime() - started) / 1e9,
            "effectCount",
            effects(id, "reserve"),"recoveryDelaySeconds",(System.nanoTime()-recoveryStart)/1e9));
    String unknownTenant = tenant + "-u";
    Definition unsafe =
        new Definition(
            "uncertain",
            1,
            List.of(
                Fixtures.node(
                    "charge", Kind.ACTIVITY, List.of(), "charge", Safety.NON_IDEMPOTENT, null, 0)));
    UUID unsafeId =
        store.start(unknownTenant, store.deploy(unknownTenant, unsafe), "unknown", Map.of());
    WorkflowStore.Claim uncertain = store.claim(unknownTenant, "unsafe-worker", 1, 30).getFirst();
    Path unsafeMarker = Path.of("target", "effect-" + unsafeId);
    Process unsafeWorker =
        child(
            ScenarioWorker.class.getName(),
            Base64.getEncoder().encodeToString(JSON.writeValueAsBytes(uncertain)),
            unsafeMarker.toAbsolutePath().toString());
    waitFile(unsafeMarker, unsafeWorker);
    kill(unsafeWorker);
    Thread.sleep(31000);
    store.tick(256);
    check(
        store.get(unknownTenant, unsafeId).state() == State.MANUAL_REVIEW,
        "non-idempotent ambiguity hidden");
    check(
        store.claim(unknownTenant, "automatic", 1, 10).isEmpty(),
        "non-idempotent automatically repeated");
    check(effects(unsafeId, "charge") == 1, "unsafe call repeated");
    store.resolve(
        unknownTenant,
        unsafeId,
        "charge",
        "APPLIED",
        "demo-operator",
        "independent receipt confirmed");
    check(
        store.history(unknownTenant, unsafeId).getLast().type() == EventType.OPERATOR_RESOLVED,
        "operator decision not appended");
    timeline.add(
        Map.of(
            "event",
            "unknown-outcome-paused-and-audited-resolution",
            "elapsedSeconds",
            (System.nanoTime() - started) / 1e9,
            "effectCount",
            effects(unsafeId, "charge")));
    String undoTenant = tenant + "-c";
    UUID undoId = store.start(undoTenant, store.deploy(undoTenant, order), "compensate", Map.of());
    try (Worker action = new Worker(store, provider)) {
      WorkflowStore.Claim reserve = ready(store, undoTenant);
      store.complete(reserve, action.execute(reserve, "normal"));
      store.cancel(undoTenant, undoId);
      for (int n = 0; n < 4; n++) {
        WorkflowStore.Claim undo = ready(store, undoTenant);
        try {
          action.execute(undo, "reject");
          throw new AssertionError("provider should reject compensation");
        } catch (Worker.ProviderRejectedException expected) {
          store.fail(undo, true, "provider rejected compensation");
        }
      }
    }
    check(
        store.get(undoTenant, undoId).state() == State.COMPENSATION_FAILED,
        "failed compensation invisible");
    timeline.add(
        Map.of(
            "event",
            "compensation-failed-visibly",
            "elapsedSeconds",
            (System.nanoTime() - started) / 1e9));
    // Media fixture demonstrates bounded parallel-all joining actual compiled activities.
    String mediaTenant = tenant + "-m";
    UUID media =
        store.start(mediaTenant, store.deploy(mediaTenant, Fixtures.media()), "media", Map.of());
    try (Worker action = new Worker(store, provider)) {
      while (store.get(mediaTenant, media).state() != State.COMPLETED) {
        for (WorkflowStore.Claim q : store.claim(mediaTenant, "media", 4, 60))
          store.complete(q, action.execute(q, "normal"));
      }
    }
    Map<String, Object> result =
        Map.of(
            "schemaVersion",
            1,
            "project",
            "handoff",
            "workload",
            "asserted-fault-demo-v1",
            "timestamp",
            Instant.now().toString(),
            "assertions",
            Map.of("failed", 0, "scenarios", 5),
            "timeline",
            timeline,
            "orderId",
            id.toString(),
            "unsafeId",
            unsafeId.toString(),
            "compensationId",
            undoId.toString(),
            "mediaId",
            media.toString());
    JSON.writerWithDefaultPrettyPrinter()
        .writeValue(Path.of("target", "demo-result.json").toFile(), result);
    System.out.println(JSON.writeValueAsString(result));
  }
}

package io.github.cheshmakzanoon.portfolio.handoff;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.nio.file.*;
import java.util.*;

/**
 * Fault target killed by demo after a provider receipt exists and before engine acknowledgement.
 */
public final class ScenarioWorker {
  private ScenarioWorker() {}

  public static void main(String[] args) throws Exception {
    WorkflowStore store =
        new WorkflowStore(
            System.getenv("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
    WorkflowStore.Claim q =
        new ObjectMapper()
            .readValue(Base64.getDecoder().decode(args[0]), WorkflowStore.Claim.class);
    try (Worker worker = new Worker(store, URI.create(System.getenv("PROVIDER_URL")))) {
      String receipt = worker.execute(q, "normal");
      Files.writeString(Path.of(args[1]), receipt);
      Thread.sleep(60000);
      store.complete(q, receipt);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.handoff;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.cheshmakzanoon.portfolio.handoff.Definition.*;
import java.nio.file.*;
import java.sql.*;
import java.time.*;
import java.util.*;

/** Closed-loop database boundary driver; independent worker/scheduler processes do the work. */
public final class WorkloadMain {
  private WorkloadMain() {}

  public static void main(String[] args) throws Exception {
    int executions = args.length == 0 ? 10000 : Integer.parseInt(args[0]);
    if (executions < 10 || executions > 10000)
      throw new IllegalArgumentException("10..10000 executions");
    String tenant = System.getenv().getOrDefault("TENANT", "demo"),
        url = System.getenv("DB_URL"),
        user = System.getenv("DB_USER"),
        password = System.getenv("DB_PASSWORD");
    WorkflowStore store = new WorkflowStore(url, user, password);
    String run = "w-" + UUID.randomUUID();
    String[] hashes = new String[2];
    for (int timer = 0; timer < 2; timer++) {
      List<Node> nodes = new ArrayList<>();
      nodes.add(Fixtures.node("approval", Kind.SIGNAL, List.of(), null, null, null, 604800));
      if (timer == 1)
        nodes.add(Fixtures.node("wait", Kind.TIMER, List.of("approval"), null, null, null, 1));
      for (int n = 0; n < 8; n++)
        nodes.add(
            Fixtures.node(
                "a" + n,
                Kind.ACTIVITY,
                List.of(n == 0 ? (timer == 1 ? "wait" : "approval") : "a" + (n - 1)),
                "reserve",
                Safety.IDEMPOTENT_WITH_KEY,
                null,
                0));
      hashes[timer] = store.deploy(tenant, new Definition("load-" + timer, 1, nodes));
    }
    long databaseBefore;try(Connection c=DriverManager.getConnection(url,user,password);Statement query=c.createStatement();ResultSet r=query.executeQuery("SELECT pg_database_size(current_database())")){r.next();databaseBefore=r.getLong(1);}
    Instant startedAt=Instant.now();
    long start = System.nanoTime();
    List<UUID> ids = new ArrayList<>();
    for (int n = 0; n < executions; n++) {
      UUID id =
          store.start(
              tenant,
              hashes[n % 2],
              run + "-" + n,
              Map.of("ordinal", Integer.toString(n), "run", run));
      ids.add(id);
      if (!store.signal(tenant, id, "approval", "approval", "yes")
          || !store.signal(tenant, id, "approval", "approval", "yes"))
        throw new AssertionError("signal lost");
    }
    long until = System.nanoTime() + java.util.concurrent.TimeUnit.MINUTES.toNanos(30);
    long completed = 0;
    List<Map<String, Object>> timeline = new ArrayList<>();
    long maximumQueue=0;
    while (completed < executions && System.nanoTime() < until) {
      try (Connection c = DriverManager.getConnection(url, user, password);
          PreparedStatement s =
              c.prepareStatement(
                  "SELECT state,count(*) FROM workflow_instance WHERE tenant=? AND start_key LIKE ? GROUP BY state")) {
        s.setString(1, tenant);
        s.setString(2, run + "-%");
        try (ResultSet r = s.executeQuery()) {
          completed = 0;
          while (r.next()) {
            String state = r.getString(1);
            long count = r.getLong(2);
            if (state.equals("COMPLETED")) completed = count;
            if (Set.of("FAILED", "COMPENSATION_FAILED", "MANUAL_REVIEW").contains(state))
              throw new AssertionError("failed workload: " + state);
          }
        }
      }
      long queue;try(Connection c=DriverManager.getConnection(url,user,password);PreparedStatement q=c.prepareStatement("SELECT count(*) FROM activity_task t JOIN workflow_instance i ON i.id=t.instance_id WHERE i.tenant=? AND i.start_key LIKE ? AND t.status IN ('READY','LEASED')")){q.setString(1,tenant);q.setString(2,run+"-%");try(ResultSet r=q.executeQuery()){r.next();queue=r.getLong(1);}}maximumQueue=Math.max(maximumQueue,queue);
      timeline.add(Map.of("elapsedSeconds",(System.nanoTime()-start)/1e9,"completed",completed,"queueDepth",queue));
      System.out.println("completed " + completed + "/" + executions);
      Thread.sleep(500);
    }
    if (completed != executions) throw new AssertionError("workload deadline exceeded");
    Map<String, Object> measurements = new LinkedHashMap<>();
    measurements.put("elapsedSeconds", (System.nanoTime() - start) / 1e9);
    measurements.put("executions", executions);
    measurements.put("activities", executions * 8);
    measurements.put("timerWaits", executions / 2);
    measurements.put("seed", 42);
    measurements.put("peakSampledQueueDepth",maximumQueue);
    measurements.put("expectedTransientFirstFailures",executions*8/5);
    measurements.put("databaseBytesBefore",databaseBefore);
    measurements.put(
        "driverHeapUsedBytes",
        Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory());
    try (Connection c = DriverManager.getConnection(url, user, password)) {
      for (String[] metric :
          new String[][] {
            {
              "completionLatencyMs",
              "SELECT percentile_cont(ARRAY[0.5,0.95,0.99]) WITHIN GROUP(ORDER BY extract(epoch FROM(h.at-i.created_at))*1000) FROM workflow_instance i JOIN LATERAL(SELECT max(at) at FROM workflow_history WHERE instance_id=i.id)h ON true WHERE i.tenant=? AND i.start_key LIKE ?"
            },
            {
              "scheduleToStartMs",
              "SELECT percentile_cont(ARRAY[0.5,0.95,0.99]) WITHIN GROUP(ORDER BY extract(epoch FROM(a.dispatched_at-t.created_at))*1000) FROM activity_task t JOIN workflow_instance i ON i.id=t.instance_id JOIN activity_attempt a ON a.instance_id=t.instance_id AND a.logical_id=t.logical_id WHERE i.tenant=? AND i.start_key LIKE ? AND a.dispatched_at IS NOT NULL"
            },
            {
              "attemptsPerLogicalTask",
              "SELECT avg(t.attempt) FROM activity_task t JOIN workflow_instance i ON i.id=t.instance_id WHERE i.tenant=? AND i.start_key LIKE ?"
            },
            {
              "queuedAtEnd",
              "SELECT count(*) FROM activity_task t JOIN workflow_instance i ON i.id=t.instance_id WHERE i.tenant=? AND i.start_key LIKE ? AND t.status IN ('READY','LEASED')"
            },
            {"leaseExpirations","SELECT count(*) FROM activity_attempt a JOIN workflow_instance i ON i.id=a.instance_id WHERE i.tenant=? AND i.start_key LIKE ? AND a.outcome='LEASE_EXPIRED'"},
            {"transientRejectedAttempts","SELECT count(*) FROM activity_attempt a JOIN workflow_instance i ON i.id=a.instance_id WHERE i.tenant=? AND i.start_key LIKE ? AND a.outcome='REJECTED'"},
            {
              "timerLatenessMs",
              "SELECT percentile_cont(ARRAY[0.5,0.95,0.99]) WITHIN GROUP(ORDER BY extract(epoch FROM(h.at-t.due_at))*1000) FROM timer t JOIN workflow_instance i ON i.id=t.instance_id JOIN workflow_history h ON h.instance_id=t.instance_id AND h.task=t.logical_id AND h.type='TIMER_FIRED' WHERE i.tenant=? AND i.start_key LIKE ?"
            }
          }) {
        try (PreparedStatement s = c.prepareStatement(metric[1])) {
          s.setString(1, tenant);
          s.setString(2, run + "-%");
          try (ResultSet r = s.executeQuery()) {
            r.next();
            measurements.put(metric[0], r.getString(1));
          }
        }
      }
      try (Statement s = c.createStatement();
          ResultSet r = s.executeQuery("SELECT pg_database_size(current_database())")) {
        r.next();
        measurements.put("databaseBytesAtEnd", r.getLong(1));measurements.put("databaseGrowthBytes",r.getLong(1)-databaseBefore);
      }
    }
    if(Long.parseLong((String)measurements.get("queuedAtEnd"))!=0)throw new AssertionError("queue not drained");
    if(Long.parseLong((String)measurements.get("transientRejectedAttempts"))!=executions*8L/5)throw new AssertionError("transient workload did not produce exactly 20% first-attempt rejection");
    Map<String, Object> result =
        Map.of(
            "schemaVersion",
            1,
            "project",
            "handoff",
            "workload",
            "seeded-eight-activities-v1",
            "startedAt",
            startedAt.toString(),
            "measurements",
            measurements,
            "timeline",
            timeline,
            "limitations",
            List.of(
                "Closed-loop submissions and shared host: coordinated omission possible",
                "Recovery/lease expiry measured separately by fault demo",
                "Database size includes prior demo data; run reset-demo first"));
    Path out = Path.of(System.getenv().getOrDefault("RESULT_FILE", "target/workload.json"));
    Files.createDirectories(out.toAbsolutePath().getParent());
    new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(out.toFile(), result);
    System.out.println("asserted workload evidence: " + out);
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Binary.*;
import static io.github.cheshmakzanoon.portfolio.majority.Model.*;

import io.netty.bootstrap.Bootstrap;
import io.netty.buffer.*;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

/** One outstanding mutation per identity; unknown outcomes retain the exact command. */
public final class KvClient implements AutoCloseable {
  private final TlsTransport.Settings settings;
  private final EventLoopGroup group = new NioEventLoopGroup(1);
  private final Map<Integer, Channel> channels = new HashMap<>();
  private final Map<Long, CompletableFuture<Result>> pending = new ConcurrentHashMap<>();
  private final AtomicLong correlation = new AtomicLong();
  private final MutationIdentity mutationIdentity;

  public KvClient(TlsTransport.Settings settings, String identity) {
    this.settings = settings;
    this.mutationIdentity = new MutationIdentity(identity);
  }

  public synchronized Result mutate(Kind kind, Key key, byte[] value, byte[] expected)
      throws Exception {
    Command requested = mutationIdentity.begin(kind, key, value, expected);
    Result result = retry(new Mutation(requested));
    mutationIdentity.resolve(result);
    return result;
  }

  public Result get(Key key) throws Exception {
    return retry(new Get(key));
  }

  private Result retry(Body body) throws Exception {
    Result result = new Result("UNKNOWN_OUTCOME", null, -1);
    for (int attempt = 0; attempt < 9; attempt++) {
      int node =
          result.code().equals("NOT_LEADER") && result.leader() >= 0 && result.leader() < 3
              ? result.leader()
              : attempt % 3;
      result = request(node, 3, body, 1800);
      if (!Set.of("NOT_LEADER", "UNAVAILABLE", "UNKNOWN_OUTCOME").contains(result.code()))
        return result;
    }
    return result;
  }

  public Result admin(int node, String action, int peer) throws Exception {
    return request(node, 4, new Admin(action, peer), 2500);
  }

  public Result direct(int node, Body body, long timeout) throws Exception {
    return request(node, 3, body, timeout);
  }

  private Result request(int node, int source, Body body, long timeout) throws Exception {
    if (pending.size() >= 256) return new Result("RESOURCE_EXHAUSTED", null, -1);
    long id = correlation.incrementAndGet();
    var future = new CompletableFuture<Result>();
    pending.put(id, future);
    try {
      Channel channel = channel(node);
      if (!channel.isWritable()) return new Result("RESOURCE_EXHAUSTED", null, -1);
      channel.writeAndFlush(
          Unpooled.wrappedBuffer(
              encode(new Envelope(source, node, settings.token(source), id, body))));
      return future.get(timeout, TimeUnit.MILLISECONDS);
    } catch (TimeoutException | ExecutionException | java.net.ConnectException e) {
      return new Result("UNKNOWN_OUTCOME", null, -1);
    } finally {
      pending.remove(id);
    }
  }

  private synchronized Channel channel(int node) throws Exception {
    Channel existing = channels.get(node);
    if (existing != null && existing.isActive()) return existing;
    var tls = TlsTransport.clientContext(settings);
    Channel created =
        new Bootstrap()
            .group(group)
            .channel(NioSocketChannel.class)
            .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 500)
            .handler(
                new ChannelInitializer<SocketChannel>() {
                  protected void initChannel(SocketChannel ch) {
                    ch.pipeline()
                        .addLast(TlsTransport.handler(tls, ch, settings.basePort() + node));
                    TlsTransport.frames(ch.pipeline());
                    ch.pipeline()
                        .addLast(
                            new SimpleChannelInboundHandler<ByteBuf>() {
                              protected void channelRead0(ChannelHandlerContext ctx, ByteBuf buffer)
                                  throws Exception {
                                byte[] bytes = new byte[buffer.readableBytes()];
                                buffer.readBytes(bytes);
                                Envelope e = decode(bytes);
                                if (e.source() != node
                                    || !MessageDigest.isEqual(
                                        e.token().getBytes(java.nio.charset.StandardCharsets.UTF_8),
                                        settings
                                            .token(node)
                                            .getBytes(java.nio.charset.StandardCharsets.UTF_8))
                                    || !(e.body() instanceof Response response)) {
                                  ctx.close();
                                  return;
                                }
                                CompletableFuture<Result> f = pending.get(e.correlation());
                                if (f != null) f.complete(response.result());
                              }

                              @Override
                              public void exceptionCaught(
                                  ChannelHandlerContext ctx, Throwable error) {
                                ctx.close();
                              }
                            });
                  }
                })
            .connect("localhost", settings.basePort() + node)
            .sync()
            .channel();
    channels.put(node, created);
    return created;
  }

  @Override
  public void close() {
    channels.values().forEach(c -> c.close().awaitUninterruptibly());
    group.shutdownGracefully(0, 1, TimeUnit.SECONDS).awaitUninterruptibly();
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Model.*;

import java.util.Arrays;

/** Retry identity is retained until a definitive committed mutation result. */
public final class MutationIdentity {
  private final String client;
  private long sequence = 1;
  private Command pending;

  public MutationIdentity(String client) {
    this.client = client;
  }

  public synchronized Command begin(Kind kind, Key key, byte[] value, byte[] expected) {
    Command command = new Command(client, sequence, kind, key, value, expected);
    if (pending != null && !Arrays.equals(pending.digest(), command.digest()))
      throw new IllegalStateException("UNKNOWN_OUTCOME_RETRY_SAME_MUTATION");
    pending = command;
    return command;
  }

  public synchronized void resolve(Result result) {
    if (result.code().equals("OK") || result.code().equals("CAS_MISMATCH")) {
      sequence++;
      pending = null;
    }
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Binary.*;
import static io.github.cheshmakzanoon.portfolio.majority.Model.*;
import static io.github.cheshmakzanoon.portfolio.majority.Raft.*;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/** One protocol owner, one bounded disk queue; Netty threads only submit typed events. */
public final class NodeMain implements AutoCloseable {
  private record Waiting(Consumer<Result> response, long deadline) {}

  private final ThreadPoolExecutor owner =
      new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS, new ArrayBlockingQueue<>(512));
  private final ExecutorService disk = Executors.newSingleThreadExecutor();
  private final ScheduledExecutorService timer = Executors.newSingleThreadScheduledExecutor();
  private final Journal journal;
  private final Raft raft;
  private final TlsTransport transport;
  private final Set<Integer> partitioned = new HashSet<>();
  private final Map<Long, Waiting> waiting = new HashMap<>();
  private long serial;
  private volatile boolean fatal;
  private volatile long snapshotLastNanos, snapshotCount, flushCount;

  public NodeMain(int id, Path directory, TlsTransport.Settings settings) throws Exception {
    journal = new Journal(directory);
    raft = new Raft(id, new SecureRandom().nextInt(Integer.MAX_VALUE), journal.recovered());
    transport = new TlsTransport(id, settings, this::receive);
  }

  public void start() throws Exception {
    transport.start();
    timer.scheduleAtFixedRate(
        () ->
            submit(
                () -> {
                  long now = System.nanoTime() / 1_000_000;
                  drive(new Tick(now));
                  var it = waiting.entrySet().iterator();
                  while (it.hasNext()) {
                    Waiting w = it.next().getValue();
                    if (w.deadline() < now) {
                      w.response().accept(new Result("UNKNOWN_OUTCOME", null, raft.leader()));
                      it.remove();
                    }
                  }
                }),
        10,
        10,
        TimeUnit.MILLISECONDS);
  }

  private Runnable guard(Runnable action){return ()->{try{action.run();}catch(Throwable error){fatal=true;System.err.println("FAIL_CLOSED "+error.getClass().getSimpleName()+": "+error.getMessage());}};}
  private boolean submit(Runnable action){if(fatal)return false;try{owner.execute(guard(action));return true;}catch(RejectedExecutionException ignored){return false;}}

  private void receive(Envelope envelope, Consumer<Result> response) {
    boolean accepted =
        submit(
            () -> {
              if (envelope.body() instanceof Peer peer) {
                if (!partitioned.contains(envelope.source()))
                  drive(new Receive(envelope.source(), peer.rpc()));
                return;
              }
              if (envelope.body() instanceof Admin admin) {
                admin(admin, response);
                return;
              }
              if (waiting.size() >= MAX_PENDING) {
                response.accept(new Result("RESOURCE_EXHAUSTED", null, raft.leader()));
                return;
              }
              long request = ++serial;
              waiting.put(request, new Waiting(response, System.nanoTime() / 1_000_000 + 1200));
              if (envelope.body() instanceof Mutation m) drive(new Mutate(request, m.command()));
              else if (envelope.body() instanceof Get g) drive(new Read(request, g.key()));
            });
    if (!accepted) response.accept(new Result("RESOURCE_EXHAUSTED", null, -1));
  }

  private void drive(Event event) {
    for (Effect effect : raft.accept(event)) {
      switch (effect) {
        case Persist p ->
            disk.execute(
                () -> {
                  try {
                    boolean snapshot =
                        p.durable().snapshot().index() != journal.recovered().snapshot().index();
                    long begin = System.nanoTime();
                    journal.persist(p.durable());
                    flushCount++;
                    if (snapshot) {
                      snapshotLastNanos = System.nanoTime() - begin;
                      snapshotCount++;
                    }
                    if (!submit(() -> drive(new Persisted(p.token())))) {
                      if (!fatal) owner.getQueue().put(guard(() -> drive(new Persisted(p.token()))));
                    }
                  } catch (Exception error) {
                    fatal = true;
                    System.err.println("FAIL_CLOSED_DISK " + error.getMessage());
                  }
                });
        case Send s -> {
          if (!partitioned.contains(s.peer())) transport.send(s.peer(), s.rpc());
        }
        case Reply r -> {
          Waiting w = waiting.remove(r.request());
          if (w != null) w.response().accept(r.result());
        }
        case Applied ignored -> {}
      }
    }
    if (!raft.waitingForDisk() && raft.applied() - raft.durable().snapshot().index() >= 128)
      drive(new TakeSnapshot());
  }

  private void admin(Admin admin, Consumer<Result> response) {
    switch (admin.action()) {
      case "status" ->
          response.accept(
              new Result("OK", status().getBytes(StandardCharsets.UTF_8), raft.leader()));
      case "partition" -> {
        partitioned.add(admin.peer());
        response.accept(new Result("OK", null, raft.leader()));
      }
      case "heal" -> {
        partitioned.clear();
        response.accept(new Result("OK", null, raft.leader()));
      }
      case "snapshot" -> {
        drive(new TakeSnapshot());
        response.accept(new Result("OK", null, raft.leader()));
      }
      default -> response.accept(new Result("INVALID_ADMIN", null, raft.leader()));
    }
  }

  private String status() {
    try {
      Snapshot s = raft.view();
      Snapshot state = new Snapshot(0, 0, CLUSTER, s.data(), s.sessions());
      String digest =
          HexFormat.of()
              .formatHex(MessageDigest.getInstance("SHA-256").digest(Codec.snapshot(state)));
      return "node="
          + raft.id()
          + " role="
          + raft.role()
          + " term="
          + raft.term()
          + " commit="
          + raft.commit()
          + " applied="
          + raft.applied()
          + " snapshot="
          + raft.durable().snapshot().index()
          + " digest="
          + digest
          + " snapshots="
          + snapshotCount
          + " snapshotMicros="
          + snapshotLastNanos / 1000
          + " flushes="
          + flushCount
          + " disk="
          + raft.waitingForDisk()
          + " pending="
          + waiting.size();
    } catch (NoSuchAlgorithmException e) {
      throw new AssertionError(e);
    }
  }

  @Override
  public void close() throws Exception {
    timer.shutdownNow();
    transport.close();
    disk.shutdown();
    if(!disk.awaitTermination(5,TimeUnit.SECONDS))throw new java.io.IOException("DISK_SHUTDOWN_TIMEOUT");
    owner.shutdown();
    owner.awaitTermination(5, TimeUnit.SECONDS);
    journal.close();
  }

  public static void main(String[] args) throws Exception {
    if (args.length != 4)
      throw new IllegalArgumentException("nodeId dataDirectory tlsDirectory basePort");
    var node =
        new NodeMain(
            Integer.parseInt(args[0]),
            Path.of(args[1]),
            TlsTransport.Settings.load(Path.of(args[2]), Integer.parseInt(args[3])));
    Runtime.getRuntime()
        .addShutdownHook(
            new Thread(
                () -> {
                  try {
                    node.close();
                  } catch (Exception e) {
                    System.err.println("shutdown " + e.getMessage());
                  }
                }));
    node.start();
    new CountDownLatch(1).await();
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import java.io.*;
import java.security.*;
import java.util.*;

/** Immutable protocol values. Binary arrays are copied at the public boundary. */
public final class Model {
  private Model() {}

  public static final String CLUSTER = "majority-local-v1";
  public static final int MAX_KEY = 256,
      MAX_VALUE = 4096,
      MAX_CLIENTS = 1024,
      MAX_DATA = 16 * 1024 * 1024,
      MAX_PENDING = 256,
      MAX_KEYS = 16384,
      MAX_SNAPSHOT = 24 * 1024 * 1024;

  public record Key(byte[] bytes) implements Comparable<Key> {
    public Key {
      bytes = bytes.clone();
      if (bytes.length > MAX_KEY) throw new IllegalArgumentException("KEY_LIMIT");
    }

    @Override
    public byte[] bytes() {
      return bytes.clone();
    }

    @Override
    public int compareTo(Key other) {
      return Arrays.compareUnsigned(bytes, other.bytes);
    }

    @Override
    public boolean equals(Object o) {
      return o instanceof Key k && Arrays.equals(bytes, k.bytes);
    }

    @Override
    public int hashCode() {
      return Arrays.hashCode(bytes);
    }
  }

  public enum Kind {
    PUT,
    DELETE,
    CAS
  }

  public record Command(
      String client, long sequence, Kind kind, Key key, byte[] value, byte[] expected) {
    public Command {
      Objects.requireNonNull(client);
      Objects.requireNonNull(kind);
      Objects.requireNonNull(key);
      if (kind != Kind.DELETE && value == null)
        throw new IllegalArgumentException("VALUE_REQUIRED");
      value = copy(value);
      expected = copy(expected);
      if (client.length() > 128
          || client.isBlank()
          || sequence < 1
          || length(value) > MAX_VALUE
          || length(expected) > MAX_VALUE) throw new IllegalArgumentException("REQUEST_LIMIT");
    }

    @Override
    public byte[] value() {
      return copy(value);
    }

    @Override
    public byte[] expected() {
      return copy(expected);
    }

    public byte[] digest() {
      try {
        return MessageDigest.getInstance("SHA-256").digest(Codec.command(this));
      } catch (NoSuchAlgorithmException e) {
        throw new AssertionError(e);
      }
    }
  }

  public record Result(String code, byte[] value, int leader) {
    public Result {
      value = copy(value);
    }

    @Override
    public byte[] value() {
      return copy(value);
    }

    @Override
    public boolean equals(Object o) {
      return o instanceof Result r
          && code.equals(r.code)
          && leader == r.leader
          && Arrays.equals(value, r.value);
    }

    @Override
    public int hashCode() {
      return Objects.hash(code, Arrays.hashCode(value), leader);
    }
  }

  public record Session(long sequence, byte[] digest, Result result) {
    public Session {
      digest = digest.clone();
    }

    @Override
    public byte[] digest() {
      return digest.clone();
    }
  }

  public record Entry(long index, long term, Command command) {}

  public record Snapshot(
      long index,
      long term,
      String cluster,
      NavigableMap<Key, byte[]> data,
      Map<String, Session> sessions) {
    public Snapshot {
      var d = new TreeMap<Key, byte[]>();
      data.forEach((k, v) -> d.put(k, v.clone()));
      data = Collections.unmodifiableNavigableMap(d);
      sessions = Map.copyOf(sessions);
    }

    @Override
    public NavigableMap<Key, byte[]> data() {
      var copy = new TreeMap<Key, byte[]>();
      data.forEach((k, v) -> copy.put(k, v.clone()));
      return Collections.unmodifiableNavigableMap(copy);
    }

    public static Snapshot empty() {
      return new Snapshot(0, 0, CLUSTER, new TreeMap<>(), Map.of());
    }
  }

  public record Durable(long term, int vote, long commit, Snapshot snapshot, List<Entry> log) {
    public Durable {
      log = List.copyOf(log);
      if (term < 0 || commit < snapshot.index())
        throw new IllegalArgumentException("INVALID_STATE");
      long i = snapshot.index();
      long previousTerm = snapshot.term();
      for (Entry e : log) {
        if (e.index() != ++i || e.term() > term || e.term() < 1 || e.term() < previousTerm)
          throw new IllegalArgumentException("NONCONTIGUOUS_LOG");
        previousTerm = e.term();
      }
      if (commit > i) throw new IllegalArgumentException("COMMIT_BEYOND_LOG");
    }

    public static Durable empty() {
      return new Durable(0, -1, 0, Snapshot.empty(), List.of());
    }
  }

  public sealed interface Rpc
      permits VoteRequest,
          VoteResponse,
          AppendRequest,
          AppendResponse,
          SnapshotRequest,
          SnapshotResponse {
    long term();

    long request();
  }

  public record VoteRequest(long term, long request, int candidate, long lastIndex, long lastTerm)
      implements Rpc {}

  public record VoteResponse(long term, long request, boolean granted) implements Rpc {}

  public record AppendRequest(
      long term,
      long request,
      int leader,
      long previousIndex,
      long previousTerm,
      List<Entry> entries,
      long commit,
      long read)
      implements Rpc {
    public AppendRequest {
      entries = List.copyOf(entries);
    }
  }

  public record AppendResponse(long term, long request, boolean success, long match, long read)
      implements Rpc {}

  public record SnapshotRequest(
      long term,
      long request,
      int leader,
      long index,
      long snapshotTerm,
      int offset,
      int total,
      byte[] chunk)
      implements Rpc {
    public SnapshotRequest {
      chunk = chunk.clone();
    }

    @Override
    public byte[] chunk() {
      return chunk.clone();
    }
  }

  public record SnapshotResponse(long term, long request, long index, int nextOffset, boolean done)
      implements Rpc {}

  static byte[] copy(byte[] b) {
    return b == null ? null : b.clone();
  }

  static int length(byte[] b) {
    return b == null ? 0 : b.length;
  }

  /** Strict versioned serialization shared with adapters; never Java object deserialization. */
  public static final class Codec {
    private Codec() {}

    public interface Writer {
      void write(DataOutputStream out) throws IOException;
    }

    public static byte[] encode(Writer writer) {
      try {
        var b = new ByteArrayOutputStream();
        try (var out = new DataOutputStream(b)) {
          writer.write(out);
        }
        return b.toByteArray();
      } catch (IOException e) {
        throw new UncheckedIOException(e);
      }
    }

    public static void bytes(DataOutputStream out, byte[] b) throws IOException {
      out.writeInt(b == null ? -1 : b.length);
      if (b != null) out.write(b);
    }

    public static byte[] bytes(DataInputStream in, int max) throws IOException {
      int n = in.readInt();
      if (n == -1) return null;
      if (n < 0 || n > max || n > in.available()) throw new IOException("INVALID_LENGTH");
      return in.readNBytes(n);
    }

    public static byte[] command(Command c) {
      return encode(out -> writeCommand(out, c));
    }

    public static void writeCommand(DataOutputStream out, Command c) throws IOException {
      out.writeBoolean(c != null);
      if (c == null) return;
      out.writeUTF(c.client());
      out.writeLong(c.sequence());
      out.writeByte(c.kind().ordinal());
      bytes(out, c.key().bytes());
      bytes(out, c.value());
      bytes(out, c.expected());
    }

    public static Command readCommand(DataInputStream in) throws IOException {
      if (!in.readBoolean()) return null;
      String c = in.readUTF();
      long seq = in.readLong();
      int kind = in.readUnsignedByte();
      if (kind >= Kind.values().length) throw new IOException("KIND");
      return new Command(
          c,
          seq,
          Kind.values()[kind],
          new Key(Objects.requireNonNull(bytes(in, MAX_KEY))),
          bytes(in, MAX_VALUE),
          bytes(in, MAX_VALUE));
    }

    public static void entry(DataOutputStream out, Entry e) throws IOException {
      out.writeLong(e.index());
      out.writeLong(e.term());
      writeCommand(out, e.command());
    }

    public static Entry entry(DataInputStream in) throws IOException {
      return new Entry(in.readLong(), in.readLong(), readCommand(in));
    }

    public static byte[] snapshot(Snapshot s) {
      byte[] body =
          encode(
              out -> {
                out.writeInt(1);
                out.writeLong(s.index());
                out.writeLong(s.term());
                out.writeUTF(s.cluster());
            out.writeInt(3);out.writeInt(0);out.writeInt(1);out.writeInt(2);
                out.writeInt(s.data().size());
                for (var e : s.data().entrySet()) {
                  bytes(out, e.getKey().bytes());
                  bytes(out, e.getValue());
                }
                out.writeInt(s.sessions().size());
                for (var e : new TreeMap<>(s.sessions()).entrySet()) {
                  out.writeUTF(e.getKey());
                  out.writeLong(e.getValue().sequence());
                  bytes(out, e.getValue().digest());
                  result(out, e.getValue().result());
                }
              });
      var crc = new java.util.zip.CRC32C();
      crc.update(body);
      return java.nio.ByteBuffer.allocate(body.length + 4)
          .put(body)
          .putInt((int) crc.getValue())
          .array();
    }

    public static Snapshot snapshot(byte[] b) throws IOException {
      if (b.length < 4 || b.length > MAX_SNAPSHOT) throw new IOException("SNAPSHOT_LENGTH");
      byte[] body = Arrays.copyOf(b, b.length - 4);
      var crc = new java.util.zip.CRC32C();
      crc.update(body);
      if ((int) crc.getValue() != java.nio.ByteBuffer.wrap(b, b.length - 4, 4).getInt())
        throw new IOException("SNAPSHOT_CHECKSUM");
      b = body;
      try (var in = new DataInputStream(new ByteArrayInputStream(b))) {
        if (in.readInt() != 1) throw new IOException("SNAPSHOT_VERSION");
        long index = in.readLong(), term = in.readLong();
        String cluster = in.readUTF();
        if (!CLUSTER.equals(cluster)) throw new IOException("CLUSTER");
        if(in.readInt()!=3||in.readInt()!=0||in.readInt()!=1||in.readInt()!=2)throw new IOException("MEMBERSHIP");
        int n = count(in, MAX_KEYS);
        var data = new TreeMap<Key, byte[]>();
        int total = 0;
        for (int i = 0; i < n; i++) {
          var k = new Key(Objects.requireNonNull(bytes(in, MAX_KEY)));
          var v = Objects.requireNonNull(bytes(in, MAX_VALUE));
          total += k.bytes().length + v.length;
          if (total > MAX_DATA || data.put(k, v) != null) throw new IOException("DATA_LIMIT");
        }
        int m = count(in, MAX_CLIENTS);
        var sessions = new HashMap<String, Session>();
        for (int i = 0; i < m; i++)
          sessions.put(
              in.readUTF(),
              new Session(in.readLong(), Objects.requireNonNull(bytes(in, 32)), result(in)));
        if (in.available() != 0) throw new IOException("TRAILING");
        return new Snapshot(index, term, cluster, data, sessions);
      }
    }

    public static void result(DataOutputStream out, Result r) throws IOException {
      out.writeUTF(r.code());
      bytes(out, r.value());
      out.writeInt(r.leader());
    }

    public static Result result(DataInputStream in) throws IOException {
      return new Result(in.readUTF(), bytes(in, MAX_VALUE), in.readInt());
    }

    public static byte[] durable(Durable d) {
      return encode(
          out -> {
            out.writeInt(1);
            out.writeLong(d.term());
            out.writeInt(d.vote());
            out.writeLong(d.commit());
            bytes(out, snapshot(d.snapshot()));
            out.writeInt(d.log().size());
            for (Entry e : d.log()) entry(out, e);
          });
    }

    public static Durable durable(byte[] b) throws IOException {
      try (var in = new DataInputStream(new ByteArrayInputStream(b))) {
        if (in.readInt() != 1) throw new IOException("WAL_VERSION");
        long term = in.readLong();
        int vote = in.readInt();
        long commit = in.readLong();
        Snapshot s = snapshot(Objects.requireNonNull(bytes(in, MAX_SNAPSHOT)));
        int n = count(in, 100000);
        var log = new ArrayList<Entry>();
        for (int i = 0; i < n; i++) log.add(entry(in));
        if (in.available() != 0) throw new IOException("TRAILING");
        return new Durable(term, vote, commit, s, log);
      }
    }

    public static int count(DataInputStream in, int max) throws IOException {
      int n = in.readInt();
      if (n < 0 || n > max) throw new IOException("COUNT_LIMIT");
      return n;
    }
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Model.*;

import java.io.*;
import java.util.*;

/** Figure-2 Raft transition owner. Effects depending on stable state wait for Persisted. */
public final class Raft {
  public enum Role {
    FOLLOWER,
    CANDIDATE,
    LEADER
  }

  public sealed interface Event permits Tick, Receive, Persisted, Mutate, Read, TakeSnapshot {}

  public record Tick(long now) implements Event {}

  public record Receive(int peer, Rpc rpc) implements Event {}

  public record Persisted(long token) implements Event {}

  public record Mutate(long request, Command command) implements Event {}

  public record Read(long request, Key key) implements Event {}

  public record TakeSnapshot() implements Event {}

  public sealed interface Effect permits Persist, Send, Reply, Applied {}

  public record Persist(long token, Durable durable) implements Effect {}

  public record Send(int peer, Rpc rpc) implements Effect {}

  public record Reply(long request, Result result) implements Effect {}

  public record Applied(long index, long term, Command command, Result result) implements Effect {}

  private record Sent(long term, long previous, long last, long read) {}

  private static final class Reading {
    final long request, safe, expires;
    final Key key;
    final Set<Integer> acks = new HashSet<>();

    Reading(long request, long safe, Key key, int self, long expires) {
      this.request = request;
      this.expires = expires;
      this.safe = safe;
      this.key = key;
      acks.add(self);
    }
  }

  private final int id;
  private final long boot;
  private final Random electionRandom;
  private long term,
      commit,
      applied,
      clock,
      deadline,
      heartbeat,
      serial,
      persistSerial,
      pendingPersist;
  private int vote, leader = -1;
  private Snapshot snapshot;
  private final ArrayList<Entry> log = new ArrayList<>();
  private Registers registers;
  private Role role = Role.FOLLOWER;
  private final Set<Integer> votes = new HashSet<>();
  private final Map<Integer, Long> voteRequests = new HashMap<>();
  private final Map<Integer, SnapshotRequest> snapshotRequests = new HashMap<>();
  private final Map<Integer, Long> next = new HashMap<>(), match = new HashMap<>();
  private final Map<Integer, Map<Long, Sent>> sent = new HashMap<>();
  private final Map<Long, Long> clients = new HashMap<>();
  private final Map<Long, Reading> reads = new LinkedHashMap<>();
  private final ArrayDeque<Event> deferred = new ArrayDeque<>();
  private List<Effect> held = List.of();
  private ArrayList<Effect> out;
  private boolean dirty;
  private ByteArrayOutputStream incoming;
  private long incomingIndex, incomingTerm;
  private byte[] outgoingSnapshot;
  private final Map<Integer, Integer> snapshotOffsets = new HashMap<>();

  public Raft(int id, long boot, Durable d) {
    if (id < 0 || id > 2) throw new IllegalArgumentException("MEMBER");
    this.id = id;
    this.boot = boot;
    electionRandom = new Random(boot * 0x9e3779b97f4a7c15L + id);
    term = d.term();
    vote = d.vote();
    commit = d.commit();
    snapshot = d.snapshot();
    log.addAll(d.log());
    registers = new Registers(snapshot);
    applied = snapshot.index();
    for (int p = 0; p < 3; p++) sent.put(p, new LinkedHashMap<>());
    applyRecovered();
    resetDeadline();
  }

  public List<Effect> accept(Event event) {
    if (event instanceof Persisted a) {
      if (a.token() != pendingPersist || pendingPersist == 0) return List.of();
      pendingPersist = 0;
      out = new ArrayList<>(held);
      if (applied < snapshot.index()) {
        registers = new Registers(snapshot);
        applied = snapshot.index();
      }
      apply();
      var result = new ArrayList<>(out);
      held = List.of();
      while (pendingPersist == 0 && !deferred.isEmpty())
        result.addAll(accept(deferred.removeFirst()));
      return List.copyOf(result);
    }
    if (pendingPersist != 0) {
      if (event instanceof Tick && deferred.peekLast() instanceof Tick) deferred.removeLast();
      if (deferred.size() >= MAX_PENDING) {
        if (event instanceof Mutate m)
          return List.of(new Reply(m.request(), new Result("RESOURCE_EXHAUSTED", null, leader)));
        if (event instanceof Read r)
          return List.of(new Reply(r.request(), new Result("RESOURCE_EXHAUSTED", null, leader)));
        return List.of(); // RPC overload is network loss; bounded retry is driven by heartbeats.
      }
      deferred.add(event);
      return List.of();
    }
    out = new ArrayList<>();
    dirty = false;
    switch (event) {
      case Tick t -> tick(t.now());
      case Receive r -> receive(r.peer(), r.rpc());
      case Mutate m -> mutate(m);
      case Read r -> read(r);
      case TakeSnapshot ignored -> compact();
      case Persisted ignored -> throw new AssertionError();
    }
    if (dirty) {
      held = List.copyOf(out);
      pendingPersist = ++persistSerial;
      return List.of(new Persist(pendingPersist, durable()));
    }
    return List.copyOf(out);
  }

  public Durable durable() {
    return new Durable(term, vote, commit, snapshot, log);
  }

  public long applied() {
    return applied;
  }

  public long commit() {
    return commit;
  }

  public long term() {
    return term;
  }

  public Role role() {
    return role;
  }

  public int leader() {
    return leader;
  }

  public int id() {
    return id;
  }

  public Snapshot view() {
    return registers.snapshot(applied, termAt(applied));
  }

  public boolean waitingForDisk() {
    return pendingPersist != 0;
  }

  private long request() {
    return (boot << 32) ^ (++serial);
  }

  private long last() {
    return snapshot.index() + log.size();
  }

  private long termAt(long index) {
    if (index == snapshot.index()) return snapshot.term();
    if (index < snapshot.index() || index > last()) return -1;
    return log.get(Math.toIntExact(index - snapshot.index() - 1)).term();
  }

  private Entry entry(long index) {
    return log.get(Math.toIntExact(index - snapshot.index() - 1));
  }

  private void resetDeadline() {
    deadline = clock + 250 + electionRandom.nextInt(250);
  }

  private void tick(long now) {
    clock = Math.max(clock, now);
    var pendingReads = reads.values().iterator();
    while (pendingReads.hasNext()) {
      Reading reading = pendingReads.next();
      if (clock >= reading.expires) {
        out.add(new Reply(reading.request, new Result("UNAVAILABLE", null, leader)));
        pendingReads.remove();
      }
    }
    if (role != Role.LEADER && clock >= deadline) elect();
    else if (role == Role.LEADER && clock >= heartbeat) {
      broadcast(0);
      heartbeat = clock + 50;
    }
  }

  private void elect() {
    term++;
    vote = id;
    role = Role.CANDIDATE;
    leader = -1;
    votes.clear();
    votes.add(id);
    reads.clear();
    sent.values().forEach(Map::clear);
    dirty = true;
    resetDeadline();
    for (int p = 0; p < 3; p++)
      if (p != id) {
        long req = request();
        voteRequests.put(p, req);
        out.add(new Send(p, new VoteRequest(term, req, id, last(), termAt(last()))));
      }
  }

  private void stepDown(long newTerm) {
    if (newTerm > term) {
      term = newTerm;
      vote = -1;
      dirty = true;
    }
    role = Role.FOLLOWER;
    leader = -1;
    votes.clear();
    reads
        .values()
        .forEach(r -> out.add(new Reply(r.request, new Result("UNKNOWN_OUTCOME", null, -1))));
    reads.clear();
    clients.values().forEach(r -> out.add(new Reply(r, new Result("UNKNOWN_OUTCOME", null, -1))));
    clients.clear();
    sent.values().forEach(Map::clear);
    snapshotOffsets.clear();
    snapshotRequests.clear();
    incoming = null;
    outgoingSnapshot = null;
  }

  private void receive(int peer, Rpc rpc) {
    if (peer < 0 || peer > 2 || peer == id) return;
    if (rpc.term() > term) stepDown(rpc.term());
    switch (rpc) {
      case VoteRequest r -> vote(peer, r);
      case VoteResponse r -> voted(peer, r);
      case AppendRequest r -> append(peer, r);
      case AppendResponse r -> appended(peer, r);
      case SnapshotRequest r -> install(peer, r);
      case SnapshotResponse r -> installed(peer, r);
    }
  }

  private void vote(int peer, VoteRequest r) {
    boolean grant =
        r.term() == term
            && r.candidate() == peer
            && (vote == -1 || vote == peer)
            && (r.lastTerm() > termAt(last())
                || (r.lastTerm() == termAt(last()) && r.lastIndex() >= last()));
    if (grant) {
      vote = peer;
      dirty = true;
      resetDeadline();
    }
    out.add(new Send(peer, new VoteResponse(term, r.request(), grant)));
  }

  private void voted(int peer, VoteResponse r) {
    if (role != Role.CANDIDATE
        || r.term() != term
        || !r.granted()
        || !Objects.equals(voteRequests.get(peer), r.request())) return;
    votes.add(peer);
    if (votes.size() < 2) return;
    role = Role.LEADER;
    leader = id;
    for (int p = 0; p < 3; p++) {
      next.put(p, last() + 1);
      match.put(p, p == id ? last() : 0L);
    }
    log.add(new Entry(last() + 1, term, null));
    match.put(id, last());
    dirty = true;
    broadcast(0);
    heartbeat = clock + 50;
  }

  private void append(int peer, AppendRequest r) {
    if (r.term() != term || r.leader() != peer) {
      out.add(new Send(peer, new AppendResponse(term, r.request(), false, last(), r.read())));
      return;
    }
    if (role != Role.FOLLOWER) stepDown(term);
    leader = peer;
    resetDeadline();
    if (termAt(r.previousIndex()) != r.previousTerm()) {
      out.add(new Send(peer, new AppendResponse(term, r.request(), false, last(), r.read())));
      return;
    }
    long index = r.previousIndex();
    for (Entry incomingEntry : r.entries()) {
      index++;
      if (incomingEntry.index() != index || incomingEntry.term() > term)
        throw new IllegalArgumentException("MALFORMED_APPEND");
      if (index <= last() && termAt(index) != incomingEntry.term()) {
        if (index <= commit) throw new IllegalStateException("COMMITTED_TRUNCATION");
        log.subList(Math.toIntExact(index - snapshot.index() - 1), log.size()).clear();
        dirty = true;
      }
      if (index > last()) {
        log.add(incomingEntry);
        dirty = true;
      }
    }
    long newCommit = Math.min(r.commit(), index);
    if (newCommit > commit) {
      commit = newCommit;
      dirty = true;
    }
    out.add(new Send(peer, new AppendResponse(term, r.request(), true, index, r.read())));
  }

  private void appended(int peer, AppendResponse r) {
    if (role != Role.LEADER || r.term() != term) return;
    Sent s = sent.get(peer).remove(r.request());
    if (s == null || s.term() != term) return;
    if (r.success()) {
      if (r.match() != s.last() || r.read() != s.read()) return;
      match.put(peer, Math.max(match.get(peer), r.match()));
      next.put(peer, Math.max(next.get(peer), r.match() + 1));
      advance();
      if (r.read() != 0) {
        Reading reading = reads.get(r.read());
        if (reading != null) {
          reading.acks.add(peer);
          completeReads();
        }
      }
      if (next.get(peer) <= last()) replicate(peer, 0);
    } else if (s.previous() >= match.get(peer) && s.last() >= next.get(peer) - 1) {
      next.put(peer, Math.max(match.get(peer) + 1, Math.min(next.get(peer) - 1, s.previous())));
      replicate(peer, s.read());
    }
  }

  private void advance() {
    long candidate = last();
    while (candidate > commit) {
      int count = 1;
      for (int p = 0; p < 3; p++) if (p != id && match.getOrDefault(p, 0L) >= candidate) count++;
      if (count >= 2 && termAt(candidate) == term) {
        commit = candidate;
        dirty = true;
        broadcast(0);
        break;
      }
      candidate--;
    }
  }

  private void broadcast(long read) {
    for (int p = 0; p < 3; p++) if (p != id) replicate(p, read);
  }

  private void replicate(int peer, long read) {
    if (sent.get(peer).size() >= MAX_PENDING) {
      var it = sent.get(peer).keySet().iterator();
      it.next();
      it.remove();
    }
    long n = next.getOrDefault(peer, last() + 1);
    if (n <= snapshot.index()) {
      sendSnapshot(peer);
      return;
    }
    long end = Math.min(last(), n + 31);
    List<Entry> entries =
        n <= end
            ? List.copyOf(
                log.subList(
                    Math.toIntExact(n - snapshot.index() - 1),
                    Math.toIntExact(end - snapshot.index())))
            : List.of();
    long req = request();
    sent.get(peer).put(req, new Sent(term, n - 1, end, read));
    out.add(
        new Send(
            peer, new AppendRequest(term, req, id, n - 1, termAt(n - 1), entries, commit, read)));
  }

  private void mutate(Mutate m) {
    if (role != Role.LEADER) {
      out.add(new Reply(m.request(), new Result("NOT_LEADER", null, leader)));
      return;
    }
    if (clients.size() >= MAX_PENDING || log.size() > 4096) {
      out.add(new Reply(m.request(), new Result("RESOURCE_EXHAUSTED", null, id)));
      return;
    }
    log.add(new Entry(last() + 1, term, m.command()));
    clients.put(last(), m.request());
    match.put(id, last());
    dirty = true;
    broadcast(0);
  }

  private void read(Read r) {
    if (role != Role.LEADER) {
      out.add(new Reply(r.request(), new Result("NOT_LEADER", null, leader)));
      return;
    }
    if (commit == 0 || termAt(commit) != term) {
      out.add(new Reply(r.request(), new Result("UNAVAILABLE", null, id)));
      return;
    }
    if (reads.size() >= MAX_PENDING) {
      out.add(new Reply(r.request(), new Result("RESOURCE_EXHAUSTED", null, id)));
      return;
    }
    long correlation = request();
    reads.put(correlation, new Reading(r.request(), commit, r.key(), id, clock + 1000));
    broadcast(correlation);
  }

  private void completeReads() {
    var it = reads.entrySet().iterator();
    while (it.hasNext()) {
      Reading r = it.next().getValue();
      if (r.acks.size() >= 2 && applied >= r.safe) {
        out.add(new Reply(r.request, registers.get(r.key)));
        it.remove();
      }
    }
  }

  private void applyRecovered() {
    while (applied < commit) {
      Entry e = entry(++applied);
      if (e.command() != null) registers.apply(e.command());
    }
  }

  private void apply() {
    while (applied < commit) {
      Entry e = entry(++applied);
      Result result =
          e.command() == null ? new Result("MARKER", null, -1) : registers.apply(e.command());
      out.add(new Applied(e.index(), e.term(), e.command(), result));
      Long client = clients.remove(e.index());
      if (client != null) out.add(new Reply(client, result));
    }
    completeReads();
  }

  private void compact() {
    if (applied <= snapshot.index()) return;
    snapshot = registers.snapshot(applied, termAt(applied));
    log.subList(0, Math.toIntExact(applied - durableSnapshotIndex())).clear();
    dirty = true;
    outgoingSnapshot = null;
    snapshotOffsets.clear();
    snapshotRequests.clear();
  }

  private long durableSnapshotIndex() {
    return log.isEmpty() ? snapshot.index() : log.getFirst().index() - 1;
  }

  private void sendSnapshot(int peer) {
    if (outgoingSnapshot == null) outgoingSnapshot = Codec.snapshot(snapshot);
    int offset = snapshotOffsets.getOrDefault(peer, 0);
    if (offset >= outgoingSnapshot.length) offset = 0;
    int end = Math.min(outgoingSnapshot.length, offset + 16384);
    SnapshotRequest message =
        new SnapshotRequest(
            term,
            request(),
            id,
            snapshot.index(),
            snapshot.term(),
            offset,
            outgoingSnapshot.length,
            Arrays.copyOfRange(outgoingSnapshot, offset, end));
    snapshotRequests.put(peer, message);
    out.add(new Send(peer, message));
  }

  private void install(int peer, SnapshotRequest r) {
    if (r.term() != term || r.leader() != peer) return;
    if (role != Role.FOLLOWER) stepDown(term);
    leader = peer;
    resetDeadline();
    if (r.total() < 1
        || r.total() > MAX_SNAPSHOT
        || r.offset() < 0
        || r.offset() + r.chunk().length > r.total()) return;
    if (r.index() <= commit) {
      out.add(new Send(peer, new SnapshotResponse(term, r.request(), r.index(), r.total(), true)));
      return;
    }
    if (r.offset() == 0) {
      incoming = new ByteArrayOutputStream();
      incomingIndex = r.index();
      incomingTerm = r.snapshotTerm();
    }
    if (incoming == null
        || incomingIndex != r.index()
        || incomingTerm != r.snapshotTerm()
        || incoming.size() != r.offset()) {out.add(new Send(peer,new SnapshotResponse(term,r.request(),r.index(),0,false)));return;}
    incoming.writeBytes(r.chunk());
    if (incoming.size() < r.total()) {
      out.add(
          new Send(
              peer, new SnapshotResponse(term, r.request(), r.index(), incoming.size(), false)));
      return;
    }
    try {
      Snapshot installed = Codec.snapshot(incoming.toByteArray());
      if (installed.index() != r.index() || installed.term() != r.snapshotTerm()) return;
      List<Entry> suffix =
          termAt(r.index()) == r.snapshotTerm()
              ? log.stream().filter(e -> e.index() > r.index()).toList()
              : List.of();
      snapshot = installed;
      log.clear();
      log.addAll(suffix);
      commit = installed.index();
      dirty = true;
      incoming = null;
      out.add(new Send(peer, new SnapshotResponse(term, r.request(), r.index(), r.total(), true)));
    } catch (IOException | IllegalArgumentException e) {
      incoming = null;
    }
  }

  private void installed(int peer, SnapshotResponse r) {
    SnapshotRequest request = snapshotRequests.get(peer);
    if (role != Role.LEADER
        || r.term() != term
        || r.index() != snapshot.index()
        || request == null
        || request.request() != r.request()) return;
    if (r.done()) {
      if(r.nextOffset()!=request.total())return;
      match.put(peer, Math.max(match.get(peer), r.index()));
      next.put(peer, Math.max(next.get(peer), r.index() + 1));
      snapshotOffsets.remove(peer);
      replicate(peer, 0);
    } else {
      if(r.nextOffset()==0&&request.offset()>0){snapshotOffsets.put(peer,0);sendSnapshot(peer);return;}
      if(r.nextOffset()!=request.offset()+request.chunk().length||r.nextOffset()>=request.total())return;
      snapshotOffsets.put(peer, r.nextOffset());
      sendSnapshot(peer);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Model.*;

import java.util.*;

/** Deterministic committed state machine. All calls belong to the node owner thread. */
public final class Registers {
  private final NavigableMap<Key, byte[]> data = new TreeMap<>();
  private final Map<String, Session> sessions = new HashMap<>();
  private int retained;

  public Registers(Snapshot snapshot) {
    data.putAll(snapshot.data());
    sessions.putAll(snapshot.sessions());
    data.forEach((k, v) -> retained += k.bytes().length + v.length);
  }

  public Result apply(Command c) {
    Session s = sessions.get(c.client());
    if (s != null && c.sequence() == s.sequence())
      return Arrays.equals(s.digest(), c.digest())
          ? s.result()
          : new Result("IDENTITY_CONFLICT", null, -1);
    if (s != null && c.sequence() < s.sequence()) return new Result("STALE_SEQUENCE", null, -1);
    if (c.sequence() != (s == null ? 1 : s.sequence() + 1))
      return new Result("SEQUENCE_GAP", null, -1);
    if (s == null && sessions.size() >= MAX_CLIENTS)
      return new Result("RESOURCE_EXHAUSTED", null, -1);
    byte[] old = data.get(c.key());
    boolean matches = c.kind() != Kind.CAS || Arrays.equals(old, c.expected());
    byte[] next = c.kind() == Kind.DELETE ? null : c.value();
    int delta =
        (next == null ? 0 : next.length + c.key().bytes().length)
            - (old == null ? 0 : old.length + c.key().bytes().length);
    Result r;
    if (!matches) r = new Result("CAS_MISMATCH", old, -1);
    else if (retained + delta > MAX_DATA || next != null && old == null && data.size() >= MAX_KEYS)
      return new Result("RESOURCE_EXHAUSTED", null, -1);
    else {
      if (next == null) data.remove(c.key());
      else data.put(c.key(), next.clone());
      retained += delta;
      r = new Result("OK", c.kind() == Kind.CAS ? old : next, -1);
    }
    sessions.put(c.client(), new Session(c.sequence(), c.digest(), r));
    return r;
  }

  public Result get(Key key) {
    return new Result("OK", data.get(key), -1);
  }

  public Snapshot snapshot(long index, long term) {
    return new Snapshot(index, term, CLUSTER, data, sessions);
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Model.*;
import static io.github.cheshmakzanoon.portfolio.majority.Raft.*;

import java.util.*;

/** Virtual time, network and stable disks are separate. No sleep or real I/O. */
public final class Simulator {
  private record Scheduled(long time, long order, int node, long boot, Event event, Durable write)
      implements Comparable<Scheduled> {
    public int compareTo(Scheduled o) {
      int t = Long.compare(time, o.time);
      return t == 0 ? Long.compare(order, o.order) : t;
    }
  }

  private final Random random;
  private final PriorityQueue<Scheduled> queue = new PriorityQueue<>();
  private final Raft[] nodes = new Raft[3];
  private final Durable[] disks = {Durable.empty(), Durable.empty(), Durable.empty()};
  private final long[] boots = {1, 1, 1}, highestApplied = new long[3];
  private final boolean[] paused = new boolean[3];
  private final boolean[][] blocked = new boolean[3][3];
  private final Map<Long, Integer> leaders = new HashMap<>();
  private final Map<Long, byte[]> committed = new HashMap<>(), results = new HashMap<>();
  private final ArrayDeque<String> trace = new ArrayDeque<>();
  public final Map<Long, Result> replies = new HashMap<>();
  private long now, order, request;
  private double loss = .08;

  public Simulator(long seed) {
    random = new Random(seed);
    for (int i = 0; i < 3; i++) nodes[i] = new Raft(i, boots[i], disks[i]);
  }

  public void reliable() {
    loss = 0;
    for (boolean[] row : blocked) Arrays.fill(row, false);
    Arrays.fill(paused, false);
    for (int i = 0; i < 3; i++) if (nodes[i] == null) restart(i);
  }

  public void partition(int node, boolean isolate) {
    for (int p = 0; p < 3; p++) blocked[node][p] = blocked[p][node] = isolate;
    record("partition " + node + " " + isolate);
  }

  public void pause(int node, boolean pause) {
    paused[node] = pause;
    record("pause " + node + " " + pause);
  }

  public void crash(int node) {
    nodes[node] = null;
    record("crash " + node);
  }

  public void restart(int node) {
    if (nodes[node] == null) {
      nodes[node] = new Raft(node, ++boots[node], disks[node]);
      record("restart " + node);
    }
  }

  public long mutate(int node, Command command) {
    long r = ++request;
    deliver(node, new Mutate(r, command));
    return r;
  }

  public long read(int node, Key key) {
    long r = ++request;
    deliver(node, new Read(r, key));
    return r;
  }

  public Raft node(int i) {
    return nodes[i];
  }

  public long now() {
    return now;
  }

  public int leader() {
    for (int i = 0; i < 3; i++) if (nodes[i] != null && nodes[i].role() == Role.LEADER) return i;
    return -1;
  }

  public void run(long duration) {
    long stop = now + duration;
    while (now < stop) {
      now += 5;
      for (int i = 0; i < 3; i++) if (nodes[i] != null && !paused[i]) deliver(i, new Tick(now));
      while (!queue.isEmpty() && queue.peek().time <= now) {
        Scheduled s = queue.remove();
        if (nodes[s.node] == null || s.boot != boots[s.node]) continue;
        if (paused[s.node]) {
          queue.add(new Scheduled(now + 10, ++order, s.node, s.boot, s.event, s.write));
          continue;
        }
        if (s.write != null) disks[s.node] = s.write;
        else deliver(s.node, s.event);
      }
      invariants();
    }
  }

  public void faultSchedule(int actions) {
    for (int n = 0; n < actions; n++) {
      int node = random.nextInt(3);
      switch (random.nextInt(12)) {
        case 0 -> partition(node, true);
        case 1 -> partition(node, false);
        case 2 -> crash(node);
        case 3 -> restart(node);
        case 4 -> pause(node, true);
        case 5 -> pause(node, false);
        case 6 -> {
          if (nodes[node] != null) deliver(node, new TakeSnapshot());
        }
        case 7, 8 -> {
          if (nodes[node] != null)
            mutate(
                node,
                new Command(
                    "c" + node,
                    1,
                    Kind.PUT,
                    new Key(new byte[] {(byte) node}),
                    new byte[] {(byte) n},
                    null));
        }
        case 9 -> {
          if (nodes[node] != null) read(node, new Key(new byte[] {0}));
        }
        default -> {}
      }
      run(10 + random.nextInt(30));
    }
    reliable();
    run(5000);
    if (leader() < 0) throw new AssertionError("NO_PROGRESS_AFTER_HEAL " + trace());
  }

  public String trace() {
    return String.join("\n", trace);
  }

  private void record(String line) {
    if (trace.size() == 300) trace.removeFirst();
    trace.add(now + " " + line);
  }

  private void deliver(int node, Event event) {
    if (nodes[node] == null) return;
    record(node + " " + event.getClass().getSimpleName());
    for (Effect effect : nodes[node].accept(event)) {
      switch (effect) {
        case Persist p -> {
          long delay = 1 + random.nextInt(12);
          queue.add(new Scheduled(now + delay, ++order, node, boots[node], null, p.durable()));
          queue.add(
              new Scheduled(
                  now + delay + 1, ++order, node, boots[node], new Persisted(p.token()), null));
        }
        case Send s -> {
          if (blocked[node][s.peer()] || random.nextDouble() < loss) continue;
          int duplicates = random.nextInt(10) == 0 ? 2 : 1;
          for (int d = 0; d < duplicates; d++)
            queue.add(
                new Scheduled(
                    now + 1 + random.nextInt(40),
                    ++order,
                    s.peer(),
                    boots[s.peer()],
                    new Receive(node, s.rpc()),
                    null));
        }
        case Reply r -> replies.put(r.request(), r.result());
        case Applied a -> {
          byte[] identity =
              Codec.encode(
                  out -> {
                    out.writeLong(a.term());
                    Codec.writeCommand(out, a.command());
                  });
          agree(committed, a.index(), identity, "COMMITTED_PREFIX");
          agree(
              results,
              a.index(),
              Codec.encode(out -> Codec.result(out, a.result())),
              "APPLICATION_RESULT");
        }
      }
    }
    invariants();
  }

  private static void agree(Map<Long, byte[]> seen, long index, byte[] value, String invariant) {
    byte[] previous = seen.putIfAbsent(index, value);
    if (previous != null && !Arrays.equals(previous, value))
      throw new AssertionError(invariant + " index=" + index);
  }

  private void invariants() {
    for (int i = 0; i < 3; i++) {
      Raft node = nodes[i];
      if (node == null) continue;
      if (node.role() == Role.LEADER) {
        Integer previous = leaders.putIfAbsent(node.term(), i);
        if (previous != null && previous != i) throw new AssertionError("ELECTION_SAFETY");
      }
      if (node.applied() > node.commit() || node.applied() < highestApplied[i])
        throw new AssertionError("MONOTONIC_APPLICATION");
      highestApplied[i] = node.applied();
      for (Entry e : node.durable().log())
        if (e.index() <= node.commit())
          agree(
              committed,
              e.index(),
              Codec.encode(
                  out -> {
                    out.writeLong(e.term());
                    Codec.writeCommand(out, e.command());
                  }),
              "COMMITTED_PREFIX");
    }
  }
}

package io.github.cheshmakzanoon.portfolio.majority;

import static io.github.cheshmakzanoon.portfolio.majority.Model.*;

import java.io.*;
import java.nio.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32C;

/** Append-only transaction WAL. A suffix replacement is one checksummed transaction. */
public final class Journal implements AutoCloseable {
  public enum Boundary {
    SNAPSHOT_FLUSH,
    SNAPSHOT_RENAME,
    GENERATION_FLUSH,
    MANIFEST_FLUSH,
    MANIFEST_RENAME,
    DIRECTORY_FLUSH,
    WAL_WRITE,
    WAL_FLUSH
  }

  @FunctionalInterface
  public interface Fault {
    void at(Boundary boundary) throws IOException;
  }

  private static final int MAGIC = 0x514b5631, HEADER = 33, MAX_RECORD = 64 * 1024 * 1024;
  private final Path directory;
  private final FileChannel lockChannel;
  private final FileLock lock;
  private final Fault fault;
  private FileChannel wal;
  private long generation;
  private Durable state;

  public Journal(Path directory) throws IOException {
    this(directory, b -> {});
  }

  public Journal(Path directory, Fault fault) throws IOException {
    this.directory = directory;
    this.fault = fault;
    Files.createDirectories(directory);
    lockChannel =
        FileChannel.open(
            directory.resolve("LOCK"), StandardOpenOption.CREATE, StandardOpenOption.WRITE);
    try {
      lock = lockChannel.tryLock();
    } catch (OverlappingFileLockException e) {
      lockChannel.close();
      throw new IOException("DIRECTORY_LOCKED", e);
    }
    if (lock == null) {
      lockChannel.close();
      throw new IOException("DIRECTORY_LOCKED");
    }
    try {
      Path manifest = directory.resolve("MANIFEST");
      if (!Files.exists(manifest)) {
        if (Files.exists(directory.resolve("wal-0")))
          throw new IOException("UNPUBLISHED_INITIAL_STATE: inspect directory before recovery");
        generation = 0;
        state = Durable.empty();
        publish(state);
      } else {
        String[] fields = Files.readString(manifest).trim().split(" ");
        if (fields.length != 3 || !fields[0].equals("QKV1"))
          throw new IOException("INCOMPATIBLE_MANIFEST: expected QKV1");
        generation = Long.parseLong(fields[1]);
        Path snapshot = directory.resolve("snapshot-" + fields[2]);
        byte[] body = checkedFile(snapshot);
        Snapshot s = Codec.snapshot(body);
        state = Durable.empty();
        wal =
            FileChannel.open(
                directory.resolve("wal-" + generation),
                StandardOpenOption.READ,
                StandardOpenOption.WRITE);
        recover();
        if (state.snapshot().index() != s.index()
            || state.snapshot().term() != s.term()
            || !Arrays.equals(Codec.snapshot(state.snapshot()), body))
          throw new IOException("MANIFEST_SNAPSHOT_MISMATCH");
      }
    } catch (IOException | RuntimeException e) {
      if (wal != null) wal.close();
      lock.release();
      lockChannel.close();
      throw e;
    }
  }

  public Durable recovered() {
    return state;
  }

  public synchronized void persist(Durable next) throws IOException {
    if (next.term() < state.term() || next.commit() < state.commit())
      throw new IOException("DURABILITY_REGRESSION");
    if (next.snapshot().index() != state.snapshot().index() || wal.size() > 8L*1024*1024) {
      publish(next);
      return;
    }
    byte[] delta = delta(state, next);
    ByteBuffer record = record((byte) 2, next, delta);
    wal.position(wal.size());
    write(wal, record);
    fault.at(Boundary.WAL_WRITE);
    wal.force(true);
    fault.at(Boundary.WAL_FLUSH);
    state = next;
  }

  private void publish(Durable next) throws IOException {
    long previousSnapshot=state==null?0:state.snapshot().index();
    long nextGeneration = wal == null ? generation : generation + 1;
    String snapshotName = "snapshot-" + next.snapshot().index();
    Path temp = directory.resolve(snapshotName + ".tmp"),
        published = directory.resolve(snapshotName);
    byte[] snapshot = Codec.snapshot(next.snapshot());
    writeChecked(temp, snapshot);
    if (!Arrays.equals(snapshot, checkedFile(temp))) throw new IOException("SNAPSHOT_VERIFY");
    fault.at(Boundary.SNAPSHOT_FLUSH);
    Files.move(
        temp, published, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
    fault.at(Boundary.SNAPSHOT_RENAME);
    Path walTemp = directory.resolve("wal-" + nextGeneration + ".tmp");
    try (FileChannel fresh =
        FileChannel.open(
            walTemp,
            StandardOpenOption.CREATE,
            StandardOpenOption.TRUNCATE_EXISTING,
            StandardOpenOption.WRITE)) {
      write(fresh, record((byte) 1, next, Codec.durable(next)));
      fresh.force(true);
    }
    fault.at(Boundary.GENERATION_FLUSH);
    Files.move(
        walTemp,
        directory.resolve("wal-" + nextGeneration),
        StandardCopyOption.ATOMIC_MOVE,
        StandardCopyOption.REPLACE_EXISTING);
    syncDirectory();
    Path manifestTemp = directory.resolve("MANIFEST.tmp");
    try (FileChannel f =
        FileChannel.open(
            manifestTemp,
            StandardOpenOption.CREATE,
            StandardOpenOption.TRUNCATE_EXISTING,
            StandardOpenOption.WRITE)) {
      write(
          f,
          ByteBuffer.wrap(
              ("QKV1 " + nextGeneration + " " + next.snapshot().index() + "\n")
                  .getBytes(java.nio.charset.StandardCharsets.US_ASCII)));
      f.force(true);
    }
    fault.at(Boundary.MANIFEST_FLUSH);
    Files.move(
        manifestTemp,
        directory.resolve("MANIFEST"),
        StandardCopyOption.ATOMIC_MOVE,
        StandardCopyOption.REPLACE_EXISTING);
    fault.at(Boundary.MANIFEST_RENAME);
    syncDirectory();
    fault.at(Boundary.DIRECTORY_FLUSH);
    if (wal != null) wal.close();
    generation = nextGeneration;
    wal =
        FileChannel.open(
            directory.resolve("wal-" + generation),
            StandardOpenOption.READ,
            StandardOpenOption.WRITE);
    state = next;
    // Keep the immediately previous generation and snapshots. Never retire before manifest
    // durability.
    try (var paths = Files.list(directory)) {
      for (Path p : paths.toList()) {
        String n = p.getFileName().toString();
        if (n.matches("wal-[0-9]+") && Long.parseLong(n.substring(4)) < generation - 1)
          Files.delete(p);
        if(n.matches("snapshot-[0-9]+")&&Long.parseLong(n.substring(9))<previousSnapshot)Files.delete(p);
      }
    }
  }

  private void recover() throws IOException {
    long position = 0, size = wal.size();
    boolean first = true;
    while (position < size) {
      long remaining = size - position;
      if (remaining < HEADER) {
        wal.truncate(position);
        wal.force(true);
        break;
      }
      ByteBuffer header = ByteBuffer.allocate(HEADER);
      read(wal, header, position);
      header.flip();
      if (header.getInt() != MAGIC || header.getInt() != 1)
        throw new IOException("INCOMPATIBLE_WAL at " + position);
      int length = header.getInt();
      byte type = header.get();
      long index = header.getLong(), term = header.getLong();
      int payload = header.getInt();
      if (length < HEADER + 4 || length > MAX_RECORD || payload != length - HEADER - 4)
        throw new IOException("WAL_LENGTH_CORRUPTION at " + position);
      if (remaining < length) {
        wal.truncate(position);
        wal.force(true);
        break;
      }
      ByteBuffer record = ByteBuffer.allocate(length);
      read(wal, record, position);
      byte[] bytes = record.array();
      int expected = ByteBuffer.wrap(bytes, length - 4, 4).getInt();
      if (crc(Arrays.copyOf(bytes, length - 4)) != expected)
        throw new IOException("WAL_CHECKSUM_CORRUPTION at " + position);
      byte[] body = Arrays.copyOfRange(bytes, HEADER, length - 4);
      if (type == 1 && first) state = Codec.durable(body);
      else if (type == 2 && !first) state = applyDelta(state, body);
      else throw new IOException("WAL_RECORD_ORDER");
      if (last(state) != index || state.term() != term)
        throw new IOException("WAL_COORDINATE_MISMATCH");
      first = false;
      position += length;
    }
    if (first) throw new IOException("MISSING_INITIAL_WAL_RECORD");
  }

  private static byte[] delta(Durable old, Durable next) {
    return encodeDelta(old, next);
  }

  private static byte[] encodeDelta(Durable old, Durable next) {
    int prefix = 0;
    while (prefix < old.log().size() && prefix < next.log().size()) {
      Entry a = old.log().get(prefix), b = next.log().get(prefix);
      if (a.index() != b.index() || a.term() != b.term()) break;
      prefix++;
    }
    int shared = prefix;
    return Codec.encode(
        out -> {
          out.writeLong(next.term());
          out.writeInt(next.vote());
          out.writeLong(next.commit());
          out.writeInt(shared);
          out.writeInt(next.log().size() - shared);
          for (int i = shared; i < next.log().size(); i++) Codec.entry(out, next.log().get(i));
        });
  }

  private static Durable applyDelta(Durable old, byte[] bytes) throws IOException {
    try (var in = new DataInputStream(new ByteArrayInputStream(bytes))) {
      long term = in.readLong();
      int vote = in.readInt();
      long commit = in.readLong();
      int shared = Codec.count(in, old.log().size());
      int additions = Codec.count(in, 4096);
      var log = new ArrayList<>(old.log().subList(0, shared));
      for (int i = 0; i < additions; i++) log.add(Codec.entry(in));
      if (in.available() != 0) throw new IOException("WAL_TRAILING");
      if (term < old.term() || commit < old.commit()) throw new IOException("WAL_REGRESSION");
      return new Durable(term, vote, commit, old.snapshot(), log);
    }
  }

  private static long last(Durable d) {
    return d.snapshot().index() + d.log().size();
  }

  private static ByteBuffer record(byte type, Durable d, byte[] payload) {
    int length = HEADER + payload.length + 4;
    if(length>MAX_RECORD)throw new IllegalStateException("WAL_RESOURCE_EXHAUSTED");
    ByteBuffer b = ByteBuffer.allocate(length);
    b.putInt(MAGIC)
        .putInt(1)
        .putInt(length)
        .put(type)
        .putLong(last(d))
        .putLong(d.term())
        .putInt(payload.length)
        .put(payload);
    b.putInt(crc(Arrays.copyOf(b.array(), length - 4))).flip();
    return b;
  }

  private static int crc(byte[] bytes) {
    var crc = new CRC32C();
    crc.update(bytes);
    return (int) crc.getValue();
  }

  private static void writeChecked(Path path, byte[] body) throws IOException {
    try (FileChannel f =
        FileChannel.open(
            path,
            StandardOpenOption.CREATE,
            StandardOpenOption.TRUNCATE_EXISTING,
            StandardOpenOption.WRITE)) {
      ByteBuffer b = ByteBuffer.allocate(body.length + 4).put(body).putInt(crc(body));
      b.flip();
      write(f, b);
      f.force(true);
    }
  }

  private static byte[] checkedFile(Path path) throws IOException {
    long size = Files.size(path);
    if (size < 4 || size > MAX_RECORD) throw new IOException("SNAPSHOT_LENGTH");
    byte[] all = Files.readAllBytes(path), body = Arrays.copyOf(all, all.length - 4);
    if (crc(body) != ByteBuffer.wrap(all, all.length - 4, 4).getInt())
      throw new IOException("SNAPSHOT_CHECKSUM");
    return body;
  }

  private void syncDirectory() throws IOException {
    try (FileChannel d = FileChannel.open(directory, StandardOpenOption.READ)) {
      d.force(true);
    }
  }

  private static void write(FileChannel f, ByteBuffer b) throws IOException {
    while (b.hasRemaining()) f.write(b);
  }

  private static void read(FileChannel f, ByteBuffer b, long offset) throws IOException {
    while (b.hasRemaining()) {
      int n = f.read(b, offset + b.position());
      if (n < 0) throw new EOFException();
    }
  }

  @Override
  public void close() throws IOException {
    if (wal != null) wal.close();
    lock.release();
    lockChannel.close();
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import java.time.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.oauth2.core.*;
import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.security.web.SecurityFilterChain;

@SpringBootApplication
public class DecisionApplication {
  public static void main(String[] args) {
    SpringApplication.run(DecisionApplication.class, args);
  }

  @Bean
  HikariDataSource runtimeDataSource(Environment e) {
    HikariConfig c = new HikariConfig();
    c.setJdbcUrl(e.getRequiredProperty("gatehouse.db.url"));
    c.setUsername(e.getProperty("gatehouse.db.user", "gatehouse_runtime"));
    c.setPassword(e.getRequiredProperty("gatehouse.db.password"));
    c.setMaximumPoolSize(8);
    c.addDataSourceProperty("socketTimeout", "5");
    c.setMinimumIdle(1);
    c.setConnectionTimeout(3000);
    c.setValidationTimeout(2000);
    c.setConnectionInitSql("SET statement_timeout='5000'");
    HikariDataSource ds = new HikariDataSource(c);
    try (var connection = ds.getConnection();
        var s = connection.createStatement();
        var r =
            s.executeQuery(
                "SELECT rolsuper,rolbypassrls,current_user=(SELECT tableowner FROM pg_tables WHERE schemaname='public' AND tablename='membership') FROM pg_roles WHERE rolname=current_user")) {
      if (!r.next() || r.getBoolean(1) || r.getBoolean(2) || r.getBoolean(3))
        throw new IllegalStateException("runtime role must not own tables or bypass RLS");
    } catch (java.sql.SQLException ex) {
      ds.close();
      throw new IllegalStateException("runtime role validation failed", ex);
    }
    return ds;
  }

  @Bean
  PolicyStore store(HikariDataSource ds) {
    return new PolicyStore(ds);
  }

  @Bean
  JwtDecoder jwtDecoder(Environment e) {
    return trustedDecoder(
        e.getRequiredProperty("gatehouse.oidc.issuer"),
        e.getRequiredProperty("gatehouse.oidc.jwks"),
        e.getProperty("gatehouse.oidc.audience", "gatehouse"));
  }

  public static JwtDecoder trustedDecoder(String issuer, String jwks, String audience) {
    // The configured URI is fixed at startup. No unverified claim can trigger issuer discovery.
    NimbusJwtDecoder decoder =
        NimbusJwtDecoder.withJwkSetUri(jwks).jwsAlgorithm(SignatureAlgorithm.RS256).build();
    OAuth2TokenValidator<Jwt> required =
        jwt -> {
          boolean ok =
              jwt.getExpiresAt() != null
                  && jwt.getIssuedAt() != null
                  && !jwt.getIssuedAt().isAfter(Instant.now())
                  && jwt.getSubject() != null
                  && !jwt.getSubject().isBlank()
                  && jwt.getAudience() != null
                  && jwt.getAudience().contains(audience);
          return ok
              ? OAuth2TokenValidatorResult.success()
              : OAuth2TokenValidatorResult.failure(
                  new OAuth2Error("invalid_token", "required token claims invalid", null));
        };
    decoder.setJwtValidator(
        new DelegatingOAuth2TokenValidator<>(
            new JwtTimestampValidator(Duration.ZERO), new JwtIssuerValidator(issuer), required));
    return decoder;
  }

  @Bean
  SecurityFilterChain security(HttpSecurity http) throws Exception {
    return http.csrf(c -> c.disable())
        .authorizeHttpRequests(
            a -> a.requestMatchers("/actuator/health").permitAll().anyRequest().authenticated())
        .oauth2ResourceServer(o -> o.jwt(j -> {}))
        .build();
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import com.github.benmanes.caffeine.cache.*;
import java.util.*;
import org.springframework.http.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import tools.jackson.databind.ObjectMapper;

@RestController
@RequestMapping("/v1/tenants/{tenant}")
public class DecisionController {
  public record ResourceRef(String type, String id) {}

  public record Request(String action, ResourceRef resource, Map<String, Object> context) {}

  public record Response(
      String decision,
      String reason,
      long tenantEpoch,
      long policyVersion,
      long resourceVersion,
      List<String> matchedRuleIds,
      UUID decisionId) {}

  public record Example(
      Set<String> roles,
      String action,
      String resourceType,
      Map<String, Object> fields,
      boolean allowed,
      String reason) {}

  public record Draft(PolicyEngine.Definition policy, List<Example> examples) {}

  public record MembershipUpdate(
      Set<String> roles,
      String department,
      Long clearance,
      Boolean suspended,
      boolean administrative,
      boolean active) {}

  public record Simulation(PolicyEngine.Definition policy, Example example) {}

  private record Key(String tenant, long version, String digest) {}

  private final RequestBounds bounds;
  private final PolicyStore store;
  private final ObjectMapper mapper;
  private final Cache<Key, PolicyEngine.Compiled> cache =
      Caffeine.newBuilder().maximumSize(500).recordStats().build();

  public DecisionController(PolicyStore store, ObjectMapper mapper, RequestBounds bounds) {
    this.bounds = bounds;
    this.store = store;
    this.mapper = mapper;
  }

  private PolicyStore.Principal principal(Jwt jwt) {
    return new PolicyStore.Principal(jwt.getIssuer().toString(), jwt.getSubject());
  }

  @PostMapping("/decisions")
  public Response decide(
      @PathVariable String tenant, @AuthenticationPrincipal Jwt jwt, @RequestBody Request request) {
    validate(request);
    PolicyStore.Outcome o =
        store.decide(
            tenant,
            principal(jwt),
            request.action(),
            request.resource().id(),
            s -> {
              if (s.membership() == null || !s.membership().active())
                return denied("NO_MEMBERSHIP");
              if (s.resource() == null || !s.resource().type().equals(request.resource().type()))
                return denied("RESOURCE_NOT_FOUND");
              if (s.policy() == null) return denied("NO_ACTIVE_POLICY");
              Map<String, Object> fields = new HashMap<>();
              put(fields, "subject.department", s.membership().department());
              put(fields, "subject.clearance", s.membership().clearance());
              put(fields, "subject.suspended", s.membership().suspended());
              put(fields, "resource.department", s.resource().department());
              put(fields, "resource.classification", s.resource().classification());
              put(fields, "resource.type", s.resource().type());
              if (s.resource().classification() != null)
                put(
                    fields,
                    "resource.sensitivity",
                    s.resource().classification() <= 0
                        ? PolicyLanguage.Label.PUBLIC
                        : s.resource().classification() == 1
                            ? PolicyLanguage.Label.INTERNAL
                            : PolicyLanguage.Label.CONFIDENTIAL);
              put(fields, "resource.id", s.resource().id());
              context(request.context()).forEach(fields::put);
              return PolicyEngine.decide(
                  compiled(tenant, s.policy()),
                  s.membership().roles(),
                  request.action(),
                  request.resource().type(),
                  fields);
            });
    return new Response(
        o.decision().allowed() ? "ALLOW" : "DENY",
        o.decision().reason(),
        o.snapshot().epoch(),
        o.snapshot().policy() == null ? 0 : o.snapshot().policy().version(),
        o.snapshot().resource() == null ? 0 : o.snapshot().resource().version(),
        o.decision().matchedRuleIds(),
        o.id());
  }

  private static PolicyEngine.Decision denied(String reason) {
    return new PolicyEngine.Decision(false, reason, List.of());
  }

  private static void put(Map<String, Object> fields, String k, Object v) {
    if (v != null) fields.put(k, v);
  }

  private static Map<String, Object> context(Map<String, Object> input) {
    Map<String, Object> out = new HashMap<>();
    if (input == null) return out;
    if (input.size() > 2) throw new IllegalArgumentException("context limits");
    input.forEach(
        (k, v) -> {
          if (k.equals("purpose") && v instanceof String s && s.length() <= 256)
            out.put("context.purpose", s);
          else if (k.equals("hour") && (v instanceof Integer || v instanceof Long))
            out.put("context.hour", ((Number) v).longValue());
          else throw new IllegalArgumentException("unapproved context field/type");
        });
    return out;
  }

  private static void validate(Request r) {
    if (r == null
        || r.action() == null
        || !r.action().matches("[A-Za-z0-9:_-]{1,128}")
        || r.resource() == null
        || r.resource().id() == null
        || !r.resource().id().matches("[A-Za-z0-9:_-]{1,128}")
        || r.resource().type() == null
        || !r.resource().type().matches("[A-Za-z0-9:_-]{1,128}"))
      throw new IllegalArgumentException("invalid decision request");
    context(r.context());
  }

  private PolicyEngine.Compiled compiled(String tenant, PolicyStore.Revision revision) {
    return cache.get(
        new Key(tenant, revision.version(), revision.digest()),
        k -> {
          PolicyEngine.Compiled p =
              PolicyEngine.compile(
                  mapper.readValue(revision.content(), PolicyEngine.Definition.class));
          if (!p.digest().equals(revision.digest()))
            throw new IllegalStateException("immutable content digest mismatch");
          return p;
        });
  }

  @PostMapping("/policy-versions")
  public Map<String, Long> draft(
      @PathVariable String tenant, @AuthenticationPrincipal Jwt jwt, @RequestBody Draft request) {
    PolicyEngine.Compiled policy = PolicyEngine.compile(request.policy());
    if (request.examples() == null
        || request.examples().isEmpty()
        || request.examples().size() > 100)
      throw new IllegalArgumentException("1..100 regression examples required");
    for (Example e : request.examples()) {
      PolicyEngine.Decision d =
          PolicyEngine.decide(
              policy, e.roles(), e.action(), e.resourceType(), normalize(e.fields()));
      if (d.allowed() != e.allowed() || !d.reason().equals(e.reason()))
        throw new IllegalArgumentException("policy regression example failed");
    }
    String content = mapper.writeValueAsString(request.policy());
    if (content.getBytes(java.nio.charset.StandardCharsets.UTF_8).length > 262144)
      throw new IllegalArgumentException("policy size limit");
    return Map.of("version", store.draft(tenant, principal(jwt), content, policy));
  }

  @PostMapping("/policy-versions/{version}/publish")
  public Map<String, Long> publish(
      @PathVariable String tenant,
      @PathVariable long version,
      @RequestHeader("If-Match") String prior,
      @AuthenticationPrincipal Jwt jwt) {
    long expected;
    try {
      expected = Long.parseLong(prior.replace("\"", ""));
    } catch (NumberFormatException e) {
      throw new IllegalArgumentException("If-Match must quote active version; use 0 for initial");
    }
    return Map.of(
        "tenantEpoch",
        store.publish(tenant, principal(jwt), version, expected),
        "policyVersion",
        version);
  }

  @PostMapping("/policy-versions/{version}/rollback")
  public PolicyStore.Published rollback(
      @PathVariable String tenant,
      @PathVariable long version,
      @RequestHeader("If-Match") String prior,
      @AuthenticationPrincipal Jwt jwt) {
    PolicyStore.Revision old = store.readForAdmin(tenant, principal(jwt), version);
    compiled(tenant, old);
    long expected;
    try {
      expected = Long.parseLong(prior.replace("\"", ""));
    } catch (NumberFormatException e) {
      throw new IllegalArgumentException("invalid expected version");
    }
    return store.rollback(tenant, principal(jwt), version, expected);
  }

  @PutMapping("/memberships/{subject}")
  public Map<String, Long> membership(
      @PathVariable String tenant,
      @PathVariable String subject,
      @AuthenticationPrincipal Jwt jwt,
      @RequestBody MembershipUpdate request) {
    if (subject.length() > 128
        || request.roles() == null
        || request.roles().size() > 100
        || request.department() != null && request.department().length() > 256)
      throw new IllegalArgumentException("membership limits");
    return Map.of(
        "tenantEpoch",
        store.membership(
            tenant,
            principal(jwt),
            new PolicyStore.Principal(jwt.getIssuer().toString(), subject),
            new PolicyStore.Membership(
                request.roles(),
                request.department(),
                request.clearance(),
                request.suspended(),
                request.administrative(),
                request.active())));
  }

  @PostMapping("/simulate")
  public PolicyEngine.Decision simulate(
      @PathVariable String tenant, @AuthenticationPrincipal Jwt jwt, @RequestBody Simulation r) {
    return store.simulate(
        tenant,
        principal(jwt),
        m -> {
          PolicyEngine.Compiled p = PolicyEngine.compile(r.policy());
          Example e = r.example();
          return PolicyEngine.decide(
              p, e.roles(), e.action(), e.resourceType(), normalize(e.fields()));
        });
  }

  @GetMapping("/audit")
  public List<PolicyStore.Audit> audit(
      @PathVariable String tenant, @AuthenticationPrincipal Jwt jwt) {
    return store.audits(tenant, principal(jwt));
  }

  static Map<String, Object> normalize(Map<String, Object> input) {
    Map<String, Object> out = new HashMap<>();
    input.forEach(
        (k, v) ->
            out.put(
                k,
                PolicyLanguage.FIELDS.get(k) == PolicyLanguage.Type.ENUM
                        && v instanceof String label
                    ? PolicyLanguage.Label.valueOf(label)
                    : v instanceof Integer n ? n.longValue() : v));
    return out;
  }

  @GetMapping("/metrics")
  public Map<String, Object> metrics(
      @PathVariable String tenant, @AuthenticationPrincipal Jwt jwt) {
    return store.simulate(
        tenant,
        principal(jwt),
        membership ->
            Map.of(
                "queryCount",
                store.queryCount(tenant),
                "cacheSize",
                cache.asMap().keySet().stream().filter(k -> k.tenant().equals(tenant)).count(),
                "requests",
                bounds.tenantStats(tenant)));
  }

  public long cacheSize() {
    return cache.estimatedSize();
  }

  public void evict() {
    cache.invalidateAll();
  }

  @ExceptionHandler(PolicyStore.Forbidden.class)
  public ResponseEntity<ProblemDetail> forbidden() {
    return problem(403, "Forbidden", "tenant membership or administrative permission required");
  }

  @ExceptionHandler(PolicyStore.Conflict.class)
  public ResponseEntity<ProblemDetail> conflict() {
    return problem(
        409, "Conflict", "active policy changed or transaction conflicted; reread before retry");
  }

  @ExceptionHandler({IllegalArgumentException.class, NullPointerException.class})
  public ResponseEntity<ProblemDetail> invalid() {
    return problem(400, "Invalid request", "request or policy validation failed");
  }

  @ExceptionHandler({PolicyStore.StoreFailure.class, IllegalStateException.class})
  public ResponseEntity<ProblemDetail> unavailable() {
    return problem(503, "Unavailable", "authorization dependency unavailable; operation refused");
  }

  private static ResponseEntity<ProblemDetail> problem(int status, String title, String detail) {
    ProblemDetail p = ProblemDetail.forStatusAndDetail(HttpStatusCode.valueOf(status), detail);
    p.setTitle(title);
    return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import com.github.benmanes.caffeine.cache.*;
import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.*;
import java.time.Duration;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
public class RequestBounds extends OncePerRequestFilter {
  private final Semaphore permits = new Semaphore(64);
  private final AtomicInteger inFlight = new AtomicInteger(), maximum = new AtomicInteger();
  private final Cache<String, Bucket> quotas =
      Caffeine.newBuilder().maximumSize(1000).expireAfterAccess(Duration.ofMinutes(5)).build();

  private static final class Bucket {
    long second;
    int count;
    final AtomicInteger inFlight = new AtomicInteger(),
        maximum = new AtomicInteger(),
        rejected = new AtomicInteger();

    synchronized boolean take() {
      long now = System.nanoTime() / 1_000_000_000L;
      if (now != second) {
        second = now;
        count = 0;
      }
      return ++count <= 5000;
    }
  }

  @Override
  protected void doFilterInternal(
      HttpServletRequest request, HttpServletResponse response, FilterChain chain)
      throws ServletException, IOException {
    String[] path = request.getRequestURI().split("/");
    String tenant =
        path.length > 3 && path[1].equals("v1") && path[2].equals("tenants") ? path[3] : "_other";
    if(!tenant.equals("_other")) {
      try { tenant=org.springframework.web.util.UriUtils.decode(tenant,java.nio.charset.StandardCharsets.UTF_8); }
      catch(IllegalArgumentException e){error(response,400,"invalid tenant path");return;}
      if(!tenant.matches("[A-Za-z0-9_-]{1,128}")){error(response,400,"invalid tenant path");return;}
    }
    Bucket bucket = quotas.get(tenant, k -> new Bucket());
    if (!bucket.take() || !permits.tryAcquire()) {
      bucket.rejected.incrementAndGet();
      error(response, 429, "authorization capacity exceeded");
      return;
    }
    int tenantActive = bucket.inFlight.incrementAndGet();
    bucket.maximum.accumulateAndGet(tenantActive, Math::max);
    int active = inFlight.incrementAndGet();
    maximum.accumulateAndGet(active, Math::max);
    try {
      byte[] body = request.getInputStream().readNBytes(262145);
      if (body.length > 262144) {
        error(response, 413, "request body limit");
        return;
      }
      HttpServletRequestWrapper bounded =
          new HttpServletRequestWrapper(request) {
            @Override
            public ServletInputStream getInputStream() {
              ByteArrayInputStream b = new ByteArrayInputStream(body);
              return new ServletInputStream() {
                public int read() {
                  return b.read();
                }

                public int read(byte[] a, int o, int l) {
                  return b.read(a, o, l);
                }

                public boolean isFinished() {
                  return b.available() == 0;
                }

                public boolean isReady() {
                  return true;
                }

                public void setReadListener(ReadListener l) {
                  throw new UnsupportedOperationException();
                }
              };
            }

            @Override
            public BufferedReader getReader() {
              return new BufferedReader(
                  new InputStreamReader(getInputStream(), java.nio.charset.StandardCharsets.UTF_8));
            }
          };
      chain.doFilter(bounded, response);
    } finally {
      bucket.inFlight.decrementAndGet();
      inFlight.decrementAndGet();
      permits.release();
    }
  }

  private static void error(HttpServletResponse r, int status, String detail) throws IOException {
    r.setStatus(status);
    r.setContentType("application/problem+json");
    r.getWriter()
        .write(
            "{\"type\":\"about:blank\",\"status\":" + status + ",\"detail\":\"" + detail + "\"}");
  }

  public java.util.Map<String, Integer> tenantStats(String tenant) {
    Bucket b = quotas.getIfPresent(tenant);
    return b == null
        ? java.util.Map.of("maximumInFlight", 0, "rejections", 0)
        : java.util.Map.of("maximumInFlight", b.maximum.get(), "rejections", b.rejected.get());
  }

  public int maximumInFlight() {
    return maximum.get();
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import java.time.*;
import java.util.*;
import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.*;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;
import org.springframework.http.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.core.*;
import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestClient;

@SpringBootApplication
@RestController
public class ProtectedDocuments {
  public static void main(String[] args) {
    SpringApplication.run(ProtectedDocuments.class, args);
  }

  private final RestClient decisionClient;

  public ProtectedDocuments(Environment e) {
    var transport =
        new org.springframework.http.client.JdkClientHttpRequestFactory(
            java.net.http.HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build());
    transport.setReadTimeout(Duration.ofSeconds(5));
    decisionClient =
        RestClient.builder()
            .baseUrl(e.getProperty("gatehouse.decision-url", "http://127.0.0.1:18500"))
            .requestFactory(transport)
            .build();
  }

  @Bean
  JwtDecoder decoder(Environment e) {
    String issuer = e.getRequiredProperty("gatehouse.oidc.issuer");
    NimbusJwtDecoder d =
        NimbusJwtDecoder.withJwkSetUri(e.getRequiredProperty("gatehouse.oidc.jwks"))
            .jwsAlgorithm(SignatureAlgorithm.RS256)
            .build();
    d.setJwtValidator(
        new DelegatingOAuth2TokenValidator<>(
            new JwtIssuerValidator(issuer),
            new JwtTimestampValidator(Duration.ZERO),
            jwt ->
                jwt.getSubject() != null
                        && !jwt.getSubject().isBlank()
                        && jwt.getAudience() != null
                        && jwt.getAudience().contains("gatehouse")
                        && jwt.getExpiresAt() != null
                        && jwt.getIssuedAt() != null
                        && !jwt.getIssuedAt().isAfter(Instant.now())
                    ? OAuth2TokenValidatorResult.success()
                    : OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"))));
    return d;
  }

  @Bean
  SecurityFilterChain security(HttpSecurity h) throws Exception {
    return h.csrf(c -> c.disable())
        .authorizeHttpRequests(a -> a.anyRequest().authenticated())
        .oauth2ResourceServer(o -> o.jwt(j -> {}))
        .build();
  }

  @GetMapping("/v1/tenants/{tenant}/documents/{id}")
  public ResponseEntity<?> read(
      @PathVariable String tenant, @PathVariable String id, @AuthenticationPrincipal Jwt jwt) {
    if (!tenant.matches("[A-Za-z0-9_-]{1,128}") || !id.matches("[A-Za-z0-9:_-]{1,128}"))
      return ResponseEntity.badRequest().build();
    try {
      Map<?, ?> decision =
          decisionClient
              .post()
              .uri("/v1/tenants/{tenant}/decisions", tenant)
              .header("Authorization", "Bearer " + jwt.getTokenValue())
              .body(
                  Map.of(
                      "action",
                      "document:read",
                      "resource",
                      Map.of("type", "document", "id", id),
                      "context",
                      Map.of("purpose", "support")))
              .retrieve()
              .body(Map.class);
      if (decision != null && "ALLOW".equals(decision.get("decision")))
        return ResponseEntity.ok(
            Map.of("id", id, "content", "Synthetic portfolio document", "authorization", decision));
      return ResponseEntity.status(403).body(Map.of("detail", "document access denied"));
    } catch (RuntimeException e) {
      return ResponseEntity.status(503)
          .body(Map.of("detail", "authorization unavailable; operation refused"));
    }
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import static io.github.cheshmakzanoon.portfolio.gatehouse.PolicyLanguage.*;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

/** Immutable candidate index, role closure, and conservative deterministic combining algorithm. */
public final class PolicyEngine {
  public enum Effect {
    ALLOW,
    DENY
  }

  public record Rule(
      String id, String action, String resourceType, Effect effect, String condition) {}

  public record Grant(String role, String action, String resourceType) {}

  public record Definition(Map<String, Set<String>> parents, List<Grant> grants, List<Rule> rules) {
    public Definition {
      Map<String, Set<String>> p = new TreeMap<>();
      parents.forEach((k, v) -> p.put(k, Set.copyOf(v)));
      parents = Collections.unmodifiableMap(p);
      grants = List.copyOf(grants);
      rules = List.copyOf(rules);
    }
  }

  public record Candidate(Rule rule, Expr expression) {}

  public record Decision(boolean allowed, String reason, List<String> matchedRuleIds) {
    public Decision {
      matchedRuleIds = List.copyOf(matchedRuleIds);
    }
  }

  public record Compiled(
      Definition definition,
      Map<String, Set<String>> closure,
      Map<String, List<Candidate>> index,
      String digest) {
    public Set<String> roles(Set<String> assigned) {
      Set<String> all = new TreeSet<>();
      for (String r : assigned) all.addAll(closure.getOrDefault(r, Set.of()));
      return Set.copyOf(all);
    }
  }

  private PolicyEngine() {}

  public static Compiled compile(Definition d) {
    if (d.parents().size() > 100 || d.rules().size() > 200 || d.grants().size() > 2000)
      throw new InvalidPolicy("policy collection bounds");
    Map<String, Set<String>> closure = new TreeMap<>();
    for (String role : d.parents().keySet()) visit(role, d.parents(), closure, new HashSet<>());
    for (Grant g : d.grants()) {
      identifier(g.action());
      identifier(g.resourceType());
      if (!closure.containsKey(g.role())) throw new InvalidPolicy("grant references unknown role");
    }
    Map<String, List<Candidate>> index = new TreeMap<>();
    Set<String> ids = new HashSet<>();
    for (Rule r : d.rules()) {
      identifier(r.id());
      identifier(r.action());
      identifier(r.resourceType());
      if (!ids.add(r.id()) || r.effect() == null) throw new InvalidPolicy("duplicate/invalid rule");
      Expr e = PolicyLanguage.compile(r.condition());
      validateRoles(e, closure.keySet());
      index
          .computeIfAbsent(key(r.action(), r.resourceType()), x -> new ArrayList<>())
          .add(new Candidate(r, e));
    }
    Map<String, List<Candidate>> frozen = new TreeMap<>();
    index.forEach(
        (k, v) ->
            frozen.put(k, v.stream().sorted(Comparator.comparing(c -> c.rule().id())).toList()));
    String canonical =
        d.parents().entrySet().stream().map(e -> e.getKey() + new TreeSet<>(e.getValue())).toList()
            + "|"
            + d.grants().stream().map(g -> encoded(g.toString())).sorted().toList()
            + "|"
            + d.rules().stream().map(r -> encoded(r.toString())).sorted().toList();
    try {
      return new Compiled(
          d,
          Collections.unmodifiableMap(closure),
          Collections.unmodifiableMap(frozen),
          HexFormat.of()
              .formatHex(
                  MessageDigest.getInstance("SHA-256")
                      .digest(canonical.getBytes(StandardCharsets.UTF_8))));
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException(e);
    }
  }

  private static String encoded(String value) {
    return Base64.getUrlEncoder()
        .withoutPadding()
        .encodeToString(value.getBytes(StandardCharsets.UTF_8));
  }

  private static void identifier(String s) {
    if (s == null || s.isBlank() || s.length() > 128 || !s.matches("[A-Za-z0-9_:.\\-]+"))
      throw new InvalidPolicy("invalid identifier");
  }

  private static Set<String> visit(
      String role,
      Map<String, Set<String>> graph,
      Map<String, Set<String>> result,
      Set<String> stack) {
    identifier(role);
    if (result.containsKey(role)) return result.get(role);
    if (!graph.containsKey(role)) throw new InvalidPolicy("missing parent role");
    if (!stack.add(role)) throw new InvalidPolicy("role cycle");
    Set<String> all = new TreeSet<>();
    all.add(role);
    for (String parent : graph.get(role)) all.addAll(visit(parent, graph, result, stack));
    stack.remove(role);
    Set<String> out = Set.copyOf(all);
    result.put(role, out);
    return out;
  }

  private static void validateRoles(Expr e, Set<String> roles) {
    switch (e) {
      case HasRole r -> {
        if (!roles.contains(r.role())) throw new InvalidPolicy("unknown role predicate");
      }
      case Binary b -> {
        validateRoles(b.left(), roles);
        validateRoles(b.right(), roles);
      }
      case Negate n -> validateRoles(n.child(), roles);
      case Compare c -> {
        validateRoles(c.left(), roles);
        validateRoles(c.right(), roles);
      }
      case In n -> validateRoles(n.value(), roles);
      default -> {}
    }
  }

  private static String key(String action, String type) {
    return action + "\u0000" + type;
  }

  public static Decision decide(
      Compiled policy,
      Set<String> assigned,
      String action,
      String resourceType,
      Map<String, Object> fields) {
    Set<String> roles = policy.roles(assigned);
    Inputs inputs = new Inputs(fields, roles);
    List<String> matched = new ArrayList<>();
    boolean allow = false, deny = false, unknown = false;
    for (Candidate c : policy.index().getOrDefault(key(action, resourceType), List.of())) {
      Truth truth;
      try {
        truth = PolicyLanguage.evaluate(c.expression(), inputs);
      } catch (RuntimeException e) {
        truth = Truth.UNKNOWN;
      }
      if (truth == Truth.UNKNOWN) unknown = true;
      else if (truth == Truth.TRUE) {
        matched.add(c.rule().id());
        if (c.rule().effect() == Effect.DENY) deny = true;
        else allow = true;
      }
    }
    if (deny) return new Decision(false, "EXPLICIT_DENY", matched);
    if (unknown) return new Decision(false, "INDETERMINATE", matched);
    boolean grant =
        policy.definition().grants().stream()
            .anyMatch(
                g ->
                    roles.contains(g.role())
                        && g.action().equals(action)
                        && g.resourceType().equals(resourceType));
    return grant && allow
        ? new Decision(true, "MATCHED_ALLOW", matched)
        : new Decision(false, grant ? "NO_ABAC_ALLOW" : "NO_RBAC_GRANT", matched);
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Restricted, statically typed language. Compilation and evaluation have independent work budgets.
 */
public final class PolicyLanguage {
  public static final int MAX_BYTES = 16_384,
      MAX_NODES = 512,
      MAX_DEPTH = 32,
      MAX_STRING = 256,
      MAX_SET = 64;

  public enum Type {
    BOOLEAN,
    STRING,
    INTEGER,
    ENUM
  }

  public enum Label {
    PUBLIC,
    INTERNAL,
    CONFIDENTIAL
  }

  public enum Truth {
    TRUE,
    FALSE,
    UNKNOWN;

    public Truth not() {
      return this == UNKNOWN ? UNKNOWN : this == TRUE ? FALSE : TRUE;
    }

    public Truth and(Truth b) {
      return this == FALSE || b == FALSE ? FALSE : this == UNKNOWN || b == UNKNOWN ? UNKNOWN : TRUE;
    }

    public Truth or(Truth b) {
      return this == TRUE || b == TRUE ? TRUE : this == UNKNOWN || b == UNKNOWN ? UNKNOWN : FALSE;
    }
  }

  public static final Map<String, Type> FIELDS =
      Map.ofEntries(
          Map.entry("subject.department", Type.STRING),
          Map.entry("subject.clearance", Type.INTEGER),
          Map.entry("subject.suspended", Type.BOOLEAN),
          Map.entry("resource.department", Type.STRING),
          Map.entry("resource.classification", Type.INTEGER),
          Map.entry("resource.type", Type.STRING),
          Map.entry("resource.id", Type.STRING),
          Map.entry("resource.sensitivity", Type.ENUM),
          Map.entry("context.purpose", Type.STRING),
          Map.entry("context.hour", Type.INTEGER));

  public sealed interface Expr
      permits Literal, Field, Binary, Negate, Compare, Exists, HasRole, In {
    Type type();
  }

  public record Literal(Object value, Type type) implements Expr {}

  public record Field(String name, Type type) implements Expr {}

  public record Binary(String op, Expr left, Expr right) implements Expr {
    public Type type() {
      return Type.BOOLEAN;
    }
  }

  public record Negate(Expr child) implements Expr {
    public Type type() {
      return Type.BOOLEAN;
    }
  }

  public record Compare(String op, Expr left, Expr right) implements Expr {
    public Type type() {
      return Type.BOOLEAN;
    }
  }

  public record Exists(Field field) implements Expr {
    public Type type() {
      return Type.BOOLEAN;
    }
  }

  public record HasRole(String role) implements Expr {
    public Type type() {
      return Type.BOOLEAN;
    }
  }

  public record In(Expr value, List<Literal> values) implements Expr {
    public In {
      values = List.copyOf(values);
    }

    public Type type() {
      return Type.BOOLEAN;
    }
  }

  public record Inputs(Map<String, Object> fields, Set<String> roles) {
    public Inputs {
      fields = Map.copyOf(fields);
      roles = Set.copyOf(roles);
      fields.forEach(
          (k, v) -> {
            Type t = FIELDS.get(k);
            if (t == null
                || !(t == Type.STRING && v instanceof String s && s.length() <= MAX_STRING
                    || t == Type.INTEGER && v instanceof Long
                    || t == Type.BOOLEAN && v instanceof Boolean
                    || t == Type.ENUM && v instanceof Label))
              throw new IllegalArgumentException("invalid input field: " + k);
          });
    }
  }

  public static final class InvalidPolicy extends IllegalArgumentException {
    public InvalidPolicy(String message) {
      super(message);
    }
  }

  private PolicyLanguage() {}

  public static Expr compile(String text) {
    if (text == null || text.getBytes(StandardCharsets.UTF_8).length > MAX_BYTES)
      throw new InvalidPolicy("policy byte limit");
    Parser p = new Parser(text);
    Expr e = p.expression(0);
    if (!p.peek("<end>")) throw p.error("trailing token");
    if (e.type() != Type.BOOLEAN) throw p.error("condition must be boolean");
    return e;
  }

  public static Truth evaluate(Expr expression, Inputs inputs) {
    Object value = eval(expression, inputs, new int[] {MAX_NODES * 2});
    return value == null ? Truth.UNKNOWN : (Boolean) value ? Truth.TRUE : Truth.FALSE;
  }

  private static Object eval(Expr e, Inputs i, int[] budget) {
    if (--budget[0] < 0) throw new InvalidPolicy("evaluation budget exhausted");
    return switch (e) {
      case Literal l -> l.value();
      case Field f -> i.fields().get(f.name());
      case Exists x -> i.fields().containsKey(x.field().name());
      case HasRole r -> i.roles().contains(r.role());
      case Negate n -> bool(truth(eval(n.child(), i, budget)).not());
      case Binary b -> {
        Truth a = truth(eval(b.left(), i, budget));
        Truth z = truth(eval(b.right(), i, budget));
        yield bool(b.op().equals("and") ? a.and(z) : a.or(z));
      }
      case Compare c -> {
        Object a = eval(c.left(), i, budget), b = eval(c.right(), i, budget);
        if (a == null || b == null) yield null;
        int order =
            a instanceof Long n
                ? Long.compare(n, (Long) b)
                : a instanceof String s
                    ? s.compareTo((String) b)
                    : a instanceof Label l
                        ? l.compareTo((Label) b)
                        : Boolean.compare((Boolean) a, (Boolean) b);
        yield switch (c.op()) {
          case "==" -> order == 0;
          case "!=" -> order != 0;
          case ">" -> order > 0;
          case ">=" -> order >= 0;
          case "<" -> order < 0;
          case "<=" -> order <= 0;
          default -> throw new InvalidPolicy("bad operator");
        };
      }
      case In n -> {
        Object v = eval(n.value(), i, budget);
        yield v == null ? null : n.values().stream().anyMatch(x -> x.value().equals(v));
      }
    };
  }

  private static Truth truth(Object x) {
    return x == null ? Truth.UNKNOWN : (Boolean) x ? Truth.TRUE : Truth.FALSE;
  }

  private static Boolean bool(Truth t) {
    return t == Truth.UNKNOWN ? null : t == Truth.TRUE;
  }

  private record Token(String text, boolean string) {}

  private static final class Parser {
    private final List<Token> tokens = new ArrayList<>();
    private int pos, nodes;

    Parser(String text) {
      for (int n = 0; n < text.length(); ) {
        char c = text.charAt(n);
        if (Character.isWhitespace(c)) {
          n++;
          continue;
        }
        if (c == '"') {
          StringBuilder b = new StringBuilder();
          n++;
          boolean closed = false;
          while (n < text.length()) {
            c = text.charAt(n++);
            if (c == '"') {
              closed = true;
              break;
            }
            if (c == '\\') {
              if (n >= text.length()) throw error("unterminated escape");
              c = text.charAt(n++);
              if (c != '"' && c != '\\') throw error("unsupported escape");
            }
            if (c < 32) throw error("control character");
            b.append(c);
            if (b.length() > MAX_STRING) throw error("literal length");
          }
          if (!closed) throw error("unterminated string");
          tokens.add(new Token(b.toString(), true));
        } else if (Character.isLetter(c) || c == '_' || Character.isDigit(c) || c == '-') {
          int start = n++;
          while (n < text.length()
              && (Character.isLetterOrDigit(text.charAt(n))
                  || text.charAt(n) == '.'
                  || text.charAt(n) == '_'
                  || text.charAt(n) == '-')) n++;
          tokens.add(new Token(text.substring(start, n), false));
        } else {
          String op = String.valueOf(c);
          n++;
          if (n < text.length() && text.charAt(n) == '=' && "=!<>".indexOf(c) >= 0)
            op += text.charAt(n++);
          if (!Set.of("(", ")", "[", "]", ",", "==", "!=", ">", "<", ">=", "<=").contains(op))
            throw error("illegal token");
          tokens.add(new Token(op, false));
        }
        if (tokens.size() > MAX_NODES * 6) throw error("token limit");
      }
      tokens.add(new Token("<end>", false));
    }

    InvalidPolicy error(String x) {
      return new InvalidPolicy(x + " at token " + pos);
    }

    boolean peek(String t) {
      return !tokens.get(pos).string() && tokens.get(pos).text().equals(t);
    }

    boolean take(String t) {
      if (peek(t)) {
        pos++;
        return true;
      }
      return false;
    }

    void expect(String t) {
      if (!take(t)) throw error("expected " + t);
    }

    Expr node(Expr e) {
      if (++nodes > MAX_NODES) throw error("AST node limit");
      return e;
    }

    Expr expression(int depth) {
      checkDepth(depth);
      Expr e = and(depth + 1);
      while (take("or")) {
        Expr b = and(depth + 1);
        requireBool(e);
        requireBool(b);
        e = node(new Binary("or", e, b));
      }
      return e;
    }

    Expr and(int d) {
      Expr e = unary(d);
      while (take("and")) {
        Expr b = unary(d);
        requireBool(e);
        requireBool(b);
        e = node(new Binary("and", e, b));
      }
      return e;
    }

    Expr unary(int d) {
      checkDepth(d);
      if (take("not")) {
        Expr e = unary(d + 1);
        requireBool(e);
        return node(new Negate(e));
      }
      if (take("(")) {
        Expr e = expression(d + 1);
        expect(")");
        return e;
      }
      return comparison(d);
    }

    void checkDepth(int d) {
      if (d > MAX_DEPTH) throw error("nesting limit");
    }

    void requireBool(Expr e) {
      if (e.type() != Type.BOOLEAN) throw error("expected boolean");
    }

    Expr comparison(int d) {
      Expr a = atom();
      if (take("in")) {
        expect("[");
        List<Literal> list = new ArrayList<>();
        do {
          Expr b = atom();
          if (!(b instanceof Literal l) || b.type() != a.type()) throw error("set element type");
          list.add(l);
          if (list.size() > MAX_SET) throw error("set limit");
        } while (take(","));
        expect("]");
        return node(new In(a, list));
      }
      if (Set.of("==", "!=", ">", "<", ">=", "<=").contains(tokens.get(pos).text())
          && !tokens.get(pos).string()) {
        String op = tokens.get(pos++).text();
        Expr b = atom();
        if (a.type() != b.type()) throw error("comparison type mismatch");
        if ((a.type() == Type.BOOLEAN || a.type() == Type.ENUM) && !Set.of("==", "!=").contains(op))
          throw error("boolean ordering forbidden");
        return node(new Compare(op, a, b));
      }
      return a;
    }

    Expr atom() {
      if (pos >= tokens.size() - 1) throw error("unexpected end of input");
      Token t = tokens.get(pos++);
      if (t.string()) return node(new Literal(t.text(), Type.STRING));
      String s = t.text();
      if (s.equals("exists")) {
        expect("(");
        Expr f = atom();
        if (!(f instanceof Field field)) throw error("exists requires field");
        expect(")");
        return node(new Exists(field));
      }
      if (s.equals("hasRole")) {
        expect("(");
        Token role = tokens.get(pos++);
        if (!role.string() || role.text().isBlank()) throw error("role name required");
        expect(")");
        return node(new HasRole(role.text()));
      }
      if (Set.of("PUBLIC", "INTERNAL", "CONFIDENTIAL").contains(s))
        return node(new Literal(Label.valueOf(s), Type.ENUM));
      if (FIELDS.containsKey(s)) return node(new Field(s, FIELDS.get(s)));
      if (s.equals("true") || s.equals("false"))
        return node(new Literal(Boolean.valueOf(s), Type.BOOLEAN));
      try {
        return node(new Literal(Long.parseLong(s), Type.INTEGER));
      } catch (NumberFormatException ignored) {
        throw error("unknown field or literal");
      }
    }
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.*;
import java.util.*;
import java.util.function.Function;
import javax.sql.DataSource;

/**
 * JDBC transactions use a transaction-local tenant variable; no session tenant state survives a
 * pool return.
 */
public final class PolicyStore {
  public record Principal(String issuer, String subject) {
    public Principal {
      if (issuer == null || subject == null || subject.length() > 128)
        throw new IllegalArgumentException("principal");
    }
  }

  public record Membership(
      Set<String> roles,
      String department,
      Long clearance,
      Boolean suspended,
      boolean admin,
      boolean active) {
    public Membership {
      roles = Set.copyOf(roles);
    }
  }

  public record Revision(long version, String content, String digest) {}

  public record Resource(
      String id, String type, String department, Long classification, long version) {}

  public record Snapshot(long epoch, Membership membership, Revision policy, Resource resource) {}

  public record Audit(
      UUID id,
      String principal,
      String action,
      String resource,
      long epoch,
      String result,
      String reason) {}

  public record Outcome(Snapshot snapshot, PolicyEngine.Decision decision, UUID id) {}

  public static class StoreFailure extends RuntimeException {
    public StoreFailure(Exception e) {
      super("authorization dependency unavailable", e);
    }
  }

  public static class Forbidden extends RuntimeException {}

  public static class Conflict extends RuntimeException {}

  private final DataSource dataSource;
  private final ThreadLocal<long[]> transactionQueries = new ThreadLocal<>();
  private final Map<String, Long> tenantQueries =
      Collections.synchronizedMap(new LinkedHashMap<>());

  public long queryCount(String tenant) {
    return tenantQueries.getOrDefault(tenant, 0L);
  }

  private final java.util.concurrent.atomic.LongAdder queryCount =
      new java.util.concurrent.atomic.LongAdder();

  private PreparedStatement prepare(Connection c, String sql) throws SQLException {
    queryCount.increment();
    long[] count = transactionQueries.get();
    if (count != null) count[0]++;
    return c.prepareStatement(sql);
  }

  public long queryCount() {
    return queryCount.sum();
  }

  public PolicyStore(DataSource dataSource) {
    this.dataSource = dataSource;
  }

  @FunctionalInterface
  private interface Work<T> {
    T run(Connection c) throws SQLException;
  }

  private <T> T transaction(String tenant, boolean write, Work<T> work) {
    if (tenant == null || !tenant.matches("[A-Za-z0-9_-]{1,128}"))
      throw new IllegalArgumentException("invalid tenant");
    transactionQueries.set(new long[] {0});
    try (Connection c = dataSource.getConnection()) {
      c.setAutoCommit(false);
      c.setTransactionIsolation(
          write ? Connection.TRANSACTION_SERIALIZABLE : Connection.TRANSACTION_REPEATABLE_READ);
      try (PreparedStatement s =
          prepare(
              c,
              "SELECT set_config('gatehouse.tenant', ?, true), set_config('statement_timeout','5000',true), set_config('lock_timeout','3000',true)")) {
        s.setString(1, tenant);
        s.execute();
      }
      try {
        T result = work.run(c);
        c.commit();
        synchronized (tenantQueries) {
          if (tenantQueries.size() < 1000 || tenantQueries.containsKey(tenant))
            tenantQueries.merge(tenant, transactionQueries.get()[0], Long::sum);
        }
        return result;
      } catch (SQLException | RuntimeException e) {
        c.rollback();
        throw e;
      }
    } catch (SQLException e) {
      if ("40001".equals(e.getSQLState())) throw new Conflict();
      throw new StoreFailure(e);
    } finally {
      transactionQueries.remove();
    }
  }

  private long epoch(Connection c, String tenant, boolean lock) throws SQLException {
    try (PreparedStatement s =
        prepare(c, "SELECT epoch FROM tenant WHERE tenant_id=?" + (lock ? " FOR UPDATE" : ""))) {
      s.setString(1, tenant);
      try (ResultSet r = s.executeQuery()) {
        if (!r.next()) throw new Forbidden();
        return r.getLong(1);
      }
    }
  }

  private Membership membership(Connection c, String tenant, Principal p) throws SQLException {
    try (PreparedStatement s =
        prepare(
            c,
            "SELECT roles,department,clearance,suspended,administrative,active FROM membership WHERE tenant_id=? AND issuer=? AND subject_id=?")) {
      s.setString(1, tenant);
      s.setString(2, p.issuer());
      s.setString(3, p.subject());
      try (ResultSet r = s.executeQuery()) {
        if (!r.next()) return null;
        return new Membership(
            Set.of((String[]) r.getArray(1).getArray()),
            r.getString(2),
            r.getObject(3, Long.class),
            r.getObject(4, Boolean.class),
            r.getBoolean(5),
            r.getBoolean(6));
      }
    }
  }

  private void administrative(Connection c, String tenant, Principal p) throws SQLException {
    Membership m = membership(c, tenant, p);
    if (m == null || !m.active() || !m.admin()) throw new Forbidden();
  }

  private Revision revision(Connection c, String tenant, long version) throws SQLException {
    try (PreparedStatement s =
        prepare(
            c,
            "SELECT version,content,digest FROM policy_version WHERE tenant_id=? AND version=?")) {
      s.setString(1, tenant);
      s.setLong(2, version);
      try (ResultSet r = s.executeQuery()) {
        if (!r.next()) throw new IllegalArgumentException("unknown version");
        return new Revision(r.getLong(1), r.getString(2), r.getString(3));
      }
    }
  }

  private long active(Connection c, String tenant) throws SQLException {
    try (PreparedStatement s = prepare(c, "SELECT version FROM active_policy WHERE tenant_id=?")) {
      s.setString(1, tenant);
      try (ResultSet r = s.executeQuery()) {
        return r.next() ? r.getLong(1) : 0;
      }
    }
  }

  private Resource resource(Connection c, String tenant, String id) throws SQLException {
    try (PreparedStatement s =
        prepare(
            c,
            "SELECT resource_id,resource_type,department,classification,resource_version FROM resource WHERE tenant_id=? AND resource_id=?")) {
      s.setString(1, tenant);
      s.setString(2, id);
      try (ResultSet r = s.executeQuery()) {
        return r.next()
            ? new Resource(
                r.getString(1),
                r.getString(2),
                r.getString(3),
                r.getObject(4, Long.class),
                r.getLong(5))
            : null;
      }
    }
  }

  public Outcome decide(
      String tenant,
      Principal principal,
      String action,
      String id,
      Function<Snapshot, PolicyEngine.Decision> evaluator) {
    return transaction(
        tenant,
        false,
        c -> {
          long e = epoch(c, tenant, false);
          Membership m = membership(c, tenant, principal);
          long v = m != null && m.active() ? active(c, tenant) : 0;
          Snapshot snap =
              new Snapshot(
                  m == null ? 0 : e,
                  m,
                  v == 0 ? null : revision(c, tenant, v),
                  m != null && m.active() ? resource(c, tenant, id) : null);
          PolicyEngine.Decision d = evaluator.apply(snap);
          UUID decisionId = UUID.randomUUID();
          audit(
              c,
              tenant,
              new Audit(
                  decisionId,
                  principalRef(principal),
                  action,
                  id,
                  e,
                  d.allowed() ? "ALLOW" : "DENY",
                  d.reason()));
          return new Outcome(snap, d, decisionId);
        });
  }

  public long draft(String tenant, Principal p, String content, PolicyEngine.Compiled compiled) {
    return transaction(
        tenant,
        true,
        c -> {
          epoch(c, tenant, true);
          administrative(c, tenant, p);
          long version;
          try (PreparedStatement s =
              prepare(
                  c, "SELECT COALESCE(MAX(version),0)+1 FROM policy_version WHERE tenant_id=?")) {
            s.setString(1, tenant);
            try (ResultSet r = s.executeQuery()) {
              r.next();
              version = r.getLong(1);
            }
          }
          try (PreparedStatement s =
              prepare(
                  c,
                  "INSERT INTO policy_version(tenant_id,version,content,digest) VALUES(?,?,?,?)")) {
            s.setString(1, tenant);
            s.setLong(2, version);
            s.setString(3, content);
            s.setString(4, compiled.digest());
            s.executeUpdate();
          }
          for (String role : compiled.definition().parents().keySet()) {
            try (PreparedStatement s = prepare(c, "INSERT INTO role VALUES(?,?,?)")) {
              s.setString(1, tenant);
              s.setLong(2, version);
              s.setString(3, role);
              s.executeUpdate();
            }
          }
          for (var entry : compiled.definition().parents().entrySet())
            for (String parent : entry.getValue()) {
              try (PreparedStatement s = prepare(c, "INSERT INTO role_edge VALUES(?,?,?,?)")) {
                s.setString(1, tenant);
                s.setLong(2, version);
                s.setString(3, entry.getKey());
                s.setString(4, parent);
                s.executeUpdate();
              }
            }
          for (var g : compiled.definition().grants()) {
            try (PreparedStatement s = prepare(c, "INSERT INTO \"grant\" VALUES(?,?,?,?,?)")) {
              s.setString(1, tenant);
              s.setLong(2, version);
              s.setString(3, g.role());
              s.setString(4, g.action());
              s.setString(5, g.resourceType());
              s.executeUpdate();
            }
          }
          audit(
              c,
              tenant,
              new Audit(
                  UUID.randomUUID(),
                  principalRef(p),
                  "policy:draft",
                  Long.toString(version),
                  epoch(c, tenant, false),
                  "CREATED",
                  "VALIDATED"));
          return version;
        });
  }

  public long publish(String tenant, Principal p, long version, long expected) {
    return transaction(
        tenant,
        true,
        c -> {
          long e = epoch(c, tenant, true);
          administrative(c, tenant, p);
          long old = active(c, tenant);
          if (old != expected || version <= old) throw new Conflict();
          revision(c, tenant, version);
          try (PreparedStatement s =
              prepare(
                  c,
                  "INSERT INTO active_policy VALUES(?,?) ON CONFLICT(tenant_id) DO UPDATE SET version=EXCLUDED.version")) {
            s.setString(1, tenant);
            s.setLong(2, version);
            s.executeUpdate();
          }

          audit(
              c,
              tenant,
              new Audit(
                  UUID.randomUUID(),
                  principalRef(p),
                  "policy:publish",
                  Long.toString(version),
                  e + 1,
                  "PUBLISHED",
                  "EXPECTED_VERSION"));
          return e + 1;
        });
  }

  public record Published(long policyVersion, long tenantEpoch) {}

  public Published rollback(String tenant, Principal principal, long sourceVersion, long expected) {
    return transaction(
        tenant,
        true,
        c -> {
          long epoch = epoch(c, tenant, true);
          administrative(c, tenant, principal);
          if (active(c, tenant) != expected) throw new Conflict();
          revision(c, tenant, sourceVersion);
          long version;
          try (PreparedStatement q =
              prepare(
                  c, "SELECT COALESCE(MAX(version),0)+1 FROM policy_version WHERE tenant_id=?")) {
            q.setString(1, tenant);
            try (ResultSet r = q.executeQuery()) {
              r.next();
              version = r.getLong(1);
            }
          }
          for (String sql :
              List.of(
                  "INSERT INTO policy_version(tenant_id,version,content,digest) SELECT tenant_id,?,content,digest FROM policy_version WHERE tenant_id=? AND version=?",
                  "INSERT INTO role SELECT tenant_id,?,role_name FROM role WHERE tenant_id=? AND version=?",
                  "INSERT INTO role_edge SELECT tenant_id,?,child,parent FROM role_edge WHERE tenant_id=? AND version=?",
                  "INSERT INTO \"grant\" SELECT tenant_id,?,role_name,action,resource_type FROM \"grant\" WHERE tenant_id=? AND version=?")) {
            try (PreparedStatement q = prepare(c, sql)) {
              q.setLong(1, version);
              q.setString(2, tenant);
              q.setLong(3, sourceVersion);
              q.executeUpdate();
            }
          }
          try (PreparedStatement q =
              prepare(
                  c,
                  "INSERT INTO active_policy VALUES(?,?) ON CONFLICT(tenant_id) DO UPDATE SET version=EXCLUDED.version")) {
            q.setString(1, tenant);
            q.setLong(2, version);
            q.executeUpdate();
          }
          audit(
              c,
              tenant,
              new Audit(
                  UUID.randomUUID(),
                  principalRef(principal),
                  "policy:rollback",
                  Long.toString(version),
                  epoch + 1,
                  "PUBLISHED",
                  "COPIED_IMMUTABLE_VERSION"));
          return new Published(version, epoch + 1);
        });
  }

  public long membership(String tenant, Principal actor, Principal target, Membership value) {
    return transaction(
        tenant,
        true,
        c -> {
          long e = epoch(c, tenant, true);
          administrative(c, tenant, actor);
          try (PreparedStatement s =
              prepare(
                  c,
                  "INSERT INTO membership VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(tenant_id,issuer,subject_id) DO UPDATE SET roles=EXCLUDED.roles,department=EXCLUDED.department,clearance=EXCLUDED.clearance,suspended=EXCLUDED.suspended,administrative=EXCLUDED.administrative,active=EXCLUDED.active")) {
            s.setString(1, tenant);
            s.setString(2, target.issuer());
            s.setString(3, target.subject());
            s.setArray(4, c.createArrayOf("text", value.roles().toArray()));
            s.setString(5, value.department());
            s.setObject(6, value.clearance());
            s.setObject(7, value.suspended());
            s.setBoolean(8, value.admin());
            s.setBoolean(9, value.active());
            s.executeUpdate();
          }

          audit(
              c,
              tenant,
              new Audit(
                  UUID.randomUUID(),
                  principalRef(actor),
                  "membership:update",
                  principalRef(target),
                  e + 1,
                  value.active() ? "ACTIVE" : "REVOKED",
                  "ADMINISTRATIVE"));
          return e + 1;
        });
  }

  public Revision readForAdmin(String tenant, Principal p, long version) {
    return transaction(
        tenant,
        false,
        c -> {
          administrative(c, tenant, p);
          return revision(c, tenant, version);
        });
  }

  public List<Audit> audits(String tenant, Principal p) {
    return transaction(
        tenant,
        false,
        c -> {
          administrative(c, tenant, p);
          List<Audit> out = new ArrayList<>();
          try (PreparedStatement s =
              prepare(
                  c,
                  "SELECT audit_id,principal_ref,action,resource_ref,epoch,result,reason FROM audit WHERE tenant_id=? ORDER BY created_at DESC,audit_id LIMIT 100")) {
            s.setString(1, tenant);
            try (ResultSet r = s.executeQuery()) {
              while (r.next())
                out.add(
                    new Audit(
                        r.getObject(1, UUID.class),
                        r.getString(2),
                        r.getString(3),
                        r.getString(4),
                        r.getLong(5),
                        r.getString(6),
                        r.getString(7)));
            }
          }
          return List.copyOf(out);
        });
  }

  public <T> T simulate(String tenant, Principal p, Function<Membership, T> work) {
    return transaction(
        tenant,
        false,
        c -> {
          administrative(c, tenant, p);
          return work.apply(membership(c, tenant, p));
        });
  }

  private void audit(Connection c, String tenant, Audit a) throws SQLException {
    try (PreparedStatement s =
        prepare(
            c,
            "INSERT INTO audit(tenant_id,audit_id,principal_ref,action,resource_ref,epoch,result,reason) VALUES(?,?,?,?,?,?,?,?)")) {
      s.setString(1, tenant);
      s.setObject(2, a.id());
      s.setString(3, a.principal());
      s.setString(4, a.action());
      s.setString(5, a.resource());
      s.setLong(6, a.epoch());
      s.setString(7, a.result());
      s.setString(8, a.reason());
      s.executeUpdate();
    }
  }

  public static String principalRef(Principal p) {
    try {
      return HexFormat.of()
          .formatHex(
              MessageDigest.getInstance("SHA-256")
                  .digest((p.issuer() + "\0" + p.subject()).getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException(e);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.gatehouse;

import org.flywaydb.core.Flyway;

/** Separate migration entry point; the service runtime never receives these credentials. */
public final class StoreAdmin {
  private StoreAdmin() {}

  public static void main(String[] args) {
    if (args.length != 1 || !args[0].equals("migrate"))
      throw new IllegalArgumentException("usage: StoreAdmin migrate");
    Flyway.configure()
        .dataSource(
            required("GATEHOUSE_MIGRATION_URL"),
            required("GATEHOUSE_MIGRATION_USER"),
            required("GATEHOUSE_MIGRATION_PASSWORD"))
        .locations("classpath:db/migration")
        .load()
        .migrate();
  }

  private static String required(String name) {
    String value = System.getenv(name);
    if (value == null || value.isBlank()) throw new IllegalStateException("missing " + name);
    return value;
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import static io.github.cheshmakzanoon.portfolio.thepit.Model.*;

import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 3, time = 1)
@Fork(
    value = 3,
    jvmArgsAppend = {"-Xmx512m"})
public class MatchingBenchmark {
  private Book book;
  private Command incoming;

  @Setup(Level.Invocation)
  public void setup() {
    book = new Book();
    book.apply(1, new Command("init", "a", Type.INIT, null, null, 0, 0, null, false, 1000000, 100));
    book.apply(2, new Command("init", "b", Type.INIT, null, null, 0, 0, null, false, 1000000, 100));
    book.apply(
        3, new Command("ask", "b", Type.NEW, "ask", Side.SELL, 100, 10, Tif.GTC, false, 0, 0));
    incoming = new Command("buy", "a", Type.NEW, "buy", Side.BUY, 101, 5, Tif.IOC, false, 0, 0);
  }

  @Benchmark
  public void indexedPartialFill(Blackhole sink) {
    sink.consume(book.apply(4, incoming));
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import static io.github.cheshmakzanoon.portfolio.thepit.Model.*;

import java.lang.management.ManagementFactory;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Closed-loop system driver. It intentionally reports core and local-force service separately. */
public final class Workload {
  private Workload() {}

  private static Command init(int a) {
    return new Command(
        "init", "a" + a, Type.INIT, null, null, 0, 0, null, false, 1_000_000_000_000L, 100_000_000);
  }

  private static Command next(Random r, int i) {
    String account = "a" + r.nextInt(64),
        order = "o" + (i % 100 < 60 ? i : r.nextInt(Math.max(1, i)));
    int action = i % 100;
    Side side = r.nextBoolean() ? Side.BUY : Side.SELL;
    long price = 9900 + r.nextInt(201), qty = 1 + r.nextInt(10);
    return new Command(
        "c" + i,
        account,
        action < 60 ? Type.NEW : action < 85 ? Type.CANCEL : Type.REPLACE,
        order,
        side,
        price,
        qty,
        Tif.GTC,
        false,
        0,
        0);
  }

  public static void main(String[] args) throws Exception {
    if (args.length < 3)
      throw new IllegalArgumentException("usage: Workload core|durable count journal");
    String mode = args[0];
    int count = Integer.parseInt(args[1]);
    if (count < 100 || count > 1_000_000) throw new IllegalArgumentException("count 100..1000000");
    Path path = Path.of(args[2]);
    long[] latency = new long[count];
    Random random = new Random(42006006);
    int duplicates = 0, peakQueue = 0;
    long errors = 0;
    Book book = mode.equals("core") ? new Book() : null;
    Gateway gateway =
        mode.equals("durable") ? new Gateway(path, "benchmark", 256, 1_100_000) : null;
    if (book == null && gateway == null) throw new IllegalArgumentException("unknown mode");
    long sequence = 0;
    try {
      for (int a = 0; a < 64; a++) {
        Command c = init(a);
        if (book != null) book.apply(++sequence, c);
        else gateway.submit(c.accountId(), c).get(30, TimeUnit.SECONDS);
      }
      com.sun.management.ThreadMXBean bean =
          (com.sun.management.ThreadMXBean) ManagementFactory.getThreadMXBean();
      long allocatedBefore = allocated(bean);
      long start = System.nanoTime();
      for (int i = 0; i < count; i++) {
        Command c = next(random, i);
        long before = System.nanoTime();
        Result r;
        if (book != null) r = book.apply(++sequence, c);
        else {
          var future = gateway.submit(c.accountId(), c);
          peakQueue = Math.max(peakQueue, gateway.queueDepth());
          r = future.get(30, TimeUnit.SECONDS);
        }
        latency[i] = System.nanoTime() - before;
        if (r.code().equals("RISK")
            || r.code().equals("OVERFLOW")
            || r.code().equals("OPEN_ORDER_CAP")) errors++;
        if (i % 1000 == 0) {
          Result duplicate =
              book != null
                  ? book.lookup(c)
                  : gateway.submit(c.accountId(), c).get(30, TimeUnit.SECONDS);
          if (!r.equals(duplicate)) throw new AssertionError("dedup mismatch");
          duplicates++;
        }
      }
      long elapsed = System.nanoTime() - start, allocatedAfter = allocated(bean);
      View state = book != null ? book.view() : gateway.fullView();
      long cash = state.accounts().values().stream().mapToLong(Balance::cash).sum(),
          lots = state.accounts().values().stream().mapToLong(Balance::lots).sum();
      if (cash != 64_000_000_000_000L || lots != 6_400_000_000L)
        throw new AssertionError("conservation");
      Arrays.sort(latency);
      long usedHeap = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
      long recovery = 0;
      if (gateway != null) {
        gateway.close();
        gateway = null;
        long before = System.nanoTime();
        try (Gateway restored = new Gateway(path, "benchmark", 256, 1_100_000)) {
          if (!state.digest().equals(restored.fullView().digest()))
            throw new AssertionError("recovery digest");
        }
        recovery = System.nanoTime() - before;
      }
      System.out.printf(
          Locale.ROOT,
          "{\"mode\":\"%s\",\"seed\":42006006,\"commands\":%d,\"duplicateInjections\":%d,\"newPercent\":60,\"cancelPercent\":25,\"replacePercent\":15,\"accounts\":64,\"openOrderCap\":100000,\"priceDistribution\":\"uniform integral ticks 9900..10100\",\"elapsedNanos\":%d,\"commandsPerSecond\":%.3f,\"p50Nanos\":%d,\"p95Nanos\":%d,\"p99Nanos\":%d,\"batchSize\":1,\"forces\":%d,\"peakObservedQueue\":%d,\"riskOrCapacityRejections\":%d,\"allocationBytesPerCommand\":%.3f,\"usedHeapBytes\":%d,\"recoveryNanos\":%d,\"finalDigest\":\"%s\"}%n",
          mode,
          count,
          duplicates,
          elapsed,
          count * 1e9 / elapsed,
          latency[count / 2],
          latency[(int) (count * .95)],
          latency[(int) (count * .99)],
          mode.equals("durable") ? count + 64 : 0,
          peakQueue,
          errors,
          (allocatedAfter - allocatedBefore) / (double) count,
          usedHeap,
          recovery,
          state.digest());
    } finally {
      if (gateway != null) gateway.close();
    }
  }

  private static long allocated(com.sun.management.ThreadMXBean bean) {
    long total = 0;
    for (long id : bean.getAllThreadIds()) {
      long n = bean.getThreadAllocatedBytes(id);
      if (n > 0) total += n;
    }
    return total;
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import static io.github.cheshmakzanoon.portfolio.thepit.Model.*;

import java.io.IOException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;

/**
 * Queue publication and CompletableFuture completion establish producer/writer/reader visibility.
 */
public final class Gateway implements AutoCloseable {
  private record Pending(Command command, CompletableFuture<Result> response) {}

  private final Book book = new Book();
  private final ConcurrentMap<String, Result> committed = new ConcurrentHashMap<>();
  private final ConcurrentLinkedQueue<Execution> executions = new ConcurrentLinkedQueue<>();
  private final Journal journal;
  private final BlockingQueue<Pending> queue;
  private final Map<String, Pending> pending = new HashMap<>();
  private final int maxCommands;
  private final Thread writer;
  private final Journal.Fault fault;
  private volatile View view;
  private volatile boolean accepting = true, closed;
  private volatile Throwable failure;

  public Gateway(Path path, String runId, int capacity, int maxCommands) throws IOException {
    this(path, runId, capacity, maxCommands, b -> {});
  }

  public Gateway(Path path, String runId, int capacity, int maxCommands, Journal.Fault fault)
      throws IOException {
    if (capacity < 1 || maxCommands < 1 || maxCommands > 1_100_000)
      throw new IllegalArgumentException();
    this.maxCommands = maxCommands;
    this.fault = fault;
    queue = new ArrayBlockingQueue<>(capacity);
    journal = new Journal(path, runId, fault);
    try {
      Checkpoint checkpoint = journal.recoveredCheckpoint();
      if (checkpoint != null) {
        book.restore(checkpoint);
        committed.putAll(checkpoint.view().results());
        executions.addAll(checkpoint.view().executions());
      }
      long restored = checkpoint == null ? 0 : checkpoint.view().sequence();
      for (Journal.Entry entry : journal.entries())
        if (entry.sequence() > restored) {
          Result r = book.apply(entry.sequence(), entry.command());
          committed.put(entry.command().key(), r);
          executions.addAll(r.executions());
        }
    } catch (RuntimeException e) {
      journal.close();
      throw new IOException("invalid replay", e);
    }
    view = book.publicView();
    writer = Thread.ofPlatform().name("thepit-single-writer").start(this::run);
  }

  public synchronized CompletableFuture<Result> submit(String identity, Command c) {
    c.validate();
    if (!Objects.equals(identity, c.accountId()))
      throw new SecurityException("account ownership required");
    Result previous = committed.get(c.key());
    if (previous != null)
      return CompletableFuture.completedFuture(
          previous.commandHash().equals(c.hash())
              ? previous
              : new Result(previous.sequence(), "CONFLICT", c.hash(), List.of()));
    Pending existing = pending.get(c.key());
    if (existing != null)
      return existing.command().hash().equals(c.hash())
          ? existing.response()
          : CompletableFuture.completedFuture(new Result(0, "CONFLICT", c.hash(), List.of()));
    if (!accepting)
      return CompletableFuture.failedFuture(
          new IllegalStateException("RECOVERY_REQUIRED_OR_CLOSED", failure));
    if (committed.size() + pending.size() >= maxCommands)
      return CompletableFuture.failedFuture(new RejectedExecutionException("RUN_CAP"));
    if (pending.size() >= queue.remainingCapacity() + queue.size())
      return CompletableFuture.failedFuture(new RejectedExecutionException("OVERLOADED_RETRYABLE"));
    Pending next = new Pending(c, new CompletableFuture<>());
    pending.put(c.key(), next);
    if (!queue.offer(next)) {
      pending.remove(c.key());
      next.response().completeExceptionally(new RejectedExecutionException("OVERLOADED_RETRYABLE"));
    }
    return next.response();
  }

  private void run() {
    try {
      while (!closed || !queue.isEmpty()) {
        Pending next = queue.poll(50, TimeUnit.MILLISECONDS);
        if (next == null) continue;
        long sequence = view.sequence() + 1;
        journal.appendAndForce(sequence, next.command());
        Result result = book.apply(sequence, next.command());
        committed.put(next.command().key(), result);
        executions.addAll(result.executions());
        view = book.publicView();
        fault.at("AFTER_APPLY");
        synchronized (this) {
          pending.remove(next.command().key());
          next.response().complete(result);
          notifyAll();
        }
      }
    } catch (Throwable e) {
      synchronized (this) {
        failure = e;
        accepting = false;
        pending
            .values()
            .forEach(
                p ->
                    p.response()
                        .completeExceptionally(new IllegalStateException("RECOVERY_REQUIRED", e)));
        pending.clear();
        queue.clear();
        notifyAll();
      }
    }
  }

  public View read(long minimumSequence, Duration timeout)
      throws InterruptedException, TimeoutException {
    long deadline = System.nanoTime() + timeout.toNanos();
    synchronized (this) {
      while (view.sequence() < minimumSequence) {
        long remaining = deadline - System.nanoTime();
        if (remaining <= 0) throw new TimeoutException("minimum sequence not applied");
        if (failure != null) throw new IllegalStateException("RECOVERY_REQUIRED", failure);
        TimeUnit.NANOSECONDS.timedWait(this, remaining);
      }
      return view;
    }
  }

  public Result result(String identity, String commandId) {
    return committed.get(identity + ":" + commandId);
  }

  public View view() {
    return view;
  }

  public synchronized View fullView() {
    if (!pending.isEmpty()) throw new IllegalStateException("full state requires idle gateway");
    return book.view();
  }

  public java.util.List<Execution> executions(
      String account, int offset, int limit, long maximumSequence) {
    return executions.stream()
        .filter(
            e ->
                e.sequence() <= maximumSequence
                    && (e.makerAccount().equals(account) || e.takerAccount().equals(account)))
        .skip(offset)
        .limit(limit)
        .toList();
  }

  public boolean healthy() {
    return accepting && failure == null;
  }

  public int queueDepth() {
    return queue.size();
  }

  public void snapshot() throws IOException {
    synchronized (this) {
      if (!pending.isEmpty()) throw new IllegalStateException("snapshot requires idle gateway");
      journal.snapshot(book.checkpoint());
    }
  }

  public void close() throws IOException {
    synchronized (this) {
      accepting = false;
      closed = true;
    }
    try {
      writer.join(10_000);
      if (writer.isAlive()) throw new IOException("writer failed to stop");
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new IOException(e);
    }
    journal.close();
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import static io.github.cheshmakzanoon.portfolio.thepit.Model.*;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.springframework.security.oauth2.core.*;
import org.springframework.security.oauth2.jwt.*;

/** Minimal loopback HTTP adapter; matching remains exclusively in Gateway's writer. */
public final class HttpApi implements AutoCloseable {
  private final ObjectMapper json =
      new ObjectMapper()
          .disable(com.fasterxml.jackson.databind.DeserializationFeature.ACCEPT_FLOAT_AS_INT)
          .enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
          .enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
  private final Gateway gateway;
  private final HttpServer server;
  private final ThreadPoolExecutor executor;
  private final JwtDecoder decoder;
  private final Semaphore handlerPermits = new Semaphore(4);
  private final boolean trusted;

  public HttpApi(
      Gateway gateway, InetSocketAddress address, String issuer, String audience, boolean trusted)
      throws IOException {
    if (trusted && !address.getAddress().isLoopbackAddress())
      throw new IllegalArgumentException("trusted local mode requires loopback binding");
    this.gateway = gateway;
    this.trusted = trusted;
    if (!trusted) {
      NimbusJwtDecoder d = JwtDecoders.fromIssuerLocation(Objects.requireNonNull(issuer));
      d.setJwtValidator(
          new DelegatingOAuth2TokenValidator<>(
              JwtValidators.createDefaultWithIssuer(issuer),
              new JwtClaimValidator<java.time.Instant>(JwtClaimNames.EXP, Objects::nonNull),
              new JwtClaimValidator<java.time.Instant>(
                  JwtClaimNames.IAT,
                  iat -> iat != null && !iat.isAfter(java.time.Instant.now().plusSeconds(60))),
              token ->
                  token.getAudience() != null && token.getAudience().contains(audience)
                      ? OAuth2TokenValidatorResult.success()
                      : OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"))));
      decoder = d;
    } else decoder = null;
    server = HttpServer.create(address, 32);
    executor =
        new ThreadPoolExecutor(
            4,
            4,
            0,
            TimeUnit.MILLISECONDS,
            new ArrayBlockingQueue<>(64),
            new ThreadPoolExecutor.CallerRunsPolicy());
    server.setExecutor(executor);
    server.createContext("/", this::handle);
    server.start();
  }

  int activeRequests() {
    return 4 - handlerPermits.availablePermits();
  }

  public int port() {
    return server.getAddress().getPort();
  }

  private void handle(HttpExchange x) throws IOException {
    if (!handlerPermits.tryAcquire()) {
      try {
        send(x, 429, Map.of("code", "OVERLOADED_RETRYABLE"));
      } finally {
        x.close();
      }
      return;
    }
    try {
      if (x.getRequestURI().getPath().equals("/health")) {
        send(x, gateway.healthy() ? 200 : 503, Map.of("healthy", gateway.healthy()));
        return;
      }
      String identity;
      Set<String> scopes;
      if (trusted) {
        identity = x.getRequestHeaders().getFirst("X-Demo-Account");
        scopes = Set.of("thepit:read", "thepit:write", "thepit:admin");
      } else {
        String auth = x.getRequestHeaders().getFirst("Authorization");
        if (auth == null || !auth.startsWith("Bearer ")) {
          send(x, 401, Map.of("code", "UNAUTHENTICATED"));
          return;
        }
        Jwt token = decoder.decode(auth.substring(7));
        identity = token.getSubject();
        String scope = token.getClaimAsString("scope");
        scopes = scope == null ? Set.of() : Set.copyOf(Arrays.asList(scope.split(" ")));
      }
      if (!identifier(identity)) {
        send(x, 401, Map.of("code", "UNAUTHENTICATED"));
        return;
      }
      String path = x.getRequestURI().getPath(), method = x.getRequestMethod();
      boolean write = method.equals("POST");
      if (!scopes.contains(write ? "thepit:write" : "thepit:read")) {
        send(x, 403, Map.of("code", "SCOPE_REQUIRED"));
        return;
      }
      if (path.equals("/commands") && write) {
        byte[] body = x.getRequestBody().readNBytes(65537);
        if (body.length > 65536) {
          send(x, 413, Map.of("code", "BODY_LIMIT"));
          return;
        }
        com.fasterxml.jackson.databind.JsonNode tree = json.readTree(body);
        if (!(tree instanceof com.fasterxml.jackson.databind.node.ObjectNode object))
          throw new IllegalArgumentException();
        if (object.path("type").asText().equals("REPLACE")) {
          if (!object.has("newRemainingQtyLots") || object.has("quantityLots"))
            throw new IllegalArgumentException("replacement requires newRemainingQtyLots");
          object.set("quantityLots", object.remove("newRemainingQtyLots"));
        }
        Command c = json.treeToValue(tree, Command.class);
        c.validate();
        if (!identity.equals(c.accountId())
            || (c.type() == Type.INIT && !scopes.contains("thepit:admin"))) {
          send(x, 403, Map.of("code", "OWNERSHIP_REQUIRED"));
          return;
        }
        Result r = gateway.submit(identity, c).get(3, TimeUnit.SECONDS);
        send(x, r.code().equals("CONFLICT") ? 409 : 200, r);
      } else if (path.startsWith("/commands/") && method.equals("GET")) {
        String id = path.substring("/commands/".length());
        if (!identifier(id)) throw new IllegalArgumentException();
        Result r = gateway.result(identity, id);
        send(x, r == null ? 404 : 200, r == null ? Map.of("code", "NOT_FOUND") : r);
      } else if (path.equals("/book") && method.equals("GET")) {
        Map<String, String> q = query(x);
        int depth = boundedInt(q, "depth", 20, 1, 100);
        long minimum = Long.parseLong(q.getOrDefault("minimumSequence", "0"));
        View v = gateway.read(minimum, Duration.ofSeconds(2));
        send(
            x,
            200,
            Map.of(
                "lastAppliedSequence",
                v.sequence(),
                "bids",
                v.orders().stream().filter(o -> o.side() == Side.BUY).limit(depth).toList(),
                "asks",
                v.orders().stream().filter(o -> o.side() == Side.SELL).limit(depth).toList()));
      } else if (path.equals("/account") && method.equals("GET")) {
        View v = gateway.view();
        send(
            x,
            200,
            Map.of(
                "lastAppliedSequence",
                v.sequence(),
                "balance",
                v.accounts().getOrDefault(identity, new Balance(0, 0, 0, 0))));
      } else if (path.equals("/executions") && method.equals("GET")) {
        Map<String, String> q = query(x);
        int offset = boundedInt(q, "offset", 0, 0, Integer.MAX_VALUE),
            limit = boundedInt(q, "limit", 20, 1, 100);
        View v = gateway.view();
        send(
            x,
            200,
            Map.of(
                "lastAppliedSequence",
                v.sequence(),
                "executions",
                gateway.executions(identity, offset, limit, v.sequence())));
      } else send(x, 404, Map.of("code", "NOT_FOUND"));
    } catch (JwtException e) {
      send(x, 401, Map.of("code", "INVALID_TOKEN"));
    } catch (SecurityException e) {
      send(x, 403, Map.of("code", "OWNERSHIP_REQUIRED"));
    } catch (TimeoutException e) {
      send(x, 202, Map.of("code", "OUTCOME_UNKNOWN_QUERY_STABLE_ID"));
    } catch (ExecutionException e) {
      send(
          x,
          e.getCause() instanceof RejectedExecutionException ? 429 : 503,
          Map.of(
              "code",
              e.getCause() instanceof RejectedExecutionException
                  ? "OVERLOADED_RETRYABLE"
                  : "RECOVERY_REQUIRED"));
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      send(x, 503, Map.of("code", "INTERRUPTED"));
    } catch (IllegalArgumentException | IOException e) {
      send(x, 400, Map.of("code", "INVALID_REQUEST"));
    } catch (RuntimeException e) {
      send(x, 503, Map.of("code", "UNAVAILABLE"));
    } finally {
      handlerPermits.release();
      x.close();
    }
  }

  private Map<String, String> query(HttpExchange x) {
    Map<String, String> result = new HashMap<>();
    String q = x.getRequestURI().getRawQuery();
    if (q != null)
      for (String pair : q.split("&")) {
        String[] kv = pair.split("=", 2);
        result.put(kv[0], kv.length == 2 ? kv[1] : "");
      }
    return result;
  }

  private int boundedInt(Map<String, String> q, String key, int def, int min, int max) {
    int value = Integer.parseInt(q.getOrDefault(key, "" + def));
    if (value < min || value > max) throw new IllegalArgumentException();
    return value;
  }

  private void send(HttpExchange x, int status, Object body) throws IOException {
    byte[] bytes = json.writeValueAsBytes(body);
    x.getResponseHeaders().set("Content-Type", "application/json");
    x.sendResponseHeaders(status, bytes.length);
    x.getResponseBody().write(bytes);
  }

  public void close() {
    server.stop(0);
    executor.shutdownNow();
  }

  public static void main(String[] args) throws Exception {
    PathConfig config = PathConfig.parse(args);
    try (Gateway gateway = new Gateway(config.path(), config.runId(), 256, 1_100_000);
        HttpApi api =
            new HttpApi(
                gateway,
                new InetSocketAddress("127.0.0.1", config.port()),
                config.issuer(),
                "thepit",
                config.trusted())) {
      System.out.println(
          "ThePit API listening on loopback:"
              + api.port()
              + " mode="
              + (config.trusted() ? "trusted-local-demo" : "protected"));
      Runtime.getRuntime()
          .addShutdownHook(
              new Thread(
                  () -> {
                    api.close();
                    try {
                      gateway.close();
                    } catch (IOException e) {
                      System.err.println("journal close failed");
                    }
                  }));
      new CountDownLatch(1).await();
    }
  }

  private record PathConfig(
      java.nio.file.Path path, String runId, int port, String issuer, boolean trusted) {
    static PathConfig parse(String[] args) {
      if (args.length < 3)
        throw new IllegalArgumentException(
            "usage: HttpApi journal runId port [issuer|trusted-local-demo]");
      String mode = args.length > 3 ? args[3] : "";
      return new PathConfig(
          java.nio.file.Path.of(args[0]),
          args[1],
          Integer.parseInt(args[2]),
          mode.equals("trusted-local-demo") ? null : mode,
          mode.equals("trusted-local-demo"));
    }
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import static io.github.cheshmakzanoon.portfolio.thepit.Model.*;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32C;

/** Complete records are immutable; only an incomplete final frame is truncated on recovery. */
public final class Journal implements AutoCloseable {
  public static final int HEADER = 24,
      MAX_PAYLOAD = 65536,
      MAX_SNAPSHOT = 16 * 1024 * 1024,
      MAX_ENTRIES = 1_100_000;
  private static final int MAGIC = 0x4d434f52, VERSION = 1;
  private static final ObjectMapper JSON =
      new ObjectMapper()
          .disable(com.fasterxml.jackson.databind.DeserializationFeature.ACCEPT_FLOAT_AS_INT)
          .enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
          .enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);

  public interface Fault {
    void at(String boundary) throws IOException;
  }

  public record Entry(long sequence, Command command) {}

  public record Payload(String runId, Command command) {}

  public record Snapshot(
      int version, long lastSequence, String prefixDigest, Checkpoint checkpoint) {}

  public record SnapshotEnvelope(String payload, String checksum) {}

  private final FileChannel channel;
  private final FileLock lock;
  private final String runId;
  private final Path path;
  private final Fault fault;
  private final List<Entry> entries = new ArrayList<>();
  private boolean snapshotUsed;
  private Snapshot restoredSnapshot;

  public Journal(Path path, String runId) throws IOException {
    this(path, runId, b -> {});
  }

  public Journal(Path path, String runId, Fault fault) throws IOException {
    if (!identifier(runId)) throw new IllegalArgumentException("invalid run ID");
    this.runId = runId;
    this.path = path;
    this.fault = fault;
    Files.createDirectories(path.toAbsolutePath().getParent());
    channel =
        FileChannel.open(
            path, StandardOpenOption.CREATE, StandardOpenOption.READ, StandardOpenOption.WRITE);
    FileLock acquired;
    try {
      acquired = channel.tryLock();
    } catch (OverlappingFileLockException e) {
      channel.close();
      throw new IOException("writer already locked", e);
    }
    if (acquired == null) {
      channel.close();
      throw new IOException("writer already locked");
    }
    lock = acquired;
    try {
      recover();
      validateSnapshot();
    } catch (Throwable t) {
      close();
      throw t;
    }
  }

  private static int crc(byte[] bytes, int length) {
    CRC32C c = new CRC32C();
    c.update(bytes, 0, length);
    return (int) c.getValue();
  }

  private void recover() throws IOException {
    long position = 0, size = channel.size();
    while (position < size) {
      if (entries.size() >= MAX_ENTRIES) throw new IOException("journal run cap exceeded");
      long start = position;
      if (size - position < HEADER) {
        truncate(start);
        break;
      }
      ByteBuffer h = ByteBuffer.allocate(HEADER);
      readFully(h, position);
      byte[] hb = h.array();
      h.flip();
      int magic = h.getInt(), version = h.getInt();
      long sequence = h.getLong();
      int length = h.getInt(), checksum = h.getInt();
      if (magic != MAGIC
          || version != VERSION
          || checksum != crc(hb, 20)
          || length < 1
          || length > MAX_PAYLOAD) throw new IOException("corrupt frame header at " + start);
      if (sequence != entries.size() + 1L) throw new IOException("journal sequence gap");
      if (size - position < HEADER + (long) length + 4) {
        truncate(start);
        break;
      }
      ByteBuffer data = ByteBuffer.allocate(length + 4);
      readFully(data, position + HEADER);
      data.flip();
      byte[] payload = new byte[length];
      data.get(payload);
      if (data.getInt() != crc(payload, length))
        throw new IOException("corrupt payload at " + start);
      Payload p = JSON.readValue(payload, Payload.class);
      if (!runId.equals(p.runId())) throw new IOException("run ID mismatch");
      try {
        p.command().validate();
      } catch (RuntimeException e) {
        throw new IOException("invalid durable command", e);
      }
      entries.add(new Entry(sequence, p.command()));
      position += HEADER + (long) length + 4;
    }
    channel.position(channel.size());
  }

  private void truncate(long size) throws IOException {
    channel.truncate(size);
    channel.force(true);
  }

  private void readFully(ByteBuffer b, long pos) throws IOException {
    while (b.hasRemaining()) {
      int n = channel.read(b, pos + b.position());
      if (n < 0) throw new IOException("unexpected EOF");
    }
  }

  public void appendAndForce(long sequence, Command command) throws IOException {
    if (entries.size() >= MAX_ENTRIES) throw new IOException("journal run cap exceeded");
    if (sequence != entries.size() + 1L) throw new IllegalArgumentException("sequence gap");
    fault.at("BEFORE_APPEND");
    byte[] payload = JSON.writeValueAsBytes(new Payload(runId, command));
    if (payload.length > MAX_PAYLOAD) throw new IOException("payload too large");
    ByteBuffer b = ByteBuffer.allocate(HEADER + payload.length + 4);
    b.putInt(MAGIC).putInt(VERSION).putLong(sequence).putInt(payload.length);
    b.putInt(crc(b.array(), 20));
    b.put(payload).putInt(crc(payload, payload.length));
    b.flip();
    // The first write is intentionally the header: deterministic process-crash fault boundary.
    int oldLimit = b.limit();
    b.limit(HEADER);
    while (b.hasRemaining()) channel.write(b);
    fault.at("DURING_FRAME");
    b.limit(oldLimit);
    while (b.hasRemaining()) channel.write(b);
    fault.at("BEFORE_FORCE");
    channel.force(true);
    entries.add(new Entry(sequence, command));
    fault.at("AFTER_FORCE");
  }

  public List<Entry> entries() {
    return List.copyOf(entries);
  }

  private String prefixDigest(long count) {
    StringBuilder s = new StringBuilder(runId);
    for (int i = 0; i < count; i++) {
      Entry e = entries.get(i);
      s.append('|').append(e.sequence()).append(':').append(e.command().hash());
    }
    return sha(s.toString());
  }

  public void snapshot() throws IOException {
    snapshot(null);
  }

  public void snapshot(Checkpoint checkpoint) throws IOException {
    Snapshot snapshot =
        new Snapshot(VERSION, entries.size(), prefixDigest(entries.size()), checkpoint);
    Path temporary = path.resolveSibling(path.getFileName() + ".snapshot.tmp"),
        target = snapshotPath();
    String payload = JSON.writeValueAsString(snapshot);
    byte[] bytes = JSON.writeValueAsBytes(new SnapshotEnvelope(payload, sha(payload)));
    if (bytes.length > MAX_SNAPSHOT)
      throw new IOException("snapshot exceeds 16MiB; full journal retained");
    try (FileChannel out =
        FileChannel.open(
            temporary,
            StandardOpenOption.CREATE,
            StandardOpenOption.TRUNCATE_EXISTING,
            StandardOpenOption.WRITE)) {
      ByteBuffer b = ByteBuffer.wrap(bytes);
      while (b.hasRemaining()) out.write(b);
      out.force(true);
    }
    try {
      Files.move(
          temporary, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
    } catch (AtomicMoveNotSupportedException e) {
      Files.deleteIfExists(temporary);
      throw new IOException("atomic snapshot publication unavailable; journal retained", e);
    }
    try (FileChannel directory =
        FileChannel.open(target.toAbsolutePath().getParent(), StandardOpenOption.READ)) {
      directory.force(true);
    }
  }

  private Path snapshotPath() {
    return path.resolveSibling(path.getFileName() + ".snapshot");
  }

  private void validateSnapshot() {
    if (!Files.exists(snapshotPath())) return;
    try {
      if (Files.size(snapshotPath()) > MAX_SNAPSHOT) return;
    } catch (IOException e) {
      return;
    }
    try {
      SnapshotEnvelope envelope =
          JSON.readValue(Files.readAllBytes(snapshotPath()), SnapshotEnvelope.class);
      if (!sha(envelope.payload()).equals(envelope.checksum())) return;
      Snapshot s = JSON.readValue(envelope.payload(), Snapshot.class);
      snapshotUsed =
          s.version() == VERSION
              && s.lastSequence() >= 0
              && s.lastSequence() <= entries.size()
              && s.prefixDigest().equals(prefixDigest(s.lastSequence()))
              && (s.checkpoint() == null || s.checkpoint().view().sequence() == s.lastSequence());
      if (snapshotUsed) restoredSnapshot = s;
    } catch (IOException | RuntimeException e) {
      snapshotUsed = false;
    }
  }

  public Checkpoint recoveredCheckpoint() {
    return restoredSnapshot == null ? null : restoredSnapshot.checkpoint();
  }

  public boolean validSnapshot() {
    return snapshotUsed;
  }

  public void close() throws IOException {
    try {
      if (lock.isValid()) lock.release();
    } finally {
      channel.close();
    }
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import static io.github.cheshmakzanoon.portfolio.thepit.Model.*;

import java.util.*;

/** Thread-confined indexed price-time book. All balances include held funds. */
public final class Book {
  private static final class Account {
    long cash, lots, heldCash, heldLots;
  }

  private static final class Level {
    Node first, last;
    long quantity;
  }

  private static final class Node {
    String account, id;
    Side side;
    long price, qty, priority, revision;
    Node prev, next;
    Level level;

    Order order() {
      return new Order(account, id, side, price, qty, priority, revision);
    }
  }

  private final NavigableMap<Long, Level> bids = new TreeMap<>(Comparator.reverseOrder());
  private final NavigableMap<Long, Level> asks = new TreeMap<>();
  private final Map<String, Node> index = new HashMap<>();
  private final Set<String> used = new HashSet<>();
  private final Map<String, Account> accounts = new TreeMap<>();
  private final Map<String, Result> results = new TreeMap<>();
  private final List<Execution> trades = new ArrayList<>();
  private long seq, totalCash, totalLots;
  private final int maxOpen;

  public Book() {
    this(100_000);
  }

  public Book(int maxOpen) {
    if (maxOpen < 1) throw new IllegalArgumentException();
    this.maxOpen = maxOpen;
  }

  public Result lookup(Command c) {
    Result r = results.get(c.key());
    if (r != null && !r.commandHash().equals(c.hash()))
      return new Result(r.sequence(), "CONFLICT", c.hash(), List.of());
    return r;
  }

  public Result apply(long sequence, Command c) {
    c.validate();
    if (results.size() >= 1_100_000) throw new IllegalStateException("RUN_CAP");
    if (sequence != seq + 1) throw new IllegalArgumentException("sequence gap");
    if (results.containsKey(c.key())) throw new IllegalStateException("duplicate journal identity");
    seq = sequence;
    var fills = new ArrayList<Execution>();
    String code;
    try {
      code = transition(c, fills);
    } catch (ArithmeticException e) {
      code = "OVERFLOW";
    }
    Result r = new Result(seq, code, c.hash(), fills);
    results.put(c.key(), r);
    return r;
  }

  private String transition(Command c, List<Execution> fills) {
    if (c.type() == Type.INIT) {
      if (accounts.containsKey(c.accountId())) return "ACCOUNT_EXISTS";
      long cash = Math.addExact(totalCash, c.initialCash()),
          lots = Math.addExact(totalLots, c.initialLots());
      Account a = new Account();
      a.cash = c.initialCash();
      a.lots = c.initialLots();
      accounts.put(c.accountId(), a);
      totalCash = cash;
      totalLots = lots;
      return "INITIALIZED";
    }
    Account a = accounts.get(c.accountId());
    if (a == null) return "UNKNOWN_ACCOUNT";
    Node old = index.get(c.orderKey());
    if (c.type() == Type.CANCEL) {
      if (old == null) return used.contains(c.orderKey()) ? "TERMINAL" : "NOT_FOUND";
      remove(old);
      return "CANCELED";
    }
    if (c.type() == Type.REPLACE && old == null)
      return used.contains(c.orderKey()) ? "TERMINAL" : "NOT_FOUND";
    if (c.type() == Type.NEW && used.contains(c.orderKey())) return "ORDER_ID_USED";
    if (c.type() == Type.REPLACE && c.quantityLots() == 0) {
      remove(old);
      return "CANCELED";
    }
    if (c.type() == Type.REPLACE && c.side() != old.side) return "SIDE_CHANGE";
    if (c.type() == Type.REPLACE && c.timeInForce() != Tif.GTC) return "TIF_CHANGE";
    long notional = Math.multiplyExact(c.priceTicks(), c.quantityLots());
    long reserve = c.side() == Side.BUY ? notional : c.quantityLots();
    long freed =
        old == null ? 0 : (old.side == Side.BUY ? Math.multiplyExact(old.price, old.qty) : old.qty);
    long available = c.side() == Side.BUY ? a.cash - a.heldCash : a.lots - a.heldLots;
    if (reserve > Math.addExact(available, freed)) return "RISK";
    if (c.postOnly() && crosses(c, best(opposite(c.side())))) return "POST_ONLY";
    if (c.timeInForce() == Tif.FOK && !fillable(c)) return "FOK_UNFILLED";
    // Reserve capacity conservatively before mutation; an aggressor cannot grow beyond the cap.
    if (old == null && index.size() >= maxOpen && c.timeInForce() == Tif.GTC)
      return "OPEN_ORDER_CAP";
    if (old != null && old.price == c.priceTicks() && c.quantityLots() <= old.qty) {
      long revision = Math.incrementExact(old.revision);
      release(old, Math.subtractExact(old.qty, c.quantityLots()));
      old.qty = c.quantityLots();
      old.revision = revision;
      return "REDUCED";
    }
    long revision = old == null ? 0 : Math.incrementExact(old.revision);
    if (old != null) remove(old);
    used.add(c.orderKey());
    long remaining = c.quantityLots();
    boolean self = false;
    while (remaining > 0) {
      Node maker = best(opposite(c.side()));
      if (!crosses(c, maker)) break;
      if (maker.account.equals(c.accountId())) {
        self = true;
        break;
      }
      long qty = Math.min(remaining, maker.qty), cost = Math.multiplyExact(maker.price, qty);
      Account ma = accounts.get(maker.account);
      Account buyer = c.side() == Side.BUY ? a : ma, seller = c.side() == Side.SELL ? a : ma;
      // Aggregate initialized supply <= Long.MAX_VALUE proves these additions cannot overflow.
      long buyerCash = Math.subtractExact(buyer.cash, cost),
          buyerLots = Math.addExact(buyer.lots, qty),
          sellerCash = Math.addExact(seller.cash, cost),
          sellerLots = Math.subtractExact(seller.lots, qty);
      buyer.cash = buyerCash;
      buyer.lots = buyerLots;
      seller.cash = sellerCash;
      seller.lots = sellerLots;
      release(maker, qty);
      maker.qty = Math.subtractExact(maker.qty, qty);
      remaining = Math.subtractExact(remaining, qty);
      Execution trade =
          new Execution(seq, maker.account, maker.id, c.accountId(), c.orderId(), maker.price, qty);
      trades.add(trade);
      fills.add(trade);
      if (maker.qty == 0) unlink(maker);
    }
    if (remaining > 0 && !self && c.timeInForce() == Tif.GTC) {
      Node n = new Node();
      n.account = c.accountId();
      n.id = c.orderId();
      n.side = c.side();
      n.price = c.priceTicks();
      n.qty = remaining;
      n.priority = seq;
      n.revision = revision;
      if (n.side == Side.BUY)
        a.heldCash = Math.addExact(a.heldCash, Math.multiplyExact(n.price, n.qty));
      else a.heldLots = Math.addExact(a.heldLots, n.qty);
      Level l = side(n.side).computeIfAbsent(n.price, k -> new Level());
      n.level = l;
      l.quantity = Math.addExact(l.quantity, n.qty);
      n.prev = l.last;
      if (l.last != null) l.last.next = n;
      else l.first = n;
      l.last = n;
      index.put(c.orderKey(), n);
    }
    return self
        ? "SELF_TRADE_CANCELED"
        : remaining == 0 ? "FILLED" : c.timeInForce() == Tif.GTC ? "RESTING" : "IOC_CANCELED";
  }

  private boolean fillable(Command c) {
    long left = c.quantityLots();
    for (var e : opposite(c.side()).entrySet()) {
      for (Node n = e.getValue().first; n != null; n = n.next) {
        if (!crosses(c, n) || n.account.equals(c.accountId())) return false;
        left = Math.subtractExact(left, Math.min(left, n.qty));
        if (left == 0) return true;
      }
    }
    return false;
  }

  private NavigableMap<Long, Level> side(Side s) {
    return s == Side.BUY ? bids : asks;
  }

  private NavigableMap<Long, Level> opposite(Side s) {
    return side(s == Side.BUY ? Side.SELL : Side.BUY);
  }

  private Node best(NavigableMap<Long, Level> side) {
    return side.isEmpty() ? null : side.firstEntry().getValue().first;
  }

  private boolean crosses(Command c, Node n) {
    return n != null
        && (c.side() == Side.BUY ? c.priceTicks() >= n.price : c.priceTicks() <= n.price);
  }

  private void release(Node n, long qty) {
    Account a = accounts.get(n.account);
    n.level.quantity = Math.subtractExact(n.level.quantity, qty);
    if (n.side == Side.BUY)
      a.heldCash = Math.subtractExact(a.heldCash, Math.multiplyExact(n.price, qty));
    else a.heldLots = Math.subtractExact(a.heldLots, qty);
  }

  private void remove(Node n) {
    release(n, n.qty);
    unlink(n);
  }

  private void unlink(Node n) {
    Level l = n.level;
    if (n.prev == null) l.first = n.next;
    else n.prev.next = n.next;
    if (n.next == null) l.last = n.prev;
    else n.next.prev = n.prev;
    if (l.first == null) side(n.side).remove(n.price);
    index.remove(n.account + ":" + n.id);
  }

  public Checkpoint checkpoint() {
    return new Checkpoint(view(), used);
  }

  public void restore(Checkpoint checkpoint) {
    if (seq != 0 || !accounts.isEmpty())
      throw new IllegalStateException("restore requires empty book");
    View v = checkpoint.view();
    v.accounts()
        .forEach(
            (name, b) -> {
              Account a = new Account();
              a.cash = b.cash();
              a.lots = b.lots();
              a.heldCash = b.reservedCash();
              a.heldLots = b.reservedLots();
              accounts.put(name, a);
              totalCash = Math.addExact(totalCash, a.cash);
              totalLots = Math.addExact(totalLots, a.lots);
            });
    for (Order o : v.orders().stream().sorted(Comparator.comparingLong(Order::priority)).toList()) {
      Node n = new Node();
      n.account = o.accountId();
      n.id = o.orderId();
      n.side = o.side();
      n.price = o.priceTicks();
      n.qty = o.remaining();
      n.priority = o.priority();
      n.revision = o.revision();
      Level l = side(n.side).computeIfAbsent(n.price, k -> new Level());
      n.level = l;
      l.quantity = Math.addExact(l.quantity, n.qty);
      n.prev = l.last;
      if (l.last != null) l.last.next = n;
      else l.first = n;
      l.last = n;
      index.put(n.account + ":" + n.id, n);
    }
    seq = v.sequence();
    used.addAll(checkpoint.usedOrderIds());
    results.putAll(v.results());
    trades.addAll(v.executions());
  }

  public View publicView() {
    var balances = new TreeMap<String, Balance>();
    accounts.forEach(
        (k, a) -> balances.put(k, new Balance(a.cash, a.lots, a.heldCash, a.heldLots)));
    var depth = new ArrayList<Order>();
    bids.forEach(
        (price, level) -> depth.add(new Order("", "depth", Side.BUY, price, level.quantity, 0, 0)));
    asks.forEach(
        (price, level) ->
            depth.add(new Order("", "depth", Side.SELL, price, level.quantity, 0, 0)));
    return new View(seq, balances, depth, List.of(), Map.of());
  }

  public View view() {
    var balances = new TreeMap<String, Balance>();
    accounts.forEach(
        (k, a) -> balances.put(k, new Balance(a.cash, a.lots, a.heldCash, a.heldLots)));
    var orders =
        index.values().stream()
            .map(Node::order)
            .sorted(Comparator.comparing(Order::accountId).thenComparing(Order::orderId))
            .toList();
    return new View(seq, balances, orders, trades, results);
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;

public final class Model {
  private Model() {}

  public enum Type {
    INIT,
    NEW,
    CANCEL,
    REPLACE
  }

  public enum Side {
    BUY,
    SELL
  }

  public enum Tif {
    GTC,
    IOC,
    FOK
  }

  public record Command(
      String clientCommandId,
      String accountId,
      Type type,
      String orderId,
      Side side,
      long priceTicks,
      long quantityLots,
      Tif timeInForce,
      boolean postOnly,
      long initialCash,
      long initialLots) {
    public String key() {
      return accountId + ":" + clientCommandId;
    }

    public String orderKey() {
      return accountId + ":" + orderId;
    }

    public String hash() {
      return sha(toString());
    }

    public void validate() {
      if (!identifier(clientCommandId) || !identifier(accountId) || type == null)
        throw new IllegalArgumentException("invalid command identity/type");
      if (type != Type.INIT && !identifier(orderId))
        throw new IllegalArgumentException("invalid order identity");
      if (type == Type.INIT && (initialCash < 0 || initialLots < 0))
        throw new IllegalArgumentException("negative initial balance");
      if ((type == Type.NEW || type == Type.REPLACE)
          && (side == null
              || timeInForce == null
              || priceTicks <= 0
              || quantityLots < 0
              || (type == Type.NEW && quantityLots == 0)
              || (postOnly && timeInForce != Tif.GTC)))
        throw new IllegalArgumentException("invalid order fields");
    }
  }

  public static boolean identifier(String s) {
    return s != null && s.matches("[a-zA-Z0-9_-]{1,64}");
  }

  public static long decimalPrice(String text) {
    return new BigDecimal(text).movePointRight(2).longValueExact();
  }

  public record Balance(long cash, long lots, long reservedCash, long reservedLots) {}

  public record Order(
      String accountId,
      String orderId,
      Side side,
      long priceTicks,
      long remaining,
      long priority,
      long revision) {}

  public record Execution(
      long sequence,
      String makerAccount,
      String makerOrder,
      String takerAccount,
      String takerOrder,
      long priceTicks,
      long lots) {}

  public record Result(long sequence, String code, String commandHash, List<Execution> executions) {
    public Result {
      executions = List.copyOf(executions);
    }
  }

  public record View(
      long sequence,
      Map<String, Balance> accounts,
      List<Order> orders,
      List<Execution> executions,
      Map<String, Result> results) {
    public View {
      accounts = Map.copyOf(accounts);
      orders = List.copyOf(orders);
      executions = List.copyOf(executions);
      results = Map.copyOf(results);
    }

    public String digest() {
      return sha(
          sequence
              + "|"
              + new java.util.TreeMap<>(accounts)
              + "|"
              + orders
              + "|"
              + executions
              + "|"
              + new java.util.TreeMap<>(results));
    }
  }

  public record Checkpoint(View view, java.util.Set<String> usedOrderIds) {
    public Checkpoint {
      usedOrderIds = java.util.Set.copyOf(usedOrderIds);
    }
  }

  public static String sha(String s) {
    try {
      return HexFormat.of()
          .formatHex(
              MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));
    } catch (java.security.NoSuchAlgorithmException e) {
      throw new AssertionError(e);
    }
  }
}

package io.github.cheshmakzanoon.portfolio.thepit;

import java.nio.file.*;
import java.util.concurrent.TimeUnit;

/** Child process pauses at a selected boundary; the parent issues SIGKILL/destroyForcibly. */
public final class CrashProcess {
  private CrashProcess() {}

  public static void main(String[] args) throws Exception {
    Path journal = Path.of(args[0]), signal = Path.of(args[1]);
    String boundary = args[2];
    java.util.concurrent.atomic.AtomicBoolean armed =
        new java.util.concurrent.atomic.AtomicBoolean();
    try (Gateway gateway =
        new Gateway(
            journal,
            "demo",
            64,
            1000,
            b -> {
              if (armed.get() && b.equals(boundary)) {
                Files.writeString(signal, b);
                try {
                  new java.util.concurrent.CountDownLatch(1).await();
                } catch (InterruptedException e) {
                  Thread.currentThread().interrupt();
                  throw new java.io.IOException(e);
                }
              }
            })) {
      var commands = Demo.fixture();
      for (var c : commands.subList(0, 11))
        gateway.submit(c.accountId(), c).get(5, TimeUnit.SECONDS);
      armed.set(true);
      gateway.submit("carol", commands.getLast()).get(30, TimeUnit.SECONDS);
    }
  }
}
